let ffm_active_user_id = null;

// Cloud login (Supabase) was intentionally disabled — AutoList Pro is
// local-only. mediaDB still scopes every blob key under a user id
// (users/<uid>/listings/...), so without a fallback here every photo/video
// save silently throws "Attempted to create listing blob without active
// user" forever. This is the stable local id used in place of a real login.
const FFM_LOCAL_USER_ID = 'local-user';

async function ffmInitActiveUserContext() {
  try {
    const r = await new Promise((resolve) => { try { chrome.storage.local.get(['ffm_active_user_id'], resolve); } catch (e) { resolve({}); } });
    ffm_active_user_id = (r && r.ffm_active_user_id) ? r.ffm_active_user_id : null;

    if (!ffm_active_user_id) {
      ffm_active_user_id = FFM_LOCAL_USER_ID;
      try { await new Promise((resolve) => { try { chrome.storage.local.set({ ffm_active_user_id: FFM_LOCAL_USER_ID }, resolve); } catch (e) { resolve(); } }); } catch (e) {}
      try { console.log('[AutoList Pro] No stored active user id — defaulted to local user context:', FFM_LOCAL_USER_ID); } catch (e) {}
    } else {
      try { console.log('[AutoList Pro] Active user context:', ffm_active_user_id); } catch (e) {}
    }

    // Mirror into window for easy access by other popup modules
    try { window.ffmActiveUserId = ffm_active_user_id; } catch (e) {}
    try { window.ffmActiveUserEmail = (r && r.ffm_active_user_email) ? r.ffm_active_user_email : null; } catch (e) {}
    try { window.__ffmActiveUser = ffm_active_user_id; } catch (e) {}
  } catch (e) {
    try { console.error('[AutoList Pro] Failed to init active user context', e); } catch (e) {}
    ffm_active_user_id = null;
  }
}

function ffmGetActiveUserIdSync() {
  return ffm_active_user_id;
}

