// Storage meter: shows local chrome.storage.local usage (drop-in)
async function ffmUpdateStorageMeter() {
  try {
    const all = await new Promise((res) => { try { chrome.storage.local.get(null, res); } catch (e) { res({}); } });
    const bytes = JSON.stringify(all || {}).length;
    const kb = Math.round(bytes / 1024);
    const maxKB = 5120; // Chrome local storage soft limit (~5MB)
    const pct = Math.min(100, Math.round((kb / maxKB) * 100));

    const bar = document.getElementById('ffm-storage-meter-bar');
    const wrap = document.getElementById('ffm-storage-meter-wrap');
    if (!bar || !wrap) return;

    bar.style.width = `${pct}%`;
    wrap.title = `Storage used: ${kb} KB / ${maxKB} KB`;

    if (pct < 60) bar.style.background = '#22c55e';
    else if (pct < 80) bar.style.background = '#f59e0b';
    else bar.style.background = '#ef4444';
    try { await ffmCheckStorageThresholds(pct, kb, maxKB); } catch (e) { console.warn('[AutoList Pro] ffmCheckStorageThresholds failed', e); }
  } catch (e) {
    console.warn('[AutoList Pro] Storage meter failed', e);
  }
}

// Expose for debugging
try { window.ffmUpdateStorageMeter = ffmUpdateStorageMeter; } catch (e) {}

// Run once after UI render (small delay to allow layout to settle)
setTimeout(() => { try { ffmUpdateStorageMeter(); } catch (e) {} }, 350);
// Check thresholds and notify once when crossing 70/80/90
async function ffmCheckStorageThresholds(pct, kb, maxKB) {
  try {
    const r = await new Promise((res) => { try { chrome.storage.local.get('ffm_storage_last_notified_pct', res); } catch (e) { res({}); } });
    const last = (r && typeof r.ffm_storage_last_notified_pct === 'number') ? r.ffm_storage_last_notified_pct : 0;
    const thresholds = [70, 80, 90];
    const crossed = thresholds.find(t => pct >= t && last < t);
    if (!crossed) return;
    await new Promise((res) => { try { chrome.storage.local.set({ ffm_storage_last_notified_pct: crossed }, () => res()); } catch (e) { res(); } });
    ffmShowStorageWarning(crossed, kb, maxKB);
  } catch (e) {
    console.warn('[AutoList Pro] ffmCheckStorageThresholds error', e);
  }
}

// Show storage warning toast with action button
function ffmShowStorageWarning(level, kb, maxKB) {
  try {
    let title = '';
    let body = '';
    let type = 'info';
    if (level === 70) {
      title = 'Storage getting full';
      body = 'AutoList Pro has accumulated old publish and schedule traces.\nThese are safe to remove and not required for listings or cloud sync.';
      type = 'info';
    } else if (level === 80) {
      title = 'Storage nearing limit';
      body = 'Cleaning old trace data can free space and prevent future issues.\nThis will not affect listings, media, or settings.';
      type = 'info';
    } else {
      title = 'Storage almost full';
      body = 'AutoList Pro may become unstable if storage fills completely.\nWe recommend cleaning unused trace data now.';
      type = 'error';
    }

    const initialText = `${title}\n\n${body}\n\nUsed: ${kb} KB / ${maxKB} KB`;
    const t = showToastPinned(initialText, { type });

    // Append action button
    try {
      const btn = document.createElement('button');
      btn.textContent = 'Clean old traces';
      btn.style.marginLeft = '12px';
      btn.style.padding = '6px 10px';
      btn.style.borderRadius = '6px';
      btn.style.border = 'none';
      btn.style.cursor = 'pointer';
      btn.style.background = '#efefef';
      btn.onclick = async () => {
        try {
          t.setText('Cleaning old traces...');
          const resp = await ffmCleanOldTraces();
          t.setText(`Cleaned ${resp && resp.removed ? resp.removed : 0} keys`);
          setTimeout(() => { try { t.dismiss(); } catch (e) {} }, 1600);
          // Refresh meter after cleaning
          try { setTimeout(() => { ffmUpdateStorageMeter(); }, 400); } catch (e) {}
        } catch (e) {
          try { t.setText('Clean failed'); } catch (ee) {}
          console.warn('[AutoList Pro] ffmCleanOldTraces failed', e);
        }
      };
      if (t && t.dismiss) {
        // attach to the toast DOM element
        try { t.el || (t.el = t); t.el.appendChild(btn); } catch (e) { try { t.appendChild(btn); } catch (ee) {} }
      } else {
        try { t.appendChild(btn); } catch (e) {}
      }
    } catch (e) { console.warn('[AutoList Pro] ffmShowStorageWarning button attach failed', e); }
  } catch (e) { console.warn('[AutoList Pro] ffmShowStorageWarning failed', e); }
}

// Trigger background cleaning for old traces; returns { removed, keys }
function ffmCleanOldTraces() {
  return new Promise((resolve) => {
    try {
      chrome.runtime.sendMessage({ action: 'ffm_clean_old_traces' }, (resp) => {
        try { resolve(resp || { removed: 0, keys: [] }); } catch (e) { resolve({ removed: 0, keys: [] }); }
      });
    } catch (e) { resolve({ removed: 0, keys: [] }); }
  });
}

