// Local backup folder (File System Access API) — mirrors every saved
// listing to a real folder on disk. See lib/fs_local.js.
(function () {
  function setStatusText(text) { try { const el = document.getElementById('local-folder-status'); if (el) el.textContent = text; } catch (e) {} }

  async function refreshStatusQuiet() {
    try {
      if (!window.AutoListLocal) return;
      const { handle, granted } = await window.AutoListLocal.getFolderQuiet();
      if (!handle) { setStatusText('Not connected — listings save to the extension only.'); return; }
      setStatusText(granted ? `Connected: ${handle.name}` : `Connection needs reconnecting — click "Choose Folder…" (was: ${handle.name})`);
    } catch (e) {}
  }

  document.addEventListener('DOMContentLoaded', refreshStatusQuiet);
  try { setTimeout(refreshStatusQuiet, 200); } catch (e) {}

  document.addEventListener('click', async (ev) => {
    try {
      const btn = ev.target && ev.target.closest ? ev.target.closest('#local-folder-choose-btn') : null;
      if (!btn) return;
      if (!window.AutoListLocal || !window.showDirectoryPicker) {
        setStatusText('Not supported in this browser.');
        return;
      }
      setStatusText('Waiting for folder selection…');
      try {
        const root = await window.AutoListLocal.chooseFolder();
        setStatusText(`Connected: ${root.name}`);
        try { if (window.showToast) window.showToast('Local backup folder connected: ' + root.name, 'success'); } catch (e) {}
      } catch (e) {
        // AbortError = user cancelled the picker; not a real failure.
        if (e && e.name !== 'AbortError') {
          console.warn('[AutoList Pro] chooseFolder failed', e);
          setStatusText('Could not connect to folder — try again.');
        } else {
          refreshStatusQuiet();
        }
      }
    } catch (e) {}
  });

  // Best-effort export of one listing to the local folder; called right
  // after a listing is saved. Never blocks or fails the actual save.
  window.ffmExportListingToLocalFolder = async function (listing) {
    try {
      if (!window.AutoListLocal) return false;
      const { handle, granted } = await window.AutoListLocal.getFolderQuiet();
      if (!handle || !granted) return false; // not connected — nothing to do
      await window.AutoListLocal.writeListing(listing);
      const ok = await window.AutoListLocal.verifyListingWritten(listing);
      if (!ok) { try { if (window.showToast) window.showToast('Local folder save could not be verified for "' + (listing && listing.inventoryName) + '"', 'error'); } catch (e) {} }
      return ok;
    } catch (e) {
      console.warn('[AutoList Pro] ffmExportListingToLocalFolder failed', e);
      try { if (window.showToast) window.showToast('Local folder save failed: ' + String(e && e.message || e), 'error'); } catch (er) {}
      return false;
    }
  };

  // Resolves a listing's images/videos to real Blobs before export: stored
  // JSON may contain full data URLs, but older/large ones can be stubbed
  // ({__ffm_data_stub:true}) with the actual bytes only in IndexedDB
  // (ffmMediaDB) — same DB-preferred pattern saveListingImages/Videos use.
  async function ffmResolveListingMediaForExport(listing) {
    const out = Object.assign({}, listing);
    const listingId = listing.listingId || listing.id;
    let dbMedia = null;
    // Always consult mediaDB, not just when `images`/`videos` look empty or
    // stubbed — for a lot of listings in this codebase, `listing.images` is
    // empty/absent entirely and the real photos only ever existed as blobs
    // in mediaDB (referenced by `localImageKeys`), never as an array on the
    // listing object itself. Skipping the DB lookup in that case silently
    // exported zero photos even though `imageCount`/`localImageKeys` showed
    // real media existed (found empirically 2026-08-01: 119 exported
    // listings, 0 photo files written, despite imageCount:2+ on every one).
    if (listingId && typeof ffmMediaDB !== 'undefined' && ffmMediaDB && typeof ffmMediaDB.getBlobsForListing === 'function') {
      try { dbMedia = await ffmMediaDB.getBlobsForListing(listingId); } catch (e) { dbMedia = null; }
    }
    const resolveArr = (arr, dbArr) => {
      const src = Array.isArray(arr) ? arr : [];
      const db = Array.isArray(dbArr) ? dbArr.slice().sort((a, b) => (Number(a && a.index) || 0) - (Number(b && b.index) || 0)) : [];
      if (src.length) {
        return src.map((item, i) => {
          if (item && !item.__ffm_data_stub) return item; // already a real data:/blob: string
          const rec = db[i] || db.find((r) => r && r.index === i);
          return (rec && rec.blob) ? rec.blob : null;
        }).filter(Boolean);
      }
      // `listing.images`/`listing.videos` had nothing at all — fall back to
      // whatever mediaDB actually has for this listing, in index order.
      return db.map((r) => r && r.blob).filter(Boolean);
    };
    out.images = resolveArr(listing.images, dbMedia && dbMedia.images);
    out.videos = resolveArr(listing.videos, dbMedia && dbMedia.videos);
    return out;
  }
  try { window.ffmResolveListingMediaForExport = ffmResolveListingMediaForExport; } catch (e) {}

  // Plain-language activity log — appended to activity_log.txt in the local
  // backup folder (skipped silently if no folder is connected; the in-popup
  // toast/progress line is still shown either way). Used by Export and by
  // bulk Delete/Relist.
  window.ffmWriteActivityLog = async function (lines) {
    try {
      if (!window.AutoListLocal) return;
      const { handle, granted } = await window.AutoListLocal.getFolderQuiet();
      if (!handle || !granted) return;
      await window.AutoListLocal.appendLogLines(lines);
    } catch (e) { console.warn('[AutoList Pro] ffmWriteActivityLog failed', e); }
  };
  window.ffmLogTimestamp = function () {
    return new Date().toLocaleString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true, month: 'short', day: 'numeric', year: 'numeric' });
  };

  window.ffmExportAllListingsToLocalFolder = async function () {
    const progressEl = document.getElementById('local-folder-export-progress');
    const setProgress = (text) => { try { if (progressEl) { progressEl.style.display = text ? 'block' : 'none'; progressEl.textContent = text || ''; } } catch (e) {} };
    try {
      if (!window.AutoListLocal) { setProgress('Not supported in this browser.'); return; }
      const { handle, granted } = await window.AutoListLocal.getFolderQuiet();
      if (!handle || !granted) { setProgress('Choose a folder first.'); return; }

      const listings = await new Promise((res) => storageGet({ listings: [] }, (r) => res(Array.isArray(r.listings) ? r.listings : [])));
      if (!listings.length) { setProgress('No saved listings to export.'); return; }

      let done = 0, failed = 0;
      for (const listing of listings) {
        setProgress(`Exporting ${done + failed + 1} of ${listings.length}…`);
        try {
          const resolved = await ffmResolveListingMediaForExport(listing);
          await window.AutoListLocal.writeListing(resolved);
          done++;
        } catch (e) {
          console.warn('[AutoList Pro] export failed for listing', listing && listing.inventoryName, e);
          failed++;
        }
      }
      const summary = failed ? `Exported ${done} listing(s), ${failed} failed — see console.` : `Exported ${done} listing(s) to ${handle.name}.`;
      setProgress(summary);
      try { if (window.showToast) window.showToast(summary, failed ? 'error' : 'success'); } catch (e) {}
    } catch (e) {
      console.warn('[AutoList Pro] ffmExportAllListingsToLocalFolder failed', e);
      setProgress('Export failed — see console.');
    }
  };

  // Lets the user pick exactly which saved listings to export, instead of
  // always exporting everything. Opens the shared checkbox picker
  // (showBulkListingActionModal) pre-checked for every listing, with quick
  // buttons for "Only Active Listings" / "Only Listings Not Published Yet".
  // Also writes a plain-language summary to activity_log.txt.
  window.ffmExportSelectedListingsToLocalFolder = async function () {
    const progressEl = document.getElementById('local-folder-export-progress');
    const setProgress = (text) => { try { if (progressEl) { progressEl.style.display = text ? 'block' : 'none'; progressEl.textContent = text || ''; } } catch (e) {} };
    try {
      if (!window.AutoListLocal) { setProgress('Not supported in this browser.'); return; }
      let { handle, granted } = await window.AutoListLocal.getFolderQuiet();
      if (!handle || !granted) {
        // This button lives in the Saved Listings toolbar now, away from the
        // Local Backup Folder menu section — a user here may never have
        // opened that menu, so don't just print a message there where they
        // won't see it. Offer to connect a folder right now instead.
        try { if (window.showToast) window.showToast('No backup folder connected yet — pick one now.', 'info'); } catch (e) {}
        try {
          const root = await window.AutoListLocal.chooseFolder();
          handle = root; granted = true;
          try { if (window.showToast) window.showToast('Connected: ' + root.name, 'success'); } catch (e) {}
          try { if (typeof refreshStatusQuiet === 'function') refreshStatusQuiet(); } catch (e) {}
        } catch (e) {
          if (e && e.name !== 'AbortError') console.warn('[AutoList Pro] chooseFolder failed (from Export)', e);
          setProgress('');
          return; // user cancelled the picker or it failed — nothing more to do
        }
      }

      const listings = await new Promise((res) => storageGet({ listings: [] }, (r) => res(Array.isArray(r.listings) ? r.listings : [])));
      if (!listings.length) { setProgress('No saved listings to export.'); return; }

      const entries = listings.map((l, i) => {
        const active = (typeof ffmIsListingActive === 'function') ? !!ffmIsListingActive(l) : !!(l && (l.isActive || l.active));
        const name = (l && (l.inventoryName || l.title)) || `Listing ${i + 1}`;
        const daysAgo = (l && typeof l.fbListedDays === 'number') ? l.fbListedDays : (l && typeof l.listedDaysAgo === 'number' ? l.listedDaysAgo : null);
        return {
          id: String((l && (l.listingId || l.id)) || i),
          label: name + (active ? '  —  Active on Facebook' : '  —  Not published yet'),
          isActive: active,
          daysAgo
        };
      });

      const selectedIds = await window.showBulkListingActionModal(entries, {
        title: `Choose What To Export (${entries.length} saved listings)`,
        helpText: 'Everything is checked by default. Uncheck anything you don’t want, or use a button below.',
        confirmLabel: 'Export Checked Listings',
        showActiveFilter: true,
        showUnlistedFilter: true,
        showDaysFilter: false,
        defaultChecked: true
      });
      if (selectedIds === null) { setProgress(''); return; }
      if (!selectedIds.length) { setProgress('Nothing was checked, so nothing was exported.'); return; }

      const idSet = new Set(selectedIds);
      const toExport = listings.filter((l, i) => idSet.has(String((l && (l.listingId || l.id)) || i)));

      const cancelToken = { cancelled: false };
      const progressBar = ffmShowBulkOpProgress({ text: `Exporting 1 of ${toExport.length}…` });
      progressBar.onCancel(() => {
        cancelToken.cancelled = true;
        progressBar.setText('Cancelling — finishing the current listing, then stopping…');
        progressBar.hideCancelButton();
      });

      let done = 0, failed = 0, cancelled = false;
      const logLines = [`--- Export started ${window.ffmLogTimestamp()} ---`];
      for (const listing of toExport) {
        if (cancelToken.cancelled) { cancelled = true; break; }
        const name = (listing && (listing.inventoryName || listing.title)) || 'Untitled listing';
        setProgress(`Exporting ${done + failed + 1} of ${toExport.length}…`);
        if (!cancelToken.cancelled) progressBar.setText(`Exporting ${done + failed + 1} of ${toExport.length}: "${name}"`);
        try {
          const resolved = await window.ffmResolveListingMediaForExport(listing);
          await window.AutoListLocal.writeListing(resolved);
          done++;
          logLines.push(`Exported OK: "${name}"`);
        } catch (e) {
          console.warn('[AutoList Pro] export failed for listing', name, e);
          failed++;
          logLines.push(`Export FAILED: "${name}" — ${String((e && e.message) || e)}`);
        }
      }
      progressBar.close();

      if (cancelled) {
        logLines.push(`--- Export CANCELLED by user after ${done + failed} of ${toExport.length} (${done} exported, ${failed} failed before stopping) ---`);
      } else {
        logLines.push(`--- Export finished: ${done} exported, ${failed} failed ---`);
      }
      try { await window.ffmWriteActivityLog(logLines); } catch (e) {}

      const summary = cancelled
        ? `Export cancelled — ${done} listing(s) exported before stopping.`
        : (failed ? `Exported ${done} listing(s), ${failed} failed — see activity_log.txt.` : `Exported ${done} listing(s) to ${handle.name}.`);
      setProgress(summary);
      try { if (window.showToast) window.showToast(summary, failed && !cancelled ? 'error' : (cancelled ? 'info' : 'success')); } catch (e) {}
    } catch (e) {
      console.warn('[AutoList Pro] ffmExportSelectedListingsToLocalFolder failed', e);
      setProgress('Export failed — see console.');
    }
  };
  // Trigger button lives in the Saved Listings toolbar now (📤 Export
  // Listings…, see ffmInjectToolbarButtons) instead of a delegated click
  // listener on a fixed element id in the Local Backup Folder section.

  // Pulls listings back in from the connected local folder. Anything already
  // present in the extension (matched by listingId) is left untouched — only
  // folders that don't correspond to an existing listing get added.
  window.ffmImportAllListingsFromLocalFolder = async function () {
    const progressEl = document.getElementById('local-folder-export-progress');
    const setProgress = (text) => { try { if (progressEl) { progressEl.style.display = text ? 'block' : 'none'; progressEl.textContent = text || ''; } } catch (e) {} };
    try {
      if (!window.AutoListLocal) { setProgress('Not supported in this browser.'); return; }
      const { handle, granted } = await window.AutoListLocal.getFolderQuiet();
      if (!handle || !granted) { setProgress('Choose a folder first.'); return; }
      if (!(window.ffmMediaDB && typeof ffmMediaDB.putListingBlob === 'function')) { setProgress('Media storage unavailable — see console.'); return; }

      setProgress('Reading folder…');
      const found = await window.AutoListLocal.readAllListings();
      if (!found.length) { setProgress('No listings found in that folder.'); return; }

      const existing = await new Promise((res) => storageGet({ listings: [] }, (r) => res(Array.isArray(r.listings) ? r.listings : [])));
      const existingIds = new Set(existing.map((l) => String(l && (l.listingId || l.id || ''))).filter(Boolean));

      let added = 0, skipped = 0, failed = 0;
      const toAdd = [];
      for (const entry of found) {
        const raw = entry.listing || {};
        const listingId = String(raw.listingId || raw.id || '');
        setProgress(`Checking ${added + skipped + failed + 1} of ${found.length}…`);
        if (!listingId) { failed++; continue; }
        if (existingIds.has(listingId)) { skipped++; continue; }

        try {
          const listing = Object.assign({}, raw);
          delete listing.images; delete listing.videos; delete listing.base64Images; delete listing.base64Videos;
          listing.listingId = listingId;

          listing.localImageKeys = [];
          for (const img of entry.images) {
            const key = await ffmMediaDB.putListingBlob(listingId, 'image', img.index, img.blob, img.mimeType);
            listing.localImageKeys.push(key);
          }
          listing.localVideoKeys = [];
          for (const vid of entry.videos) {
            const key = await ffmMediaDB.putListingBlob(listingId, 'video', vid.index, vid.blob, vid.mimeType);
            listing.localVideoKeys.push(key);
          }
          listing.imageCount = listing.localImageKeys.length;
          listing.videoCount = listing.localVideoKeys.length;

          toAdd.push(listing);
          existingIds.add(listingId);
          added++;
        } catch (e) {
          console.warn('[AutoList Pro] import failed for', listingId, e);
          failed++;
        }
      }

      if (added) {
        const merged = existing.concat(toAdd);
        const prepared = prepareListingsForStorage(merged);
        try { await ffmStoreRestoredListings(prepared); } catch (e) { await new Promise((res) => storageSet({ listings: prepared }, res)); }
        try { if (typeof displaySavedListingsClean === 'function') displaySavedListingsClean('import'); else if (typeof displaySavedListingsOnce === 'function') displaySavedListingsOnce(); } catch (e) {}
      }

      const summary = `Imported ${added} new, skipped ${skipped} already-saved${failed ? `, ${failed} failed — see console` : ''}.`;
      setProgress(summary);
      try { if (window.showToast) window.showToast(summary, failed ? 'error' : 'success'); } catch (e) {}
    } catch (e) {
      console.warn('[AutoList Pro] ffmImportAllListingsFromLocalFolder failed', e);
      setProgress('Import failed — see console.');
    }
  };

  document.addEventListener('click', (ev) => {
    try {
      const btn = ev.target && ev.target.closest ? ev.target.closest('#local-folder-import-all-btn') : null;
      if (!btn) return;
      window.ffmImportAllListingsFromLocalFolder();
    } catch (e) {}
  });
})();

// Bulk import from Facebook — pulls every in-stock "Your listings" item into
// the extension (full details + photos), reusing the exact same scrape
// pipeline as the single "From Published" import. Runs from the popup (not
// background.js) because the local-folder export needs a DOM context.
(function () {
  let __ffmBulkStop = false;
  function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }

  function waitForTabComplete(tabId, timeoutMs) {
    return new Promise((resolve) => {
      let done = false;
      const timer = setTimeout(() => { if (!done) { done = true; try { chrome.tabs.onUpdated.removeListener(listener); } catch (e) {} resolve(false); } }, timeoutMs);
      function listener(id, info) {
        if (id === tabId && info && info.status === 'complete') {
          if (!done) { done = true; clearTimeout(timer); try { chrome.tabs.onUpdated.removeListener(listener); } catch (e) {} resolve(true); }
        }
      }
      try { chrome.tabs.onUpdated.addListener(listener); } catch (e) { resolve(false); }
    });
  }

  function sendMessageToTabWithRetry(tabId, msg, tries, delayMs) {
    return new Promise((resolve) => {
      let attempt = 0;
      const tryOnce = () => {
        attempt++;
        try {
          chrome.tabs.sendMessage(tabId, msg, (resp) => {
            if (chrome.runtime.lastError || !resp) {
              if (attempt < tries) setTimeout(tryOnce, delayMs); else resolve(null);
            } else resolve(resp);
          });
        } catch (e) {
          if (attempt < tries) setTimeout(tryOnce, delayMs); else resolve(null);
        }
      };
      tryOnce();
    });
  }

  function waitForScrapeResult(timeoutMs) {
    return new Promise((resolve) => {
      let done = false;
      const timer = setTimeout(() => { if (!done) { done = true; try { chrome.runtime.onMessage.removeListener(listener); } catch (e) {} resolve(null); } }, timeoutMs);
      function listener(msg) {
        if (msg && msg.action === 'scrape-result' && msg.origin === 'from_published') {
          if (!done) { done = true; clearTimeout(timer); try { chrome.runtime.onMessage.removeListener(listener); } catch (e) {} resolve(msg.data); }
        }
      }
      try { chrome.runtime.onMessage.addListener(listener); } catch (e) { resolve(null); }
    });
  }

  function sleepMs(ms) { return new Promise((r) => setTimeout(r, ms)); }

  // Polls background.js's __ffm_media_cache (populated once the media
  // helper tab finishes its own scrape and reports back) for a given
  // listing's real photos/videos. Returns null if nothing showed up within
  // the retry budget — callers should fall back to whatever the initial
  // scrape-result already had rather than treat this as fatal.
  async function fetchCachedMediaWithRetry(pubUrl, tries, delayMs) {
    for (let i = 0; i < tries; i++) {
      try {
        const resp = await new Promise((res) => { try { chrome.runtime.sendMessage({ action: 'ffm_request_cached_media', pubUrl }, res); } catch (e) { res(null); } });
        const hasImages = resp && resp.ok && resp.data && Array.isArray(resp.data.images) && resp.data.images.length;
        const hasVideos = resp && resp.ok && resp.data && Array.isArray(resp.data.videos) && resp.data.videos.length;
        if (hasImages || hasVideos) return resp.data;
      } catch (e) {}
      await sleepMs(delayMs);
    }
    return null;
  }

  function mapScrapedToBulkListing(data, src) {
    const fields = (data && data.fields) || {};
    const clean = (v) => (v && v !== '(Not found)') ? v : '';
    return {
      listingId: (typeof ffmGenerateListingId === 'function') ? ffmGenerateListingId() : ('ffm_' + Date.now() + '_' + Math.random().toString(36).slice(2, 7)),
      fbListingId: src.listingId,
      fbItemUrl: src.itemUrl,
      inventoryName: (data && (data.inventoryName || data.title)) || src.title || ('Imported ' + src.listingId),
      title: (data && data.title) || src.title || '',
      price: (data && data.price) || '',
      retailPrice: '',
      category: clean(fields.category),
      condition: clean(fields.condition),
      bedSize: '', bedType: '', sofaType: '', core: '', comfortLevel: '',
      bikeType: clean(fields.bikeType),
      wheelSize: clean(fields.wheelSize),
      bikeMaterial: clean(fields.bikeMaterial),
      smartHomeCompatibility: clean(fields.smartHomeCompatibility),
      elecColor: clean(fields.elecColor),
      publicMeetup: !!(data && data.publicMeetup), doorPickup: !!(data && data.doorPickup), doorDropoff: !!(data && data.doorDropoff),
      hideFromFriends: !!(data && data.hideFromFriends),
      description: (data && data.description) || '',
      images: Array.isArray(data && data.images) ? data.images : [],
      videos: Array.isArray(data && data.videos) ? data.videos : [],
      timestamp: Date.now(),
      importedFromFacebook: true,
    };
  }

  async function saveBulkListing(listing) {
    const existing = await new Promise((res) => storageGet({ listings: [] }, (r) => res(Array.isArray(r.listings) ? r.listings : [])));
    const dupIndex = existing.findIndex((l) => l && l.fbListingId && String(l.fbListingId) === String(listing.fbListingId));
    let outcome;
    if (dupIndex >= 0) {
      listing.listingId = existing[dupIndex].listingId || listing.listingId;
      existing[dupIndex] = Object.assign({}, existing[dupIndex], listing);
      outcome = 'updated';
    } else {
      existing.push(listing);
      outcome = 'created';
    }
    const prepared = prepareListingsForStorage(existing);
    await new Promise((res) => {
      try { ffmStoreRestoredListings(prepared).then(res).catch(() => { try { storageSet({ listings: prepared }, res); } catch (e) { res(); } }); }
      catch (e) { try { storageSet({ listings: prepared }, res); } catch (er) { res(); } }
    });
    try { if (typeof window.ffmExportListingToLocalFolder === 'function') await window.ffmExportListingToLocalFolder(listing); } catch (e) {}
    return outcome;
  }

  window.ffmBulkImportStop = function () { __ffmBulkStop = true; };

  // progressCb(text) is called with a short human-readable status after
  // every step — the caller (UI) is responsible for displaying it.
  window.ffmBulkImportFromFacebook = async function (progressCb) {
    __ffmBulkStop = false;
    const report = (text) => { try { if (typeof progressCb === 'function') progressCb(text); } catch (e) {} };
    let tab = null;
    let reusedExistingTab = false;
    try {
      // Same activation the real "From Published" button performs before
      // opening Facebook — without this, the content script won't inject the
      // Generate button or run its scrape logic at all on this tab.
      report('Activating scraper…');
      try {
        if (chrome.storage && chrome.storage.session && typeof chrome.storage.session.set === 'function') {
          await new Promise((res) => chrome.storage.session.set({ CLFP_ACTIVE: true }, res));
        }
      } catch (e) {}
      try { chrome.runtime.sendMessage({ type: 'ffm_set_clfp_active', active: true }); } catch (e) {}

      // Reuse an already-open Facebook Marketplace tab if one exists, rather
      // than always spawning a brand new tab — this keeps the run visible in
      // whatever tab you (or a browser automation tool watching alongside
      // you) already have open, instead of a fresh tab elsewhere.
      try {
        const existing = await new Promise((res) => chrome.tabs.query({ url: 'https://www.facebook.com/marketplace/*' }, res));
        if (existing && existing.length) { tab = existing[0]; reusedExistingTab = true; }
      } catch (e) {}

      const injectScraper = async () => {
        try {
          if (chrome.scripting && typeof chrome.scripting.executeScript === 'function') {
            await chrome.scripting.executeScript({ target: { tabId: tab.id }, files: ['content/bulk_import_selling.js', 'content/from_published_scraper.js'] });
          }
        } catch (e) {}
      };

      // "Your listings" page, filtered to live/in-stock only — never the
      // unfiltered page, so an already-sold listing is never picked up.
      // content/bulk_import_selling.js reads each listing's ID by opening
      // its "..." menu and closing it via the same button (never clicking
      // any menu item) — see that file's header comment for the full
      // safety rationale.
      const sellingUrl = 'https://www.facebook.com/marketplace/you/selling?state=LIVE&status[0]=IN_STOCK';
      if (tab) {
        await new Promise((res) => chrome.tabs.update(tab.id, { url: sellingUrl, active: true }, res));
      } else {
        tab = await new Promise((res) => chrome.tabs.create({ url: sellingUrl, active: true }, res));
      }
      await waitForTabComplete(tab.id, 30000);
      await sleep(1200);
      await injectScraper();
      await sleep(800);

      report('Reading your listings…');
      const enumResp = await sendMessageToTabWithRetry(tab.id, { action: 'ffm_bulk_selling_enumerate' }, 10, 1000);
      if (!enumResp || !enumResp.ok) { report('Could not read your listings page — is it still open?'); return { ok: false }; }
      const items = enumResp.listings || [];
      if (enumResp.aborted) {
        report(`Stopped early after ${items.length} listing(s): a listing's menu wouldn't verifiably close, so the run stopped rather than risk touching the wrong control. Nothing was clicked besides "..." to open/close.`);
        if (!items.length) return { ok: true, created: 0, updated: 0, failed: 0, total: 0, aborted: true };
      }
      if (!items.length) { report('No listings found.'); return { ok: true, created: 0, updated: 0, failed: 0, total: 0 }; }
      report(`Found ${items.length} listing(s). Starting import…`);

      let created = 0, updated = 0, failed = 0;
      // Belt-and-suspenders tab cleanup: the per-listing diff below closes
      // whatever's new right after that listing's scrape resolves, but the
      // media-helper tab (chrome.tabs.create in background.js's
      // ffm_open_edit_and_media handler) can finish creating a beat after
      // that diff already ran — a real race, not a hypothetical one — which
      // would otherwise leave it open indefinitely. Sweeping for any
      // straggler at the START of every iteration (and once before the
      // loop, in case a prior interrupted run left one) bounds the total to
      // at most one listing's worth of extra tabs at any moment, regardless
      // of Chrome tab-behavior settings, since both tabs are always created
      // via chrome.tabs.create (an explicit API call), never a link click.
      const sweepStrayAutomationTabs = async () => {
        try {
          const all = await new Promise((res) => chrome.tabs.query({}, res));
          const stray = all.filter((t) => t.id !== tab.id && /marketplace\/edit\/|__ffm_media=1/.test(t.url || t.pendingUrl || ''));
          if (stray.length) await new Promise((res) => chrome.tabs.remove(stray.map((t) => t.id), res));
        } catch (e) {}
      };
      await sweepStrayAutomationTabs();
      for (let i = 0; i < items.length; i++) {
        if (__ffmBulkStop) { report(`Stopped after ${i} of ${items.length}.`); break; }
        await sweepStrayAutomationTabs();
        const item = items[i];
        report(`(${i + 1}/${items.length}) ${item.title || item.listingId}…`);
        try {
          // Exact same URL scheme + message the extension's own injected
          // "Generate" button uses (from_published_scraper.js) — background.js
          // opens the edit tab plus a hidden media-helper tab from this.
          const editUrl = `https://www.facebook.com/marketplace/edit/?listing_id=${item.listingId}&__ffm_generate=1&__ffm_pub=${encodeURIComponent(item.itemUrl)}`;
          const beforeIds = new Set((await new Promise((res) => chrome.tabs.query({}, res))).map((t) => t.id));

          const resultPromise = waitForScrapeResult(30000);
          await new Promise((res) => { try { chrome.runtime.sendMessage({ action: 'ffm_open_edit_and_media', editUrl, pubUrl: item.itemUrl, listingId: item.listingId }, res); } catch (e) { res(null); } });
          const data = await resultPromise;

          if (!data) { failed++; report(`(${i + 1}/${items.length}) ${item.title || item.listingId} — timed out, skipped.`); }
          else {
            // The initial scrape-result's own data.images/videos come from a
            // quick DOM read of the edit page and are often sparse or empty.
            // The real photos/videos are found by a SEPARATE helper tab
            // (background.js's media pipeline) and only show up later in its
            // ffm_request_cached_media cache — the manual single-listing
            // "From Published" flow already waits for this; bulk-import
            // wasn't, which is why photos were routinely missing. Poll for it
            // here (background.js closes the helper tab itself once it's
            // delivered, so this isn't racing our own tab cleanup below).
            const media = await fetchCachedMediaWithRetry(item.itemUrl, 8, 1500);
            if (media) {
              if (Array.isArray(media.images) && media.images.length) data.images = media.images;
              if (Array.isArray(media.videos) && media.videos.length) data.videos = media.videos;
            }
            const listing = mapScrapedToBulkListing(data, item);
            const outcome = await saveBulkListing(listing);
            if (outcome === 'updated') updated++; else created++;
          }

          // Close whatever new tab(s) this listing opened (edit tab + media
          // helper tab) — never touches the main orchestration tab.
          try {
            const afterTabs = await new Promise((res) => chrome.tabs.query({}, res));
            const newTabIds = afterTabs.filter((t) => t.id !== tab.id && !beforeIds.has(t.id)).map((t) => t.id);
            if (newTabIds.length) await new Promise((res) => chrome.tabs.remove(newTabIds, res));
          } catch (e) {}
        } catch (e) { failed++; console.warn('[AutoList Pro bulk-import] listing failed', item, e); }
        await sleep(2500 + Math.floor(Math.random() * 1500)); // pace requests, don't hammer Facebook
      }
      const summary = `Done. ${created} new, ${updated} updated, ${failed} failed (of ${items.length}).`;
      report(summary);
      try { if (typeof ffmRefreshSavedListings === 'function') ffmRefreshSavedListings(); } catch (e) {}
      try { if (window.showToast) window.showToast(summary, failed ? 'error' : 'success'); } catch (e) {}
      return { ok: true, created, updated, failed, total: items.length };
    } catch (e) {
      report('Import failed: ' + String(e && e.message || e));
      return { ok: false, error: String(e) };
    } finally {
      // Only close the tab if we created it ourselves — leave a reused tab
      // (one that was already open before this run) exactly as we found it.
      try { if (tab && tab.id && !reusedExistingTab) chrome.tabs.remove(tab.id); } catch (e) {}
    }
  };

  document.addEventListener('click', (ev) => {
    try {
      const startBtn = ev.target && ev.target.closest ? ev.target.closest('#fb-bulk-import-start-btn') : null;
      const stopBtn = ev.target && ev.target.closest ? ev.target.closest('#fb-bulk-import-stop-btn') : null;
      const statusEl = document.getElementById('fb-bulk-import-status');
      if (startBtn) {
        if (startBtn.disabled) return;
        startBtn.disabled = true;
        try { const sb = document.getElementById('fb-bulk-import-stop-btn'); if (sb) sb.style.display = ''; } catch (e) {}
        window.ffmBulkImportFromFacebook((text) => { try { if (statusEl) statusEl.textContent = text; } catch (e) {} })
          .finally(() => {
            startBtn.disabled = false;
            try { const sb = document.getElementById('fb-bulk-import-stop-btn'); if (sb) sb.style.display = 'none'; } catch (e) {}
          });
      } else if (stopBtn) {
        window.ffmBulkImportStop();
        if (statusEl) statusEl.textContent = 'Stopping after current listing…';
      }
    } catch (e) {}
  });
})();

