  // -----------------------------
  // Auth gating helpers (visual + click interception)
  // -----------------------------
  async function ffmLoadAuthState() {
    try {
      const st = await new Promise((resolve) => {
        try { chrome.runtime.sendMessage({ type: 'ffm-auth:get-state' }, (res) => resolve(res)); } catch (e) { resolve(null); }
      });
      const signedIn = !!(st && st.ok && (st.signedIn || (st.user && st.user.email)));
      try { window.ffmSignedIn = signedIn; } catch (e) {}
      try { window.ffmCurrentUserEmail = st && st.user && st.user.email ? st.user.email : null; } catch (e) {}
      try { window.ffmCurrentUserId = st && st.user && st.user.id ? st.user.id : null; } catch (e) {}
      // If signed in, check agreement acceptance
      try { if (signedIn) { ffmCheckAndShowAgreement && ffmCheckAndShowAgreement(); } } catch (e) {}
      return signedIn;
    } catch (e) {
      console.warn('[AutoList Pro] ffmLoadAuthState failed', e);
      try { window.ffmSignedIn = false; } catch (e) {}
      return false;
    }
  }

  // Check stored acceptance and show short modal if needed
  function ffmCheckAndShowAgreement() {
    try {
      const userId = window.ffmCurrentUserId || null;
      if (!userId) return;
      const key = 'ffm_user_agreement_accepted';
      try {
        chrome.storage.local.get(key, (res) => {
          try {
            const map = (res && res[key]) ? res[key] : {};
            const existing = map[userId];
            const requiredVersion = '1.0';
            if (existing && existing.version === requiredVersion) {
              return; // already accepted
            }
            // Not accepted yet — show short modal that requires acceptance
            ffmShowAgreementModal(userId, requiredVersion);
          } catch (e) {}
        });
      } catch (e) {}
    } catch (e) { console.warn('[AutoList Pro] ffmCheckAndShowAgreement failed', e); }
  }

  function ffmShowAgreementModal(userId, version) {
    try {
      // If already shown, avoid duplicating
      if (document.getElementById('ffm-agreement-short')) return;

      const root = document.createElement('div');
      root.id = 'ffm-agreement-short';
      root.style.position = 'fixed';
      root.style.inset = '0';
      root.style.background = 'rgba(0,0,0,0.6)';
      root.style.display = 'flex';
      root.style.alignItems = 'center';
      root.style.justifyContent = 'center';
      root.style.zIndex = '200000';

      const card = document.createElement('div');
      card.style.width = 'min(640px,92vw)';
      card.style.background = '#fff';
      card.style.borderRadius = '10px';
      card.style.padding = '18px';
      card.style.boxShadow = '0 8px 30px rgba(0,0,0,0.35)';
      card.style.maxHeight = '80vh';
      card.style.overflow = 'auto';

      const title = document.createElement('h2');
      title.textContent = 'AutoList Pro – User Agreement';
      title.style.marginTop = '0';
      card.appendChild(title);

      const body = document.createElement('div');
      body.style.fontSize = '14px';
      body.style.color = '#222';
      body.style.lineHeight = '1.4';
      body.innerHTML = `
        <p>Before using AutoList Pro, please review and agree to the following:</p>
        <ul>
          <li>AutoList Pro is an independent helper tool and is not affiliated with Facebook or Meta.</li>
          <li>AutoList Pro does not manage or verify your Facebook login. All actions run on the Facebook account currently signed into your browser.</li>
          <li>AutoList Pro does not collect Facebook usernames, passwords, or cookies.</li>
          <li>Automation features rely on Facebook’s web interface and may be affected by Facebook changes or limits.</li>
          <li>You are responsible for complying with Facebook’s Terms of Service.</li>
        </ul>
        <p>You can view the full User Agreement at any time in Settings.</p>
      `;
      card.appendChild(body);

      const actions = document.createElement('div');
      actions.style.display = 'flex';
      actions.style.justifyContent = 'flex-end';
      actions.style.gap = '8px';
      actions.style.marginTop = '12px';

      const viewBtn = document.createElement('button');
      viewBtn.className = 'action-btn ffm-view-agreement-btn';
      viewBtn.textContent = 'View Full Agreement';
      viewBtn.addEventListener('click', () => {
        try {
          // Close short modal (if present) so settings is visible
          try { const short = document.getElementById('ffm-agreement-short'); if (short) short.remove(); } catch (e) {}
          // open settings and scroll to agreement
          const settingsPanel = document.getElementById('ffm-settings-panel');
          if (settingsPanel) settingsPanel.style.display = 'block';
          const full = document.getElementById('ffm-full-agreement');
          if (full) { full.style.display = 'block'; setTimeout(() => { try { full.scrollIntoView({ behavior: 'smooth' }); } catch (e) {} }, 50); }
        } catch (e) {}
      });

      const agreeBtn = document.createElement('button');
      agreeBtn.className = 'action-btn ffm-agree-btn';
      agreeBtn.textContent = 'I Agree';
      agreeBtn.addEventListener('click', () => {
        try {
          const key = 'ffm_user_agreement_accepted';
          try {
            chrome.storage.local.get(key, (res) => {
              try {
                const map = (res && res[key]) ? res[key] : {};
                map[userId] = { version: version || '1.0', acceptedAt: Date.now(), userId };
                chrome.storage.local.set({ [key]: map }, () => {
                  try { const el = document.getElementById('ffm-agreement-short'); if (el) el.remove(); } catch (e) {}
                  try { ffmCheckCloudSyncStatusAfterLogin && typeof ffmCheckCloudSyncStatusAfterLogin === 'function' && ffmCheckCloudSyncStatusAfterLogin(); } catch (e) {}
                });
              } catch (e) { try { const el = document.getElementById('ffm-agreement-short'); if (el) el.remove(); } catch (e) {} }
            });
          } catch (e) { try { const el = document.getElementById('ffm-agreement-short'); if (el) el.remove(); } catch (e) {} }
        } catch (e) {}
      });

      // No cancel button — modal must be accepted to proceed
      actions.appendChild(viewBtn);
      actions.appendChild(agreeBtn);
      card.appendChild(actions);

      // Prevent clicks on backdrop from closing or interacting
      root.addEventListener('click', (ev) => { ev.stopPropagation(); });

      root.appendChild(card);
      document.body.appendChild(root);
    } catch (e) { console.warn('[AutoList Pro] ffmShowAgreementModal failed', e); }
  }

