// Lightweight S3 fetch helper for popup: returns a Blob for a given S3 key
async function ffmFetchS3Blob(s3Key) {
  try {
    if (!s3Key) return null;
    // Prefer using the centralized awsSignDownload helper which includes
    // timeout/parse logic and consistent query param naming.
    let signJson = null;
    try {
      signJson = await awsSignDownload(s3Key);
    } catch (e) {
      console.warn('[popup] ffmFetchS3Blob: awsSignDownload failed', s3Key, e);
      return null;
    }

    const presignedUrl = signJson && signJson.url;
    if (!presignedUrl) {
      console.warn('[popup] ffmFetchS3Blob: no url returned from awsSignDownload', s3Key, signJson);
      return null;
    }

    // Use fetchWithTimeout for robustness
    try {
      const resp = await fetchWithTimeout(presignedUrl, {}, 15000);
      if (!resp || !resp.ok) {
        console.warn('[popup] ffmFetchS3Blob: blob fetch failed', s3Key, resp && resp.status);
        return null;
      }
      return await resp.blob();
    } catch (e) {
      console.warn('[popup] ffmFetchS3Blob: presigned fetch error', e, s3Key);
      return null;
    }
  } catch (e) {
    console.warn('[popup] ffmFetchS3Blob error', e);
    return null;
  }
}

// Ensure the MediaDB is available before attempts to read/write
async function ensureMediaDBReady(timeoutMs = 5000) {
  const start = Date.now();
  while (true) {
    try {
      if (window.ffmMediaDB && typeof ffmMediaDB.getBlobsForListing === 'function' && typeof ffmMediaDB.putListingBlob === 'function') return true;
    } catch (e) {}
    if (Date.now() - start > timeoutMs) break;
    await new Promise(r => setTimeout(r, 120));
  }
  return false;
}

// Canonical metadata key helper is defined near the S3 helpers above.
// It uses `ffmGetListingRootKey(listingId)` and returns
// `${ffmGetListingRootKey(listingId)}/info.json`.
// -----------------------------
// Canonical Saved Listings Helper
// -----------------------------
function ffmSetCanonicalListings(listingsArray) {
  // Block canonical listings mutation while a hidden AS is in-progress
  if (typeof window !== 'undefined' && window.__FFM_AS_IN_PROGRESS__ && !ffmAsMergedApplied) {
    try { console.warn('[AS] Mutation blocked until merged result'); } catch (e) {}
    return;
  }
  // Ensure we operate on an array
  let finalListings = Array.isArray(listingsArray) ? listingsArray : [];

  // --- PATCH: enforce uniqueness by listingId only ---
  const mapById = new Map();
  for (const item of finalListings) {
    if (item && item.listingId) {
      mapById.set(item.listingId, item);
    }
  }
  finalListings = Array.from(mapById.values());

  const safe = finalListings;

  // Normalize a bit so we always have an ID-ish field
  const normalized = safe.map(l => {
    if (!l) return l;
    const copy = { ...l };
    if (!copy.id && copy.listingId) copy.id = copy.listingId;
    if (!copy.listingId && copy.id) copy.listingId = copy.id;
    return copy;
  });

  try {
    // Use centralized storageSet so suppression and large-data stripping apply.
    storageSet({
      listings: normalized,
      ffm_saved_listings: normalized,
      ffmSavedListings: normalized,
      __ffm_saved_listings_cache: normalized
    }, () => {
      try {
        console.log(
          "[AutoList Pro] ffmSetCanonicalListings ->",
          normalized.length,
          "listings saved"
        );
      } catch (e) { /* ignore logging failure */ }
    });
  } catch (e) {
    try { console.warn('[AutoList Pro] ffmSetCanonicalListings storage.set failed', e); } catch(_){}
  }

  // Also keep the in-memory copy in sync if it exists
  try {
    if (Array.isArray(window.ffmSavedListingsActive)) {
      window.ffmSavedListingsActive = normalized.slice();
    }
  } catch (e) { /* ignore */ }
}
// === FIXED: canonical cloud-restore writer ===
// Writes canonical arrays plus individual ffm_<id> keys so restored
// listings persist across popup reloads and are discoverable by legacy readers.
async function ffmStoreRestoredListings(restoredList) {
  const list = Array.isArray(restoredList) ? restoredList : [];
  const toWrite = {
    ffmSavedListings: list,
    ffm_saved_listings: list,
    __ffm_saved_listings_cache: list,
    listings: list
  };

  for (const listing of list) {
    try {
      const id = listing && (listing.listingId || listing.id || listing.inventoryName);
      if (!id) continue;
      // ensure string key
      const sid = String(id);
      if (!sid) continue;
      // only write proper ffm_ ids or accept whatever id is present
      const key = sid.startsWith('ffm_') ? sid : `ffm_${sid}`;
      toWrite[key] = listing;
    } catch (e) {
      // per-listing non-fatal
    }
  }

  return new Promise((resolve) => {
    try {
      storageSet(toWrite, () => {
        try {
          console.log('✔ RESTORE WRITE COMPLETE — wrote:');
          console.log('  → canonical arrays:', list.length);
          try { console.log('  → individual ffm_* keys:', list.map(l => l && (l.listingId || l.id || l.inventoryName))); } catch (e) {}
        } catch (e) {}
        try {
          // Update local-modified timestamp after a successful restore write
          try { ffmTouchLocalLastModified && typeof ffmTouchLocalLastModified === 'function' && ffmTouchLocalLastModified(); } catch (e) {}
        } catch (e) {}
        resolve();
      });
    } catch (e) {
      try { console.warn('[AutoList Pro] ffmStoreRestoredListings storage.set failed', e); } catch (_) {}
      resolve();
    }
  });
}

