// -----------------------------------------------------
//  AutoList Pro DB Thumbnail Loader for Saved Listings
// -----------------------------------------------------
async function ffmGetThumbnailFromDB(listing) {
  const listingId = listing.listingId || listing.id;
  if (!listingId) return '';

  const keys = listing.localImageKeys || [];
  if (!keys.length) return '';

  const firstKey = keys[0];
  if (!firstKey || typeof firstKey !== 'string') return '';

  try {
    const rec = await ffmMediaDB.getBlob(firstKey);
    if (rec && rec.blob) {
      return URL.createObjectURL(rec.blob);
    }
  } catch (e) {
    console.warn('[AutoList Pro popup] Thumbnail DB load failed', e);
  }
  return '';
}

