function ffmResetForm(formId) {
  try {
    const el = document.getElementById(formId);
    if (!el) return;
    console.debug(`[AutoList Pro] Resetting ${formId}…`);

    // Clear inputs
    try {
      el.querySelectorAll("input, textarea, select").forEach(i => {
        try {
          const t = (i.type || '').toString().toLowerCase();
          if (t === 'checkbox' || t === 'radio') i.checked = false;
          else i.value = '';
        } catch (err) {}
      });
    } catch (e) {}

    // Clear media thumbnails and arrays
    try { el.querySelectorAll('.thumbnail-preview, .video-preview').forEach(p => { try { p.remove(); } catch(_){} }); } catch(e) {}
    try { window.currentImages = []; } catch(e) {}
    try { window.currentVideos = []; } catch(e) {}
    try { window.uploadedMediaList = []; } catch(e) {}
    try { window.pendingUploads = []; } catch(e) {}

    // Reset publish status box
    try { const text = document.getElementById('publish-result-text'); if (text) text.textContent = 'Ready.'; } catch(e) {}
    try { const time = document.getElementById('publish-result-time'); if (time) time.textContent = ''; } catch(e) {}
    try { const icon = document.getElementById('publish-result-icon'); if (icon) icon.style.display = 'none'; } catch(e) {}

    // Restore defaults if this is the manual listing form
    try {
      if (formId === 'create-listing-section') {
        try { const priceInput = el.querySelector('input[name="price"]'); if (priceInput) priceInput.value = '0'; } catch(e) {}
        try { const conditionSelect = el.querySelector('select[name="condition"]'); if (conditionSelect) conditionSelect.value = 'Used - like new'; } catch(e) {}
        try { const categorySelect = el.querySelector('select[name="category"]'); if (categorySelect) categorySelect.value = 'Furniture'; } catch(e) {}
        try { const hffToggle = el.querySelector('#hide-from-friends'); if (hffToggle) hffToggle.checked = false; } catch(e) {}
      }
    } catch(e) {}

    console.debug(`[AutoList Pro] ${formId} fully cleared`);
  } catch (err) { console.debug('[AutoList Pro] ffmResetForm error', err); }
}

