// ---- Last Checked label helper (silent; only hourly logs) ----
function updateLastCheckedLabel(ts) {
  try {
    const wrap = document.querySelector('#ffmSortRight');
    if (!wrap) return;

    const lastTs = Number(ts || window.ffmLastActiveCheck || 0) || 0;

    // If we don't have an in-memory timestamp, try to read the most recent
    // persisted timestamp from storage (check both modern and legacy keys).
    if (!lastTs && chrome && chrome.storage && chrome.storage.local && typeof chrome.storage.local.get === 'function') {
      try {
        chrome.storage.local.get(['ffmLastActiveCheck','fast4mp_lastActiveCheck'], (res) => {
          try {
            const a = Number((res && res.ffmLastActiveCheck) || 0) || 0;
            const b = Number((res && res.fast4mp_lastActiveCheck) || 0) || 0;
            const chosen = Math.max(a, b) || 0;
            const mins = chosen ? Math.floor((Date.now() - chosen) / 60000) : 0;
            const text = mins === 0 ? 'Just Now' : `${mins} min${mins !== 1 ? 's' : ''} ago`;
            try {
              let tip = wrap.querySelector('.ffm-last-checked-tip');
              if (!tip) {
                tip = document.createElement('span');
                tip.className = 'ffm-last-checked-tip';
                tip.setAttribute('title', 'Active Listings are updated by clicking the Active Sync button');
                tip.style.cursor = 'help';
                if (wrap.textContent && wrap.textContent.trim()) wrap.appendChild(document.createTextNode(' | '));
                wrap.appendChild(tip);
              }
              tip.textContent = 'Last checked: ' + text;
            } catch (e) { try { wrap.textContent = 'Last checked: ' + text; } catch(_) {} }
          } catch (e) { /* ignore storage-read errors */ }
        });
      } catch (e) { /* ignore */ }
      return;
    }

    const minutesAgo = Math.floor((Date.now() - (lastTs || Date.now())) / 60000);
    const text = minutesAgo === 0 ? 'Just Now' : `${minutesAgo} min${minutesAgo !== 1 ? 's' : ''} ago`;

    try {
      let tip = wrap.querySelector('.ffm-last-checked-tip');
      if (!tip) {
        tip = document.createElement('span');
        tip.className = 'ffm-last-checked-tip';
        tip.setAttribute('title', 'Active Listings are updated by Clicking the Active Sync button');
        tip.style.cursor = 'help';
        // insert separator if wrap already has content
        if (wrap.textContent && wrap.textContent.trim()) wrap.appendChild(document.createTextNode(' | '));
        wrap.appendChild(tip);
      }
      tip.textContent = 'Last checked: ' + text;
    } catch (e) { try { wrap.textContent = 'Last checked: ' + text; } catch(_) {} }

    // Log only once per hour (when Active Sync runs)
    if (minutesAgo % 60 === 0) {
      try { console.log(`[AutoList Pro popup] 🕒 Hourly Active Sync check — ${text}`); } catch (e) {}
    }
  } catch (e) { /* ignore */ }
}

