// Small helper: show/hide Active Sync running state across popup buttons
function ffmSetActiveSyncRunning(isRunning) {
  try {
    window.__ffm_as_running = !!isRunning;
    const nodes = document.querySelectorAll('#btnActiveSync, button#btnActiveSync, .ffm-btn#btnActiveSync');
    nodes.forEach(btn => {
      try {
        btn.disabled = !!isRunning;
        if (isRunning) {
          try { btn.dataset._ffm_old_text = btn.textContent; } catch (e) {}
          try { btn.textContent = '🔄 Running…'; } catch (e) {}
          try { btn.classList && btn.classList.add('ffm-active-sync-running'); } catch (e) {}
        } else {
          try {
            if (btn.dataset && btn.dataset._ffm_old_text) { btn.textContent = btn.dataset._ffm_old_text; delete btn.dataset._ffm_old_text; }
            else btn.textContent = '🔄 Active Sync';
          } catch (e) {}
          try { btn.classList && btn.classList.remove('ffm-active-sync-running'); } catch (e) {}
        }
      } catch (e) {}
    });

    // Maintain a watchdog to clear stale running state
    try {
      if (!isRunning && window.__ffm_as_watchdog) { clearTimeout(window.__ffm_as_watchdog); window.__ffm_as_watchdog = null; }
      if (isRunning) {
        if (window.__ffm_as_watchdog) try { clearTimeout(window.__ffm_as_watchdog); } catch (e) {}
        window.__ffm_as_watchdog = setTimeout(() => { try { ffmSetActiveSyncRunning(false); } catch (e) {} }, 30000);
      }
    } catch (e) {}
  } catch (e) {}
}

