// Live-update Last Checked label with dynamic scheduling (legacy).
// This legacy scheduler will be skipped if the unified silent updater is active.
try {
  if (window._ffm_lastCheckedTimer) {
    // New unified updater is active; skip legacy dynamic scheduler to avoid duplicate timers.
  } else {
    // - update every minute while age < 1 hour
    // - update every hour while age < 1 day
    // - update every day thereafter
    if (!window.__ffmLastCheckedTimer) {
      const scheduleTick = (delay) => {
        try {
          if (window.__ffmLastCheckedTimer) clearTimeout(window.__ffmLastCheckedTimer);
        } catch (e) {}
        try { window.__ffmLastCheckedTimer = setTimeout(tick, delay); } catch (e) {}
      };

      const tick = () => {
        try {
          try {
            chrome && chrome.storage && chrome.storage.local && chrome.storage.local.get && chrome.storage.local.get('fast4mp_lastActiveCheck', (res) => {
              try {
                const ts = res && res.fast4mp_lastActiveCheck;
                if (ts && typeof updateLastCheckedLabel === 'function') updateLastCheckedLabel(ts);

                // decide next delay
                const ageMs = ts ? (Date.now() - ts) : null;
                let nextDelay = 60 * 1000; // default 1 min
                if (ageMs === null) nextDelay = 60 * 1000;
                else if (ageMs < 60 * 60 * 1000) nextDelay = 60 * 1000;
                else if (ageMs < 24 * 60 * 60 * 1000) nextDelay = 60 * 60 * 1000;
                else nextDelay = 24 * 60 * 60 * 1000;

                scheduleTick(nextDelay);
              } catch (e) {
                // on any error, try again in 1 minute
                scheduleTick(60 * 1000);
              }
            });
          } catch (e) {
            // storage.get threw synchronously
            scheduleTick(60 * 1000);
          }
        } catch (e) {
          // fallback reschedule
          try { scheduleTick(60 * 1000); } catch (ee) {}
        }
      };

      // Start immediately
      try { tick(); } catch (e) { /* ignore */ }

      // Clear timer on unload to avoid leaks
      try { window.addEventListener && window.addEventListener('unload', () => { try { clearTimeout(window.__ffmLastCheckedTimer); window.__ffmLastCheckedTimer = null; } catch (e) {} }); } catch (e) {}
    }
  }
} catch (e) { /* ignore */ }

