function ffmNormalizeTitle(t) {
  try {
    if (!t) return '';
    const firstLine = ('' + t).split('\n')[0] || '';
    let s = firstLine.replace(/[^\x20-\x7E]/g, ' ').replace(/\s+/g, ' ').trim();
    s = s.replace(/\s*\-\s*Like New!?$/i, '').trim();
    return s.toLowerCase();
  } catch (e) { return ''; }
}

function ffmExtractDateStr(d) {
  try {
    if (!d) return null;
    const m = /listed on\s+([0-9]{1,2}\/([0-9]{1,2}|[0-9]{2}))/i.exec(d);
    return m ? m[1] : null;
  } catch (e) { return null; }
}

function ffmSimilar(a, b) {
  try {
    if (!a || !b) return false;
    if (a === b) return true;
    if (a.includes(b) || b.includes(a)) return true;
    const ta = new Set(a.split(' '));
    const tb = new Set(b.split(' '));
    let overlap = 0;
    for (const w of ta) if (tb.has(w)) overlap++;
    const ratio = overlap / Math.max(ta.size || 1, tb.size || 1);
    return ratio >= 0.6;
  } catch (e) { return false; }
}

// Async wrapper for chrome.storage.local.set that properly checks chrome.runtime.lastError
// and retries with large-data stripping on quota errors. Returns a Promise that resolves
// when the set succeeds or rejects with an Error.
async function storageLocalSetAsync(obj) {
  return new Promise((resolve, reject) => {
    try {
      if (!(window.chrome && chrome.storage && chrome.storage.local && chrome.storage.local.set)) {
        // Fallback to localStorage synchronous merge used by storageSet
        try {
          const raw = localStorage.getItem('fast4mp_storage');
          const parsed = raw ? JSON.parse(raw) : {};
          const merged = Object.assign({}, parsed, stripLargeDataUrls(obj, 100 * 1024, []));
          localStorage.setItem('fast4mp_storage', JSON.stringify(merged));
          return resolve();
        } catch (e) {
          return reject(e);
        }

        
      }

      chrome.storage.local.set(obj, function() {
        const err = (window.chrome && chrome.runtime && chrome.runtime.lastError) ? chrome.runtime.lastError : null;
        if (!err) return resolve();
        // If it's a quota error, try again with large data URLs stripped
        try {
          if (/quota/i.test(err.message || '')) {
            console.warn('storageLocalSetAsync: quota exceeded, retrying with large data URLs stripped');
            const stripped = {};
            for (const k in obj) stripped[k] = stripLargeDataUrls(obj[k], 100 * 1024, [k]);
            chrome.storage.local.set(stripped, function() {
              const err2 = (window.chrome && chrome.runtime && chrome.runtime.lastError) ? chrome.runtime.lastError : null;
              if (err2) return reject(new Error(err2.message || 'storage set retry failed'));
              return resolve();
            });
            return;
          }
        } catch (e) {
          // fallthrough to reject with original error
        }
        return reject(new Error(err.message || 'chrome.storage.local.set failed'));
      });
    } catch (e) {
      return reject(e);
    }
  });
}

