// Top-level: Update listing UI: badge color and swap Publish -> Delete/Relist when active
function updateListingStatusUI(listingEl, ts) {
  try {
    if (!listingEl) return;
    const now = Date.now();
    const badge = listingEl.querySelector('.ffm-active-badge');
    try { console.debug('[AutoList Pro] updateListingStatusUI entered', { inventory: listingEl.getAttribute && listingEl.getAttribute('data-inventory-name'), title: listingEl.getAttribute && listingEl.getAttribute('data-listing-title'), hasBadge: !!badge }); } catch(_) {}
    let ageDays = null;
    if (ts && Number(ts) > 0) ageDays = Math.floor((now - Number(ts)) / (24 * 60 * 60 * 1000));

    // normalize classes
    try {
      if (badge) {
        badge.classList.remove('ffm-active-badge-new', 'ffm-active-badge-aging', 'ffm-active-badge-old', 'ffm-active-badge-unknown');
        if (ageDays === null) {
          badge.classList.add('ffm-active-badge-unknown');
          badge.title = 'Unknown date — consider checking this listing';
        } else if (ageDays <= 3) {
          badge.classList.add('ffm-active-badge-new');
          badge.title = `Listed ${ageDays} day${ageDays === 1 ? '' : 's'} ago — New listing, no need for Delete/Relist`;
        } else if (ageDays >= 4 && ageDays <= 5) {
          badge.classList.add('ffm-active-badge-aging');
          badge.title = `Listed ${ageDays} days ago — Ageing listing, recommend Delete/Relist soon`;
        } else if (ageDays >= 6) {
          badge.classList.add('ffm-active-badge-old');
          badge.title = `Listed ${ageDays} days ago — Old listing, recommend Delete/Relist`;
        }
      }
    } catch (e) {}

    // Swap publish button behavior
    try {
      const publishBtn = listingEl.querySelector('.publish-btn');
      if (!publishBtn) {
        try { console.debug('[AutoList Pro] updateListingStatusUI: publish button not found for', listingEl.getAttribute && listingEl.getAttribute('data-inventory-name')); } catch(_) {}
        return;
      }

      try { console.debug('[AutoList Pro] publishBtn found', { hasPublishHandler: !!publishBtn._ffm_handlePublish, hasDeleteHandler: !!publishBtn._ffm_handleDelete, text: publishBtn.textContent }); } catch(_) {}

      // Consider any active badge (including unknown date) as 'active' so Publish -> Delete/Relist
      // is available even when date parsing failed.
      const isActive = !!badge && badge.classList && (
        badge.classList.contains('ffm-active-badge-new') ||
        badge.classList.contains('ffm-active-badge-aging') ||
        badge.classList.contains('ffm-active-badge-old') ||
        badge.classList.contains('ffm-active-badge-unknown')
      );
      if (isActive) {
        listingEl.dataset.isActive = 'true';
        // replace original publish handler with delete/relist
        try {
          if (publishBtn._ffm_handlePublish) publishBtn.removeEventListener('click', publishBtn._ffm_handlePublish);
        } catch (e) {}
        // avoid adding multiple handlers
          if (!publishBtn._ffm_handleDelete) {
          publishBtn._ffm_handleDelete = async (ev) => {
            try { ev.preventDefault && ev.preventDefault(); } catch (_) {}
            // Mark this as a manual DnR action so content final-gate can honour menu-auto
            try {
              chrome.storage.local.set({ ffm_manual_action: { ts: Date.now(), type: 'dnr', inventoryName: listingEl && listingEl.getAttribute ? listingEl.getAttribute('data-inventory-name') : null } }, () => {
                try { console.log('[AutoList Pro popup] ffm_manual_action written (manual DnR)', { inventory: listingEl && listingEl.getAttribute ? listingEl.getAttribute('data-inventory-name') : null }); } catch (e) {}

                // Pull full Saved Listing data, not the DOM element — run after marker is persisted
                const inventory = listingEl.getAttribute && listingEl.getAttribute('data-inventory-name');
                try {
                  chrome.storage.local.get(["savedListings","ffm_saved_listings","listings","ffmSavedListings","ffmSavedListings"], (res) => {
                    try {
                      const arr = (res && (res.savedListings || res.ffm_saved_listings || res.listings || res.ffmSavedListings || res.ffmSavedListings)) || [];
                      let sl = null;
                      if (inventory) sl = arr.find(l => l && (l.inventoryName === inventory || l.inventory_name === inventory));
                      if (!sl && inventory) sl = arr.find(l => l && (String(l.listingId) === String(inventory) || String(l.id) === String(inventory)));
                      if (!sl && inventory) sl = arr.find(l => l && l.title && String(l.title).trim() === String(inventory).trim());
                      if (sl) return handleDeleteAndRelist(sl);

                      // No saved-listing found; build minimal fallback from DOM
                      try {
                        const fallback = {
                          listingId: listingEl && listingEl.getAttribute ? (listingEl.getAttribute('data-listing-id') || listingEl.getAttribute('data-listing-id')) : null,
                          inventoryName: listingEl && listingEl.getAttribute ? (listingEl.getAttribute('data-inventory-name') || null) : null,
                          title: listingEl && listingEl.getAttribute ? (listingEl.getAttribute('data-listing-title') || listingEl.getAttribute('data-inventory-name') || '') : ''
                        };
                        return handleDeleteAndRelist(fallback);
                      } catch (e) {
                        console.debug('[AutoList Pro] handleDeleteAndRelist: fallback build failed', e);
                      }
                    } catch (e) { console.debug('[AutoList Pro] handleDeleteAndRelist: storage callback error', e); }
                  });
                } catch (e) {
                  try { handleDeleteAndRelist(listingEl); } catch (ee) { console.debug('[AutoList Pro] handleDeleteAndRelist fallback failed', ee); }
                }
              });
            } catch (e) {}
          };
        }
        try { publishBtn.addEventListener('click', publishBtn._ffm_handleDelete); } catch (e) {}
            publishBtn.textContent = 'Delete / Relist';
            publishBtn.classList.add('dnr-btn');
            try { console.debug('[AutoList Pro] updateListingStatusUI: swapped to Delete/Relist', { inventory: listingEl.getAttribute && listingEl.getAttribute('data-inventory-name') }); } catch(_) {}
      } else {
        listingEl.dataset.isActive = 'false';
        // restore original publish behavior
        try { if (publishBtn._ffm_handleDelete) publishBtn.removeEventListener('click', publishBtn._ffm_handleDelete); } catch (e) {}
        try { if (publishBtn._ffm_handlePublish) { publishBtn.addEventListener('click', publishBtn._ffm_handlePublish); } } catch (e) {}
            publishBtn.textContent = 'Publish';
            publishBtn.classList.remove('dnr-btn');
            try { console.debug('[AutoList Pro] updateListingStatusUI: restored Publish', { inventory: listingEl.getAttribute && listingEl.getAttribute('data-inventory-name') }); } catch(_) {}
      }
    } catch (e) {}
  } catch (e) { console.debug('updateListingStatusUI error', e); }
}

