    if (!validListings.length) {
      try { console.log('[AS MATCH] scraped result empty — skipping ffmUpdateActiveListingFlags'); } catch (e) {}
      return null;
    }
    const scraped = validListings;
    try { console.log('[AS MATCH] merged result received — invoking matcher', { count: scraped.length }); } catch (e) {}

    // Try known matcher candidates in preferred order (non-destructive fallbacks)
    if (typeof ffmMatchActiveListingsToSavedListings === 'function') {
      try {
        const res = await Promise.resolve(ffmMatchActiveListingsToSavedListings(scraped, { source: 'AS', authoritative: true }));
        try { console.log('[AS MATCH] ffmMatchActiveListingsToSavedListings completed', { resultLen: Array.isArray(res) ? res.length : (res ? 1 : 0) }); } catch (e) {}
        return res;
      } catch (e) { console.error('[AS MATCH] ffmMatchActiveListingsToSavedListings threw', e); }
    }

    if (typeof ffmApplyActiveFlagsFromActiveListings === 'function') {
      try {
        const res = await Promise.resolve(ffmApplyActiveFlagsFromActiveListings(scraped, { source: 'AS', authoritative: true }));
        try { console.log('[AS MATCH] ffmApplyActiveFlagsFromActiveListings completed'); } catch (e) {}
        return res;
      } catch (e) { console.error('[AS MATCH] ffmApplyActiveFlagsFromActiveListings threw', e); }
    }

    if (typeof ffmReconcileActiveListings === 'function') {
      try {
        const res = await Promise.resolve(ffmReconcileActiveListings(scraped, { source: 'AS', authoritative: true }));
        try { console.log('[AS MATCH] ffmReconcileActiveListings completed'); } catch (e) {}
        return res;
      } catch (e) { console.error('[AS MATCH] ffmReconcileActiveListings threw', e); }
    }

    if (typeof ffmUpdateActiveFlagsFromMarketplace === 'function') {
      try {
        const res = await Promise.resolve(ffmUpdateActiveFlagsFromMarketplace(scraped, { source: 'AS', authoritative: true }));
        try { console.log('[AS MATCH] ffmUpdateActiveFlagsFromMarketplace completed'); } catch (e) {}
        return res;
      } catch (e) { console.error('[AS MATCH] ffmUpdateActiveFlagsFromMarketplace threw', e); }
    }

    // Final fallback: the in-place updater used elsewhere in the popup
