// Simple placeholder auth flow (replace with real OAuth later)
async function driveToggleConnect() {
  try {
    // Try to establish OAuth with user-provided client id using launchWebAuthFlow
    const clientId = await new Promise((res) => storageGet({ drive_client_id: '' }, (r) => res(r.drive_client_id || '')));
      if (!driveConnected) { 
         if (!clientId) alert('Please paste your Google OAuth Client ID in the input and click Save before connecting.');
         // Attempt to connect to Google Drive
      // Build an OAuth URL for Google Drive (v2/v3) using PKCE-less implicit flow with response_type=token
      // We request https://www.googleapis.com/auth/drive.readonly and https://www.googleapis.com/auth/drive.file
      const redirectUri = chrome.identity.getRedirectURL();
    const scope = encodeURIComponent('https://www.googleapis.com/auth/drive.file https://www.googleapis.com/auth/drive.readonly https://www.googleapis.com/auth/drive.metadata.readonly');
      const authUrl = `https://accounts.google.com/o/oauth2/v2/auth?client_id=${encodeURIComponent(clientId)}&response_type=token&redirect_uri=${encodeURIComponent(redirectUri)}&scope=${scope}&prompt=consent`;

      try {
        const resultUrl = await new Promise((resolve, reject) => {
          chrome.identity.launchWebAuthFlow({ url: authUrl, interactive: true }, (redirectedTo) => {
            if (chrome.runtime.lastError) return reject(chrome.runtime.lastError);
            resolve(redirectedTo);
          });
        });
        // Parse the resulting fragment for access_token
        const hash = (resultUrl || '').split('#')[1] || '';
        const params = new URLSearchParams(hash);
        const token = params.get('access_token');
        if (!token) { alert('Could not obtain access token.'); return; }
        // Store token (short-lived) and mark connected
        storageSet({ drive_connected: true, drive_access_token: token }, () => { driveConnected = true; updateDriveStatusUI(); statusBar.textContent = 'Drive connected.'; });
      } catch (err) {
        console.error('launchWebAuthFlow error details:', {
          error: err,
          message: err?.message || 'No error message',
          toString: String(err),
          stack: err?.stack,
          lastError: chrome.runtime.lastError
        });
        
        // If redirect_uri_mismatch, show the exact redirect URI to copy into Cloud Console
        try {
          const redirectUri = chrome.identity.getRedirectURL();
          const errorMsg = err?.message || String(err) || 'Unknown error';
          
          if (errorMsg.toLowerCase().includes('redirect_uri_mismatch')) {
            // Show setup instructions in console and alert
            window.showOAuthSetupInstructions();
            alert('Drive connect failed: redirect_uri_mismatch.\n\nRegister this Redirect URI in Google Cloud Console (Authorized redirect URIs):\n' + redirectUri + '\n\nThen refresh the extension and try again.\n\nCheck the console for detailed setup instructions.');
          } else if (errorMsg.toLowerCase().includes('access_denied')) {
            alert('Drive connect failed: Access denied.\n\nYou may have cancelled the authorization or denied permissions.');
          } else if (errorMsg.toLowerCase().includes('invalid_client')) {
            alert('Drive connect failed: Invalid client ID.\n\nPlease check that your Google OAuth Client ID is correct and properly configured in Google Cloud Console.');
          } else {
            alert('Drive connect failed: ' + errorMsg + '\n\nCheck the console for more details.\n\nRedirect URI for Google Cloud Console:\n' + redirectUri);
          }
        } catch (e) { 
          console.error('Error handling failed:', e);
          alert('Drive connect failed. See console for details.'); 
        }
      }
      
    } else {
      // disconnect: remove stored token
      driveConnected = false;
      storageSet({ drive_connected: false, drive_access_token: '' }, () => { updateDriveStatusUI(); statusBar.textContent = 'Drive disconnected.'; });
    }
  } catch (e) { console.error('driveToggleConnect error', e); }
}

