// Initialize CFST launch helper: open/focus Sharetown tab, set flags, enter select mode
function initCFSTLaunch() {
  try {
    // Enter select mode UI locally (do not set session flag here — background manages it)
    try { if (typeof enterSelectMode === 'function') enterSelectMode(); } catch (e) { console.debug('[AutoList Pro popup] enterSelectMode failed from initCFSTLaunch', e); }

    // Mark that the popup is requesting a new Sharetown tab so enterSelectMode's
    // fallback doesn't also ask the background and create a duplicate.
    try {
      try { window.__ffm_requesting_sharetown_tab = Date.now(); } catch (e) {}
      try { setTimeout(() => { try { window.__ffm_requesting_sharetown_tab = 0; } catch (e) {} }, 6000); } catch (e) {}
    } catch (e) {}
    // Request background to open a NEW Sharetown tab (background creates it).
    try { chrome.runtime.sendMessage({ action: 'ffm_start_select_mode_popup', openNew: true }, () => {}); } catch (e) {}
  } catch (e) {
    console.debug('[AutoList Pro popup] initCFSTLaunch failed', e);
  }
}

