// --- Listen for pre-publish events so the popup can remove the timestamp before the job runs ---
try {
  chrome.runtime.onMessage.addListener((msg) => {
    try {
      if (!msg || msg.action !== 'pre-publish') return;
      const invName = msg.inventoryName || msg.name || msg.title || null;
      const norm = invName ? normalizeInventoryName(invName) : null;
      try { console.debug('[AutoList Pro] Popup received pre-publish for', invName); } catch (e) {}

      if (norm) {
        try {
          const card = Array.from(document.querySelectorAll('[data-inventory-name]')).find(el => {
            try { return normalizeInventoryName(el.getAttribute('data-inventory-name') || '') === norm; } catch (e) { return false; }
          });
          if (card) {
            try { card.querySelectorAll('.alarm-inline, .alarm-ts').forEach(el => el.remove()); } catch (e) {}
            try { console.debug('[AutoList Pro] Pre-publish: removed timestamp for', invName); } catch (e) {}
            return;
          }
        } catch (e) { /* best-effort */ }
      }

      // fallback: nothing matched — best-effort global remove
      try { document.querySelectorAll('.alarm-inline, .alarm-ts').forEach(el => el.remove()); } catch (e) {}
    } catch (e) { /* swallow */ }
  });
} catch (e) { console.warn('pre-publish listener failed to attach', e); }

