// Open the extension UI in a sidebar-like window. Chrome supports sidePanel in newer builds, otherwise use a small docked window.
async function openSidebar() {
  try {
    // Preferred behavior now: always open/focus Marketplace Selling, then spawn the overlay there
    const spawnOnMarketplace = async () => {
      // Prefer opening the general Marketplace feed so users can select images from listings.
      const targetUrl = 'https://www.facebook.com/marketplace';
      const findTab = async () => await new Promise((resolve)=>{ try { chrome.tabs.query({}, (tabs)=>{ resolve((tabs||[]).find(t=>t.url && t.url.includes('/marketplace'))||null); }); } catch(e){ resolve(null);} });
      let mtab = await findTab();
      if (!mtab) {
        mtab = await new Promise((resolve)=>{ try { chrome.tabs.create({ url: targetUrl }, (t)=> resolve(t)); } catch(e){ resolve(null);} });
      } else {
        try { chrome.windows.update(mtab.windowId, { focused: true }); } catch(e){}
        try { chrome.tabs.update(mtab.id, { active: true }); } catch(e){}
      }
      if (!mtab || !mtab.id) return false;
      // retry sendMessage a few times until the content script is ready
      // overlay spawning disabled: do not send runtime message to create in-page overlay
      const trySend = () => new Promise((resolve) => { resolve(null); });
      for (let i=0;i<10;i++) {
        const r = await trySend();
        if (r && r.ok) return true;
        await new Promise(res=>setTimeout(res, 500));
      }
      return false;
    };

    const placed = await spawnOnMarketplace();
    if (placed) {
      statusBar && (statusBar.textContent = 'Opened Create overlay on Marketplace.');
      // When running embedded inside the Side Panel, don't close the panel/popup — leave it open.
      if (!ffmEmbedded) {
        try { window.close(); } catch (e) {}
      }
      return;
    }

    // Final fallback: open a small window docked to the side, then refocus the original tab so we don't steal the page
    const url = chrome.runtime.getURL('popup.html');
    // Request the background script to open the popup window. Background will
    // ensure existing extension popups are closed first to avoid duplicates.
      try {
      try { ffmSendMessage({ action: 'open-popup' }, (resp) => { try { if (resp && resp.opened) { statusBar && (statusBar.textContent = 'Opened window (non-intrusive).'); if (!ffmEmbedded) { try { window.close(); } catch (e) {} } } } catch (e) {} }); } catch (e) {}
    } catch (e) {
      // Fallback to direct create if messaging fails
      const current = await new Promise((resolve) => { try { chrome.windows.getCurrent((w) => resolve(w)); } catch (err) { resolve(null); } });
      const wnd = await new Promise((resolve) => {
        try {
          chrome.windows.create({ url, type: 'normal', state: 'normal', width: 574, height: Math.min(875, screen.height - 80), left: Math.max(0, screen.width - 600), focused: false }, (w) => resolve(w));
        } catch (err) { resolve(null); }
      });
      try { current && chrome.windows.update(current.id, { focused: true }); } catch (err) {}
  if (wnd) { statusBar && (statusBar.textContent = 'Opened window (non-intrusive).'); if (!ffmEmbedded) { try { window.close(); } catch (err) {} } }
    }
  } catch (e) { console.debug('openSidebar error', e); alert('Could not open sidebar. See console for details.'); }
}

