// Record a per-listing change entry on the manifest object (in-memory)
function ffmRecordListingChange(manifest, listingId, fields = []) {
  try {
    if (!manifest || !listingId) return;
    manifest.changes = manifest.changes || {};
    manifest.changes[listingId] = Object.assign({}, manifest.changes[listingId] || {}, {
      type: (manifest.changes && manifest.changes[listingId] && manifest.changes[listingId].type === 'added') ? 'updated' : 'updated',
      fields: Array.isArray(fields) ? fields : [],
      updatedAt: Date.now()
    });
  } catch (e) { console.debug('ffmRecordListingChange error', e); }
}

// Client instance id helper (stable per browser profile, stored locally)
async function ffmGetClientInstanceId() {
  try {
    const key = 'ffm_client_instance_id';
    const existing = await new Promise((res) => { try { chrome.storage.local.get([key], (r) => res(r && r[key] ? r[key] : null)); } catch (e) { res(null); } });
    if (existing) return existing;
    // generate
    const id = (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') ? crypto.randomUUID() : ('ffm-' + Date.now() + '-' + Math.random().toString(36).slice(2,10));
    try { const obj = {}; obj[key] = id; chrome.storage.local.set(obj, ()=>{}); } catch (e) {}
    return id;
  } catch (e) { return null; }
}

// Compute a lightweight delta between local ids and cloud manifest using manifest.changes
function ffmComputeCloudDelta(localIds = [], cloudManifest = {}) {
  try {
    const cloudIds = Array.isArray(cloudManifest.listings) ? cloudManifest.listings.map(String) : [];
    const changes = (cloudManifest.changes && typeof cloudManifest.changes === 'object') ? cloudManifest.changes : {};
    const added = cloudIds.filter(id => !localIds.includes(String(id)));
    const updated = Object.keys(changes || {}).filter(id => localIds.includes(String(id)));
    return { added, updated };
  } catch (e) { console.debug('ffmComputeCloudDelta error', e); return { added: [], updated: [] }; }
}

function ffmBuildChangeSummary(manifest = {}, delta = { added: [], updated: [] }) {
  try {
    const lines = [];
    if (Array.isArray(delta.added) && delta.added.length) lines.push(`New listings: ${delta.added.length}`);
    if (Array.isArray(delta.updated) && delta.updated.length) lines.push(`Updated listings: ${delta.updated.length}`);
    return lines.join('\n');
  } catch (e) { return ''; }
}

// Upload backup manifest listing file to users/<uid>/backup_manifest.json
async function uploadUserBackupManifestToS3(uid, listingsArray) {
  if (!uid) throw new Error('uploadUserBackupManifestToS3 requires uid');
  let payload = null;
  const key = `users/${uid}/backup_manifest.json`;
  // If caller passed a full manifest object, use it (update timestamp)
  if (listingsArray && typeof listingsArray === 'object' && Array.isArray(listingsArray.listings)) {
    payload = Object.assign({}, listingsArray);
    payload.updatedAt = Date.now();
  } else {
    // Build payload from array of ids; try to preserve existing manifest.changes if present
    payload = { version: 1, updatedAt: Date.now(), listings: Array.isArray(listingsArray) ? listingsArray : [] };
    try {
      const signed = await awsSignDownload(key).catch(() => null);
      if (signed && signed.url) {
        const resp = await fetch(signed.url).catch(() => null);
        if (resp && resp.ok) {
          const existing = await resp.json().catch(() => null);
          if (existing && existing.changes && typeof existing.changes === 'object') {
            payload.changes = Object.assign({}, existing.changes);
          }
        }
      }
    } catch (e) { console.debug('[AutoList Pro] merge existing manifest failed', e); }

    // Enrich change entries with local inventory names when possible
    try {
      const local = await new Promise((res) => { try { chrome.storage.local.get(['ffm_saved_listings','listings'], (r) => res((r && (r.ffm_saved_listings || r.listings)) || [])); } catch (e) { res([]); } });
      const map = {};
      for (const l of Array.isArray(local) ? local : []) {
        try { const id = String(l && (l.listingId || l.id || l.inventoryId || '')); if (id) map[id] = l.inventoryName || l.title || map[id] || null; } catch(e){}
      }
      if (!payload.changes) payload.changes = {};
      for (const id of payload.listings || []) {
        try {
          if (map[id]) {
            payload.changes[id] = Object.assign({}, payload.changes[id] || {}, { inventoryName: map[id] });
          }
        } catch(e){}
      }
    } catch (e) { console.debug('[AutoList Pro] enrich manifest with local names failed', e); }
  }
  // Attach lastWriter metadata (client instance + timestamp). Do NOT include extensionId.
  try {
    const clientId = await ffmGetClientInstanceId().catch(()=>null);
    payload.lastWriter = { clientId: clientId || null, writtenAt: Date.now() };
  } catch (e) { console.debug('[AutoList Pro] attach lastWriter failed', e); }
  return uploadToS3({ key, body: JSON.stringify(payload), contentType: 'application/json' });
}
async function awsSignDownload(key) {
  // Cloud sync removed — return null instead of throwing so callers' existing
  // "no signed URL" fallback paths handle this the same as any other failure.
  const base = await getAwsApiBase();
  if (!base) return null;
  const url = base.replace(/\/$/, '') + '/sign-download?key=' + encodeURIComponent(key);
  try {
    // Use fetchWithTimeout for robustness and log debug info on failure
    let resp;
    try { resp = await fetchWithTimeout(url, {}, 10000); } catch (e) { console.error('[AutoList Pro] awsSignDownload fetch error', String(e), { url, key }); throw e; }
    if (!resp.ok) {
      const bodyText = await resp.text().catch(() => '<no-body>');
      console.error('[AutoList Pro] awsSignDownload failed', { status: resp.status, body: bodyText, url, key });
      throw new Error('sign-download failed: ' + (bodyText || resp.status));
    }
    const j = await resp.json().catch((e) => { console.error('[AutoList Pro] awsSignDownload parse json failed', e, { url, key }); throw e; });
    if (!j || !j.url) {
      console.error('[AutoList Pro] awsSignDownload returned no url', { url, key, respJson: j });
      throw new Error('sign-download returned no url');
    }
    return j;
  } catch (e) {
    console.error('[AutoList Pro] awsSignDownload error', e, { url, key });
    throw e;
  }
}
async function awsExists(key) {
  const base = await getAwsApiBase();
  if (!base) return false;
  try {
    const resp = await fetch(base.replace(/\/$/, '') + '/exists?key=' + encodeURIComponent(key));
    if (!resp.ok) return false;
    const j = await resp.json();
    return !!j.exists;
  } catch (e) { return false; }
}
// Delete multiple S3 objects by keys
async function awsDeleteObjects(keys = [], opts = {}) {
  // opts: { minAgeDays: number, adminToken: string }
  if (!Array.isArray(keys) || keys.length === 0) return true;
  // Client-side filtering: backend only accepts mobile/, listings/, metadata/ prefixes
  try {
    const allowedPrefixes = ['mobile/', 'listings/', 'metadata/', 'users/'];
    const original = Array.isArray(keys) ? keys.slice() : [];
    console.debug('awsDeleteObjects raw input:', JSON.stringify(original));
    const normalized = [];
    const bad = [];
    for (let raw of original) {
      if (typeof raw !== 'string') { bad.push(raw); continue; }
      let k = raw;
      // Do NOT decode percent-encoding here — S3 keys are literal and may contain %20 etc.
      // If it looks like a full URL (https:// or http:// or s3://), extract the path part
      try {
        if (/^[a-zA-Z]+:\/\//.test(k)) {
          const m = k.match(/(mobile\/|listings\/|metadata\/).*/);
          if (m && m[0]) k = m[0]; else {
            try { const u = new URL(k); k = (u.pathname || '') + (u.search || '') + (u.hash || ''); if (k.startsWith('/')) k = k.slice(1); } catch(_){}
          }
        }
      } catch (e) {}
      // Remove any leading slashes
      if (k.startsWith('/')) k = k.slice(1);
      // After normalization, ensure it starts with an allowed prefix
      if (allowedPrefixes.some(p => k.startsWith(p))) {
        normalized.push(k);
      } else {
        bad.push(raw);
      }
    }
    if (bad.length) console.debug('awsDeleteObjects: discarded non-normalized keys', JSON.stringify(bad));
    if (!normalized.length) {
      console.warn('awsDeleteObjects: no allowed keys after normalization', JSON.stringify(original));
      throw new Error('No allowed S3 keys to delete (allowed prefixes: mobile/, listings/, metadata/, users/)');
    }
    keys = normalized;
    console.debug('awsDeleteObjects: normalized keys:', JSON.stringify(keys));
  } catch (e) {
    console.debug('awsDeleteObjects validation error', e);
    throw e;
  }
  const base = await getAwsApiBase();
  if (!base) throw new Error('AWS API base not set');
  const body = { keys };
  if (opts && typeof opts.minAgeDays === 'number') body.minAgeDays = opts.minAgeDays;
  if (opts && typeof opts.adminToken === 'string' && opts.adminToken) body.adminToken = opts.adminToken;
  const resp = await fetch(base.replace(/\/$/, '') + '/delete-objects', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body)
  });
  if (!resp.ok) {
    const text = await resp.text().catch(()=>null);
    console.error('delete-objects response failed', resp.status, text);
    const errMsg = text ? `delete-objects failed: ${text}` : `delete-objects failed with status ${resp.status}`;
    throw new Error(errMsg);
  }
  return resp.json().catch(()=>({}));
}
