// Export/Import backup logic removed — feature deprecated.
 
 // --- Sync Listings UI wiring ------------------------------------------------
 const syncListBtn = document.getElementById('sync-listings-btn');
 const syncListModal = document.getElementById('sync-list-modal');
 const syncListContents = document.getElementById('sync-list-contents');
 const syncListClose = document.getElementById('sync-list-close');
 const syncListRefresh = document.getElementById('sync-list-refresh');
 const syncListImportAll = document.getElementById('sync-list-import-all');
 // cache the latest found items so Import All can reuse
 let syncListLatestItems = [];
 
 // Search Drive for files ending with _listing.json (returns array of {id,name,createdTime})
 async function searchDriveForListingMetadata(pageToken = null, pageSize = 50) {
   try {
     const token = await getDriveAuthToken(true);
     if (!token) return { items: [], nextPageToken: null };
 
     // Query for JSON files whose names end with _listing.json
     // Drive query language doesn't support endsWith, use name contains and filter client-side
     const q = `mimeType='application/json' and trashed=false and name contains '_listing.json'`;
     const params = new URLSearchParams({ q, fields: `nextPageToken, files(id,name,createdTime)`, pageSize: String(pageSize) });
     if (pageToken) params.append('pageToken', pageToken);
     let resp = await fetch(`https://www.googleapis.com/drive/v3/files?${params.toString()}`, { headers: { 'Authorization': 'Bearer ' + token } });
     if (resp.status === 401 || resp.status === 403) {
       const newToken = await refreshDriveAccessToken(true);
       if (newToken) { resp = await fetch(`https://www.googleapis.com/drive/v3/files?${params.toString()}`, { headers: { 'Authorization': 'Bearer ' + newToken } }); }
     }
     if (!resp.ok) { console.debug('searchDriveForListingMetadata failed', resp.status); return { items: [], nextPageToken: null }; }
     const json = await resp.json();
     const files = (json.files || []).filter(f => (f.name || '').toLowerCase().endsWith('_listing.json')).map(f => ({ id: f.id, name: f.name, createdTime: f.createdTime }));
     return { items: files, nextPageToken: json.nextPageToken || null };
   } catch (e) { console.debug('searchDriveForListingMetadata error', e); return { items: [], nextPageToken: null }; }
 }
 
 // Fetch all pages of Drive listing metadata
 async function searchDriveForListingMetadataAll() {
   let items = [];
   let token = null;
   for (let i = 0; i < 50; i++) { // hard cap pages to avoid infinite loops
     const res = await searchDriveForListingMetadata(token);
     items = items.concat(res.items || []);
     token = res.nextPageToken || null;
     if (!token) break;
   }

    // Settings panel logout button (also visible inside the Account panel)
    const settingsLogoutBtn = document.getElementById('ffm-settings-logout');
    if (settingsLogoutBtn) {
      try {
        settingsLogoutBtn.addEventListener('click', async () => {
          try {
            if (typeof FFM_AUTH_DISABLED !== 'undefined' && FFM_AUTH_DISABLED) {
              console.info('[AutoList Pro] Logout disabled (Phase 1)');
              return;
            }
            try { await new Promise((res) => { try { chrome.runtime.sendMessage({ type: 'ffm-auth:logout' }, (r) => res(r)); } catch (e) { res({ ok: false }); } }); } catch (e) { console.warn('[AutoList Pro] signOut failed', e); }
            try { await ffmAuthClearSession(); } catch (e) {}
            try { window.location.reload(); } catch (e) {}
          } catch (e) {}
        });
      } catch (e) {}
    }
   return items;
 }
 
function renderSyncListItems(items) {
  try {
    if (!syncListContents) return;
    syncListContents.innerHTML = '';
    if (!items || !items.length) { syncListContents.innerHTML = '<div style="padding:8px;color:#666;">No listing metadata files found in Drive.</div>'; return; }
    syncListLatestItems = items.slice();
    items.forEach((it) => {
      const row = document.createElement('div'); row.className = 'sync-list-item';
      const meta = document.createElement('div'); meta.className = 'meta'; meta.textContent = `${it.name} — ${it.createdTime ? new Date(it.createdTime).toLocaleString() : ''}`;
      const actions = document.createElement('div');
      const importBtn = document.createElement('button'); importBtn.className = 'action-btn'; importBtn.textContent = 'Import';
      importBtn.addEventListener('click', async () => {
        try {
          const includeMedia = await showConfirm('Download media (images/videos) from Drive when importing this listing?\n\nOK = download and attach\nCancel = metadata only.', { yesLabel: 'Download + Attach', noLabel: 'Metadata Only' });
          syncListContents.style.pointerEvents = 'none';
          importBtn.disabled = true; importBtn.textContent = 'Importing...';
          await restoreListingFromDrive(it.id, { rehydrateMedia: includeMedia });
        } catch (e) { console.debug('import click error', e); alert('Import error'); }
        finally { syncListContents.style.pointerEvents = ''; importBtn.disabled = false; importBtn.textContent = 'Import'; }
      });
      actions.appendChild(importBtn);
      row.appendChild(meta); row.appendChild(actions); syncListContents.appendChild(row);
    });
  } catch (e) { console.debug('renderSyncListItems error', e); }
}

// Render an AWS-style sync list: `items` is an array of inventoryName strings
function renderAwsSyncList(items) {
  try {
    if (!syncListContents) return;
    syncListContents.innerHTML = '';
    if (!items || !items.length) { syncListContents.innerHTML = '<div style="padding:8px;color:#666;">No listings found in Cloud.</div>'; return; }
    syncListLatestItems = Array.isArray(items) ? items.slice() : [];

    const ctrlRow = document.createElement('div'); ctrlRow.style.display = 'flex'; ctrlRow.style.justifyContent = 'space-between'; ctrlRow.style.alignItems = 'center'; ctrlRow.style.marginBottom = '8px';
    const leftWrap = document.createElement('div');
    const selectAll = document.createElement('button'); selectAll.className = 'action-btn'; selectAll.textContent = 'Select All'; selectAll.type = 'button';
    leftWrap.appendChild(selectAll);
    const rightWrap = document.createElement('div');
    const importSelectedBtn = document.createElement('button'); importSelectedBtn.className = 'action-btn'; importSelectedBtn.textContent = 'Import Selected'; importSelectedBtn.type = 'button';
    const importAllBtn = document.createElement('button'); importAllBtn.className = 'action-btn'; importAllBtn.textContent = 'Import All'; importAllBtn.type = 'button'; importAllBtn.style.marginLeft = '8px';
    rightWrap.appendChild(importSelectedBtn); rightWrap.appendChild(importAllBtn);
    ctrlRow.appendChild(leftWrap); ctrlRow.appendChild(rightWrap); syncListContents.appendChild(ctrlRow);

    const rows = [];
    items.forEach((inv) => {
      const row = document.createElement('div'); row.className = 'sync-list-item'; row.style.display = 'flex'; row.style.alignItems = 'center'; row.style.justifyContent = 'space-between'; row.style.gap = '8px';
      const left = document.createElement('div'); left.style.display = 'flex'; left.style.alignItems = 'center'; left.style.gap = '8px';
      const chk = document.createElement('input'); chk.type = 'checkbox'; chk.className = 'sync-aws-chk'; chk.dataset.inventory = inv;
      const label = document.createElement('div'); label.className = 'meta'; label.textContent = inv;
      // Prefer showing the canonical inventoryName from metadata (not title)
      (async () => {
        try {
          const meta = await awsGetMetadata(inv).catch(() => null);
          if (meta && meta.inventoryName) {
            label.textContent = meta.inventoryName;
          }
        } catch (e) { console.debug('renderAwsSyncList: metadata fetch error for', inv, e); }
      })();
      left.appendChild(chk); left.appendChild(label);
      const actions = document.createElement('div');
      const imp = document.createElement('button'); imp.className = 'action-btn'; imp.textContent = 'Import';
      imp.addEventListener('click', async () => {
        try {
          imp.disabled = true; imp.textContent = 'Importing...';
          const attach = await showConfirm('Download media (images/videos) from Cloud when importing this listing?\n\nOK = Download + Attach\nCancel = Metadata only.', { yesLabel: 'Download + Attach', noLabel: 'Metadata Only' });
          await importAwsListing(inv, attach);
          try { window.showToast && window.showToast(`Imported ${inv}`, 'success'); } catch (e) {}
        } catch (e) { console.debug('import aws single error', e); alert('Import failed'); }
        finally { imp.disabled = false; imp.textContent = 'Import'; }
      });
      actions.appendChild(imp);
      row.appendChild(left); row.appendChild(actions); syncListContents.appendChild(row);
      rows.push({ inv, chk });
    });

    selectAll.addEventListener('click', () => { const allChecked = rows.every(r => r.chk.checked); rows.forEach(r => r.chk.checked = !allChecked); selectAll.textContent = allChecked ? 'Select All' : 'Deselect All'; });

    importSelectedBtn.addEventListener('click', async () => {
      try {
        const selected = rows.filter(r => r.chk.checked).map(r => r.inv);
        if (!selected.length) { alert('No listings selected.'); return; }
        const attach = await showConfirm(`Import ${selected.length} listing(s) with media?\n\nOK = Download + Attach\nCancel = Metadata only.`, { yesLabel: 'Download + Attach', noLabel: 'Metadata Only' });
        syncListContents.style.pointerEvents = 'none'; importSelectedBtn.disabled = true; importSelectedBtn.textContent = 'Importing...';
        for (let i = 0; i < selected.length; i++) { try { await importAwsListing(selected[i], attach); } catch (e) { console.debug('importSelected per-item error', e); } }
        try { window.showToast && window.showToast(`Imported ${selected.length} listing(s)`, 'success'); } catch (e) {}
      } catch (e) { console.debug('importSelected error', e); alert('Import Selected failed'); }
      finally { syncListContents.style.pointerEvents = ''; importSelectedBtn.disabled = false; importSelectedBtn.textContent = 'Import Selected'; }
    });

    importAllBtn.addEventListener('click', async () => {
      try {
        const attach = await showConfirm(`Import all ${rows.length} listing(s) with media?\n\nOK = Download + Attach\nCancel = Metadata only.`, { yesLabel: 'Import All', noLabel: 'Metadata only' });
        syncListContents.style.pointerEvents = 'none'; importAllBtn.disabled = true; importAllBtn.textContent = 'Importing...';
        for (let i = 0; i < rows.length; i++) { try { await importAwsListing(rows[i].inv, attach); } catch (e) { console.debug('importAll per-item error', e); } }
        try { window.showToast && window.showToast(`Imported ${rows.length} listing(s)`, 'success'); } catch (e) {}
      } catch (e) { console.debug('importAll error', e); alert('Import All failed'); }
      finally { syncListContents.style.pointerEvents = ''; importAllBtn.disabled = false; importAllBtn.textContent = 'Import All'; }
    });

  } catch (e) { console.debug('renderAwsSyncList error', e); if (syncListContents) syncListContents.innerHTML = 'Error rendering AWS list.'; }
}

// Import a single AWS listing into local storage. attachMedia controls whether to download images/videos.
async function importAwsListing(inventoryName, attachMedia = true) {
  try {
    if (!inventoryName) return false;
    const remote = await awsGetMetadata(inventoryName);
    if (!remote) return false;
    // Skip legacy remote metadata that lacks a modern ffm listingId
    if (!isValidFfmId(remote.listingId) && !isValidFfmId(remote.id)) {
      try { console.debug('[AutoList Pro] importAwsListing: skipping legacy remote listing (no ffm id)', inventoryName); } catch (e) {}
      try { window.showToast && window.showToast('Skipping legacy cloud listing (no ffm id)', { type: 'info' }); } catch (e) {}
      return false;
    }
    const localStore = await new Promise((res) => storageGet({ listings: [] }, (r) => res(r.listings || [])));
    const existingIx = localStore.findIndex(x => x && x.inventoryName === inventoryName);
    if (existingIx >= 0) {
      const l = localStore[existingIx];
      if ((!l.s3ImageKeys || !l.s3ImageKeys.length) && Array.isArray(remote.s3ImageKeys)) l.s3ImageKeys = remote.s3ImageKeys.slice();
      if ((!l.s3VideoKeys || !l.s3VideoKeys.length) && Array.isArray(remote.s3VideoKeys)) l.s3VideoKeys = remote.s3VideoKeys.slice();
      try { const localDesc = (l.description || '').toString().trim(); const remoteDesc = (remote.description || '').toString().trim(); if (!localDesc && remoteDesc) l.description = remote.description; } catch (e) {}
      if (attachMedia) {
        try {
          if (Array.isArray(l.s3ImageKeys)) {
            for (let i = 0; i < l.s3ImageKeys.length; i++) {
              try { const dataUrl = await downloadFromAwsS3(l.s3ImageKeys[i]); if (dataUrl) l.images = (l.images || []).concat([dataUrl]); } catch (e) { console.debug('download image error', e); }
            }
          }
          if (Array.isArray(l.s3VideoKeys)) {
            for (let i = 0; i < l.s3VideoKeys.length; i++) {
              try { const v = await downloadFromAwsS3(l.s3VideoKeys[i]); if (v) l.videos = (l.videos || []).concat([v]); } catch (e) { console.debug('download video error', e); }
            }
          }
        } catch (e) { console.debug('attachMedia error', e); }
      }
      await new Promise((r) => storageSet({ listings: prepareListingsForStorage(localStore) }, r));
      try { displaySavedListingsOnce(); } catch (e) {}
      return true;
    } else {
        const mapCat = (v) => { try { return /mattress/i.test((v||'').toString()) ? 'Furniture' : (v || ''); } catch (e) { return (v || ''); } };

        const listing = {
        inventoryName: remote.inventoryName || inventoryName,
        title: remote.title || '',
        price: remote.price || '',
        retailPrice: remote.retailPrice || '',
        category: mapCat(remote.category || 'Furniture'),
        condition: remote.condition || 'Used - Like New',
        bedSize: remote.bedSize || '',
        core: remote.core || '',
        comfortLevel: remote.comfortLevel || '',
        hideFromFriends: !!remote.hideFromFriends,
        description: remote.description || '',
        timestamp: remote.timestamp || Date.now(),
        s3ImageKeys: remote.s3ImageKeys || [],
        s3VideoKeys: remote.s3VideoKeys || [],
        images: [],
        videos: [],
        awsLinked: true
      };
      if (attachMedia) {
        try {
          for (let i = 0; i < listing.s3ImageKeys.length; i++) { try { const d = await downloadFromAwsS3(listing.s3ImageKeys[i]); if (d) listing.images.push(d); } catch(e){console.debug('dl img',e);} }
          for (let i = 0; i < listing.s3VideoKeys.length; i++) { try { const v = await downloadFromAwsS3(listing.s3VideoKeys[i]); if (v) listing.videos.push(v); } catch(e){console.debug('dl vid',e);} }
        } catch (e) { console.debug('importAwsListing media download error', e); }
      }
      await new Promise((resolve) => storageGet({ listings: [] }, (res) => {
        const arr = res.listings || [];
        arr.push(listing);
        storageSet({ listings: prepareListingsForStorage(arr) }, resolve);
      }));
      try { displaySavedListingsOnce(); } catch (e) {}
      return true;
    }
  } catch (e) { console.debug('importAwsListing error', e); return false; }
}
 
 async function openSyncListModal() {
   try {
     if (!syncListModal) return;
     syncListModal.setAttribute('aria-hidden', 'false');
     // Store the currently focused element to restore focus later
     window.lastFocusedElement = document.activeElement;
     if (syncListContents) syncListContents.innerHTML = 'Searching...';
     // Add keyboard event listener for Escape key
     if (!syncListModal.escapeKeyListener) {
       syncListModal.escapeKeyListener = (e) => {
         if (e.key === 'Escape') {
           closeSyncListModal();
         }
       };
       document.addEventListener('keydown', syncListModal.escapeKeyListener);
     }
  // perform search (all pages) — choose provider-aware flow
  try {
    const provider = await getCloudProvider();
    if (provider === 'aws') {
      if (syncListContents) syncListContents.innerHTML = 'Querying Cloud...';
      let names = [];
      try {
        names = await awsListAllInventoryNames();
        renderAwsSyncList(names || []);
      } catch (e) {
        console.debug('openSyncListModal: aws list failed', e);
        try {
          const base = await getAwsApiBase();
          const msg = `Cloud listing query failed. API base: ${base || '<not-set>'}. See console for details.`;
          try { window.showToast && window.showToast(msg, { type: 'error' }); } catch(_){}
        } catch (_) {
          try { window.showToast && window.showToast('Cloud listing query failed. See console for details.', { type: 'error' }); } catch(_){}
        }
        // show an empty list so UI doesn't spin forever
        renderAwsSyncList([]);
      }
    } else {
      const all = await searchDriveForListingMetadataAll();
      renderSyncListItems(all || []);
    }
  } catch (e) {
    console.debug('openSyncListModal provider-aware error', e);
    const all = await searchDriveForListingMetadataAll();
    renderSyncListItems(all || []);
  }
     // Focus the close button for keyboard accessibility
     if (syncListClose) {
       setTimeout(() => syncListClose.focus(), 100);
     }
   } catch (e) { console.debug('openSyncListModal error', e); if (syncListContents) syncListContents.innerHTML = 'Search failed.'; }
 }
 
 function closeSyncListModal() {
   try {
     if (!syncListModal) return;
     // Remove keyboard event listener
     if (syncListModal.escapeKeyListener) {
       document.removeEventListener('keydown', syncListModal.escapeKeyListener);
       syncListModal.escapeKeyListener = null;
     }
     // Remove focus from any elements inside the modal before hiding it
     const focusedElement = document.activeElement;
     if (focusedElement && syncListModal.contains(focusedElement)) {
       focusedElement.blur();
     }
     // Small delay to ensure focus is removed before setting aria-hidden
     setTimeout(() => {
       // Hide the modal
       syncListModal.setAttribute('aria-hidden', 'true');
       // Restore focus to the element that was focused before opening the modal
       if (window.lastFocusedElement && window.lastFocusedElement.focus) {
         try {
           window.lastFocusedElement.focus();
         } catch (e) {
           console.debug('Could not restore focus:', e);
         }
       }
       window.lastFocusedElement = null;
     }, 10);
   } catch (e) {
     console.debug('closeSyncListModal error', e);
   }
 }
 
 if (syncListBtn) syncListBtn.addEventListener('click', (ev) => { ev.preventDefault(); openSyncListModal(); });
 if (syncListClose) syncListClose.addEventListener('click', closeSyncListModal);
if (syncListRefresh) syncListRefresh.addEventListener('click', async () => {
  try {
    if (syncListContents) syncListContents.innerHTML = 'Refreshing...';
    const provider = await getCloudProvider();
    if (provider === 'aws') {
      let names = [];
      try { names = await awsListAllInventoryNames(); } catch (e) { names = []; }
      renderAwsSyncList(names || []);
    } else {
      const all = await searchDriveForListingMetadataAll();
      renderSyncListItems(all || []);
    }
  } catch (e) { console.debug('refresh error', e); }
});
 
 // Import All handler: import every listed file with Download + Attach
 if (syncListImportAll) {
   syncListImportAll.addEventListener('click', async () => {
     try {
      // Provider-aware Import All
      const provider = await getCloudProvider();
      if (provider === 'aws') {
        if (!syncListLatestItems || !syncListLatestItems.length) {
          if (syncListContents) syncListContents.innerHTML = 'Querying Cloud...';
          let names = [];
          try { names = await awsListAllInventoryNames(); } catch (e) { names = []; }
          syncListLatestItems = names.slice();
        }
        const names = syncListLatestItems || [];
        if (!names.length) { alert('No listings found to import.'); return; }
        const ok = await showConfirm(`Import all ${names.length} listing(s) from Cloud with Download + Attach?`, { yesLabel: 'Import All', noLabel: 'Cancel' });
        if (!ok) return;
        if (syncListContents) syncListContents.style.pointerEvents = 'none';
        if (syncListImportAll) { syncListImportAll.disabled = true; syncListImportAll.textContent = 'Importing...'; }
        if (syncListRefresh) syncListRefresh.disabled = true;
        let imported = 0, failed = 0;
        for (let i = 0; i < names.length; i++) {
          try {
            const name = names[i];
            try { if (document.getElementById('sync-list-progress')) document.getElementById('sync-list-progress').textContent = `Importing ${i+1}/${names.length}: ${name}`; } catch(e){}
            const res = await importAwsListing(name, true);
            if (res) imported++; else failed++;
          } catch (e) { failed++; }
        }
        try { const progressEl = document.getElementById('sync-list-progress'); if (progressEl) progressEl.textContent = `Done: Imported ${imported}, Failed ${failed}.`; } catch (e) {}
        statusBar && (statusBar.textContent = `Bulk import finished: ${imported} new, ${failed} failed.`);
        try { displaySavedListingsOnce(); } catch (e) {}
      } else {
        if (!syncListLatestItems || !syncListLatestItems.length) {
          // refresh first
          if (syncListContents) syncListContents.innerHTML = 'Searching...';
          const all = await searchDriveForListingMetadataAll();
          renderSyncListItems(all || []);
        }
        const items = syncListLatestItems || [];
        if (!items.length) { alert('No listings found to import.'); return; }
        // confirm bulk import
        const ok = await showConfirm(`Import all ${items.length} listing(s) from Drive with Download + Attach?`, { yesLabel: 'Import All', noLabel: 'Cancel' });
        if (!ok) return;
        // disable UI
        if (syncListContents) syncListContents.style.pointerEvents = 'none';
        if (syncListImportAll) { syncListImportAll.disabled = true; syncListImportAll.textContent = 'Importing...'; }
        if (syncListRefresh) syncListRefresh.disabled = true;
        // progress message area
        let progressEl = document.getElementById('sync-list-progress');
        if (!progressEl && syncListContents) {
          progressEl = document.createElement('div');
          progressEl.id = 'sync-list-progress';
          progressEl.style.fontSize = '12px';
          progressEl.style.color = '#333';
          progressEl.style.margin = '6px 0';
          syncListContents.parentElement && syncListContents.parentElement.appendChild(progressEl);
        }
        let imported = 0, failed = 0, merged = 0;
        for (let i = 0; i < items.length; i++) {
          const it = items[i];
          try {
            if (progressEl) progressEl.textContent = `Importing ${i+1}/${items.length}: ${it.name}`;
            const nameFromFile = (it.name || '').replace(/_listing\.json$/i, '');
            const local = await new Promise((resolve)=> storageGet({ listings: [] }, (r)=> resolve(r.listings || [])));
            const existingIx = local.findIndex(x => x && x.inventoryName === nameFromFile);
            if (existingIx >= 0) {
              // Merge into existing listing to avoid duplicates
              try {
                let meta = await downloadJsonFromDrive(it.id);
                if (!meta) throw new Error('no-meta');
                const hasImgIds = Array.isArray(meta.driveFileIds) && meta.driveFileIds.length > 0;
                const hasVidIds = Array.isArray(meta.driveVideoIds) && meta.driveVideoIds.length > 0;
                if (!hasImgIds || !hasVidIds) {
                  const found = await findDriveMediaIdsForListing(meta.inventoryName || nameFromFile);
                  if (!hasImgIds && found.imageIds && found.imageIds.length) meta.driveFileIds = found.imageIds.slice();
                  if (!hasVidIds && found.videoIds && found.videoIds.length) meta.driveVideoIds = found.videoIds.slice();
                }
                const l = local[existingIx];
                l.driveMetaId = it.id;
                if ((!l.driveFileIds || !l.driveFileIds.length) && meta.driveFileIds && meta.driveFileIds.length) l.driveFileIds = meta.driveFileIds.slice();
                if ((!l.driveVideoIds || !l.driveVideoIds.length) && meta.driveVideoIds && meta.driveVideoIds.length) l.driveVideoIds = meta.driveVideoIds.slice();
                // Fill description if missing locally
                try {
                  const localDesc = (l.description || '').toString().trim();
                  const remoteDesc = (meta.description || '').toString().trim();
                  if (!localDesc && remoteDesc) l.description = meta.description;
                } catch (e) {}
                // Attach images/videos locally for Import All
                if (meta.driveFileIds && meta.driveFileIds.length) {
                  const imgs = await downloadImagesFromDrive(meta.driveFileIds);
                  if (imgs && imgs.length) {
                    const seen = new Set(Array.isArray(l.images) ? l.images : []);
                    l.images = (Array.isArray(l.images) ? l.images : []).concat(imgs.filter(x => !seen.has(x)));
                  }
                }
                if (meta.driveVideoIds && meta.driveVideoIds.length) {
                  const vids = await downloadImagesFromDrive(meta.driveVideoIds);
                  if (vids && vids.length) {
                    const seenV = new Set(Array.isArray(l.videos) ? l.videos : []);
                    l.videos = (Array.isArray(l.videos) ? l.videos : []).concat(vids.filter(x => !seenV.has(x)));
                  }
                }
                await new Promise((res)=> storageSet({ listings: prepareListingsForStorage(local) }, res));
                merged++;
              } catch (e) { failed++; continue; }
            } else {
              const res = await restoreListingFromDrive(it.id, { rehydrateMedia: true });
              if (res && res.success) imported++; else failed++;
            }
          } catch (e) { failed++; }
        }
        if (progressEl) progressEl.textContent = `Done: Imported ${imported}, Merged ${merged}, Failed ${failed}.`;
        statusBar && (statusBar.textContent = `Bulk import finished: ${imported} new, ${merged} updated, ${failed} failed.`);
        // refresh Saved Listings
        try { displaySavedListingsOnce(); } catch (e) {}
      }
     } catch (e) {
       console.debug('Import All error', e);
       alert('Import All failed. See console for details.');
     } finally {
       if (syncListContents) syncListContents.style.pointerEvents = '';
       if (syncListImportAll) { syncListImportAll.disabled = false; syncListImportAll.textContent = 'Import All'; }
       if (syncListRefresh) syncListRefresh.disabled = false;
     }
   });
 }

