// ----------------------
// Mobile Upload (QR) Flow (inline next to Images)
// ----------------------
const mobileUploadBtn = document.getElementById('mobile-upload-btn');
const mobileUploadInline = document.getElementById('mobile-upload-inline');

// Mobile upload via AWS S3: generate a one-time session, show a QR to a hosted mobile page,
// and list uploaded files under prefix mobile/<session>/
function renderMobileUploadUI(sessionId, mobilePageUrl) {
  try {
    if (!mobileUploadInline) return;
    mobileUploadInline.style.display = 'block';
    mobileUploadInline.innerHTML = '';
    const wrap = document.createElement('div');
    wrap.style.border = '1px dashed #ccc';
    wrap.style.padding = '8px';
    wrap.style.borderRadius = '6px';
    wrap.style.background = '#fff';

  const p = document.createElement('div'); p.style.fontSize = '12px'; p.style.marginBottom = '6px'; p.textContent = 'Scan this QR on your phone to upload photos/videos. They will appear below to import.';
  const link = document.createElement('a'); link.href = mobilePageUrl; link.target = '_blank'; link.textContent = mobilePageUrl; link.style.display = 'block'; link.style.wordBreak = 'break-all'; link.style.marginBottom = '8px';
    const qrDiv = document.createElement('div'); qrDiv.id = 'ffm-mobile-qr'; qrDiv.style.width = '160px'; qrDiv.style.height = '160px'; qrDiv.style.marginBottom = '8px';

  // Render QR using local QRCode library. Use the mobilePageUrl (folderLink was a stale name).
  try { if (window && window.QRCode) new QRCode(qrDiv, { text: mobilePageUrl, width: 160, height: 160 }); } catch (e) { console.debug('QRCode render failed', e); }

  const refreshBtn = document.createElement('button'); refreshBtn.type = 'button'; refreshBtn.className = 'action-btn'; refreshBtn.textContent = 'Refresh'; refreshBtn.style.padding = '6px 8px';
    const importList = document.createElement('div'); importList.style.marginTop = '8px';
  // Hint for mobile upload flow
  const refreshHint = document.createElement('div');
  refreshHint.style.fontSize = '12px';
  refreshHint.style.color = '#666';
  refreshHint.style.marginLeft = '8px';
  refreshHint.textContent = 'Once images complete upload on your phone click Refresh';
  // Small connectivity status for mobile uploads
  const testRow = document.createElement('div'); testRow.style.display = 'flex'; testRow.style.alignItems = 'center'; testRow.style.gap = '8px'; testRow.style.marginTop = '8px';
  let testBtn = null; // removed interactive Test API button per cleanup
  const testStatus = document.createElement('div'); testStatus.style.fontSize = '12px'; testStatus.style.color = '#666'; testStatus.textContent = 'API status: unknown';
  testRow.appendChild(testStatus);
  // Track which S3 keys we already imported this session to avoid duplicates on multiple refreshes
  const importedKeys = new Set();

    refreshBtn.addEventListener('click', async () => {
      refreshBtn.disabled = true; refreshBtn.textContent = 'Refreshing...';
      try {
        const api = await getAwsApiBase();
        const prefix = `mobile/${sessionId}/`;
        const resp = await fetch(`${api}/list-objects?prefix=${encodeURIComponent(prefix)}`);
        const json = resp.ok ? await resp.json() : { items: [] };
        const items = (json.items || []).filter(x => x && x.key && !x.key.endsWith('/'));
        importList.innerHTML = '';
        if (!items.length) {
          importList.textContent = 'No files yet. Upload from your phone then click Refresh.';
        } else {
          // Auto-import all items (new ones only) just like local uploads
          let imgCount = 0, vidCount = 0, skipped = 0;
          const importedKeysThisRun = [];
          for (const it of items) {
            try {
              const key = it.key;
              if (importedKeys.has(key)) { skipped++; continue; }
              const nameText = key.substring(prefix.length);
              const lower = nameText.toLowerCase();
              const isVideo = /\.(mp4|mov|webm|m4v)$/i.test(lower);
              const isImage = /\.(jpg|jpeg|png|webp|gif)$/i.test(lower);
              const sign = await fetch(`${api}/sign-download?key=${encodeURIComponent(key)}`);
              if (!sign.ok) { console.debug('sign failed', key); continue; }
              const { url } = await sign.json();
              const r = await fetch(url);
              if (!r.ok) { console.debug('download failed', key); continue; }
              const blob = await r.blob();
              const dataUrl = await new Promise((res) => { const fr = new FileReader(); fr.onload = () => res(fr.result); fr.readAsDataURL(blob); });
              if (isVideo) { currentVideos.push(dataUrl); vidCount++; }
              else if (isImage) { currentImages.push(dataUrl); imgCount++; }
              else { // fallback: try to sniff by blob type
                if ((blob.type||'').startsWith('video/')) { currentVideos.push(dataUrl); vidCount++; }
                else { currentImages.push(dataUrl); imgCount++; }
              }
              importedKeys.add(key);
              importedKeysThisRun.push(key);
              // Show list row with status
              const row = document.createElement('div'); row.style.display = 'flex'; row.style.gap = '8px'; row.style.alignItems = 'center'; row.style.marginBottom = '6px';
              const name = document.createElement('div'); name.textContent = nameText; name.style.flex = '1'; name.style.fontSize = '13px';
              const badge = document.createElement('span'); badge.className = 'pill'; badge.textContent = 'Imported';
              row.appendChild(name); row.appendChild(badge); importList.appendChild(row);
            } catch (e) { console.debug('auto-import error', e); }
          }
          // Re-render galleries once after batch imports
          try { renderImageGallery(); } catch (e) {}
          try { renderVideoGallery(); } catch (e) {}
          const summary = document.createElement('div'); summary.style.marginTop = '6px'; summary.style.fontSize = '12px'; summary.textContent = `Imported ${imgCount} image(s) and ${vidCount} video(s)${skipped?`, skipped ${skipped} already imported`:''}.`;
          importList.appendChild(summary);

          // Automatic cleanup: delete from S3 after import
          if (importedKeysThisRun.length) {
            try {
              const api = await getAwsApiBase();
              await fetch(`${api}/delete-objects`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ keys: importedKeysThisRun }) });
              const note = document.createElement('div'); note.style.fontSize='12px'; note.style.color='#333'; note.textContent = `Deleted ${importedKeysThisRun.length} file(s) from Cloud.`; importList.appendChild(note);
            } catch (e) { console.debug('delete after import failed', e); }
          }
        }
      } catch (e) { console.debug('refresh list error', e); importList.textContent = 'Error listing files.'; }
      refreshBtn.disabled = false; refreshBtn.textContent = 'Refresh';
    });
    // Connectivity test implementation
    const runConnectivityTest = async () => {
      const diag = { ts: Date.now(), sessionId, mobilePageUrl, checks: [] };
      try {
        try { if (testBtn) testBtn.disabled = true; } catch(_){}
        testStatus.textContent = 'Checking...';
        const api = await getAwsApiBase();
        if (!api) { testStatus.textContent = 'API base not configured'; return; }

        // 1) Try fetching the mobile page URL (helpful for CORS/adblock failures)
        try {
          const c = new AbortController(); const t = setTimeout(() => c.abort(), 7000);
          const r = await fetch(mobilePageUrl, { signal: c.signal, credentials: 'omit' });
          clearTimeout(t);
          diag.checks.push({ name: 'mobile_page_fetch', ok: r.ok, status: r.status, statusText: r.statusText });
        } catch (e) {
          diag.checks.push({ name: 'mobile_page_fetch', ok: false, error: e && e.message ? e.message : String(e) });
        }

        // 2) Try a small sign-upload probe (OPTIONS/HEAD may indicate CORS blocks). We don't actually upload.
        try {
          const probeKey = `mobile/${sessionId}/probe.txt`;
          const s = new AbortController(); const to = setTimeout(() => s.abort(), 7000);
          const probeResp = await fetch(`${api.replace(/\/$/, '')}/sign-upload`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ key: probeKey, contentType: 'text/plain' }), signal: s.signal });
          clearTimeout(to);
          diag.checks.push({ name: 'sign_upload_probe', ok: probeResp.ok, status: probeResp.status, statusText: probeResp.statusText });
        } catch (e) {
          diag.checks.push({ name: 'sign_upload_probe', ok: false, error: e && e.message ? e.message : String(e) });
        }

        // 3) Call list-objects for the session prefix (what Refresh uses)
        try {
          const prefix = `mobile/${sessionId}/`;
          const c2 = new AbortController(); const t2 = setTimeout(() => c2.abort(), 8000);
          const resp = await fetch(`${api.replace(/\/$/, '')}/list-objects?prefix=${encodeURIComponent(prefix)}`, { signal: c2.signal });
          clearTimeout(t2);
          if (!resp.ok) diag.checks.push({ name: 'list_objects', ok: false, status: resp.status, statusText: resp.statusText });
          else {
            const j = await resp.json();
            diag.checks.push({ name: 'list_objects', ok: true, items: (j.items && Array.isArray(j.items)) ? j.items.length : 0 });
          }
        } catch (e) { diag.checks.push({ name: 'list_objects', ok: false, error: e && e.message ? e.message : String(e) }); }

        // Persist diagnostics so you can copy them even if popup reloads
        try {
          const key = 'ffm_mobile_diag_' + sessionId;
          await window.ffmSafeSetStorage({ [key]: diag });
          try { window.__ffm_cached_diag_text = JSON.stringify(diag, null, 2); window.__ffm_cached_diag_ts = Date.now(); } catch (e) {}
        } catch (e) {}

        // Display concise status
        const failed = diag.checks.filter(c => !c.ok);
        if (failed.length) {
          testStatus.textContent = `Issues: ${failed.map(f => f.name).join(', ')}`;
        } else {
          const itemsChk = diag.checks.find(c => c.name === 'list_objects');
          testStatus.textContent = `OK — ${itemsChk && itemsChk.items ? itemsChk.items : 0} item(s) visible`;
        }
      } catch (e) {
        testStatus.textContent = `Diag error: ${e && e.message ? e.message : String(e)}`;
  } finally { try { if (testBtn) testBtn.disabled = false; } catch(_){} }
    };

    // Note: Test API button and Copy diag link removed (cleanup)
    // If an interactive trigger is needed in future, we can re-add a guarded control.
  const actionRow = document.createElement('div'); actionRow.style.display='flex'; actionRow.style.alignItems='center'; actionRow.style.gap='8px'; actionRow.appendChild(refreshBtn); actionRow.appendChild(refreshHint);
  // insert the testRow into the action area so it's visible
  actionRow.appendChild(testRow);
    wrap.appendChild(p); wrap.appendChild(link); wrap.appendChild(qrDiv); wrap.appendChild(actionRow); wrap.appendChild(importList);
  mobileUploadInline.appendChild(wrap);
  // Render QR after insertion so the library has a mounted node
  try { if (window.QRCode) new QRCode(qrDiv, { text: mobilePageUrl, width: 160, height: 160 }); } catch (e) { console.debug('QRCode render failed', e); }
  // Auto-run connectivity test once UI is visible
  try { setTimeout(() => { try { runConnectivityTest && runConnectivityTest(); } catch (e) {} }, 200); } catch (e) {}
  } catch (e) { console.debug('renderMobileUploadUI error', e); }
}

if (mobileUploadBtn) mobileUploadBtn.addEventListener('click', async () => {
  try {
    mobileUploadBtn.disabled = true; mobileUploadBtn.textContent = 'Preparing...';
    // Generate a random session id for this mobile upload
    const sessionId = `s${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}`;
    const api = await getAwsApiBase();
    const mobileUrl = `${api.replace(/\/$/, '')}/mobile?session=${encodeURIComponent(sessionId)}`;
    renderMobileUploadUI(sessionId, mobileUrl);
  } catch (e) { console.debug('mobile upload handler error', e); alert('Mobile upload failed'); }
  finally { mobileUploadBtn.disabled = false; mobileUploadBtn.textContent = 'Mobile Upload (QR)'; }
});

