// Resync helpers
async function resyncUploadAll() {
  try {
    const provider = await getCloudProvider();
    if (provider === 'drive') {
      const token = await getDriveAuthToken(true);
      if (!token) { alert('Drive not connected. Connect in the Menu first.'); return; }
    } else {
      const api = await getAwsApiBase();
      if (!api) { alert('Set AWS API base URL in Menu, then try again.'); return; }
    }
  const local = await new Promise((r)=> storageGet({ listings: [] }, (res)=> r(res.listings || [])));
  // Also push the current templates to cloud so other machines can pull them
  try { await uploadTemplatesToCloud(); } catch (e) { console.debug('uploadTemplatesToCloud non-fatal', e); }
    let okCount = 0, failCount = 0, mediaRepaired = 0;
    for (const listing of local) {
      try {
        // Track before state to detect changes
        const isAws = ((await getCloudProvider())==='aws');
        const beforeImgArr = isAws ? (Array.isArray(listing.s3ImageKeys)? listing.s3ImageKeys.slice() : []) : (listing.driveFileIds||[]);
        const beforeVidArr = isAws ? (Array.isArray(listing.s3VideoKeys)? listing.s3VideoKeys.slice() : []) : (listing.driveVideoIds||[]);
        const beforeImg = JSON.stringify(beforeImgArr);
        const beforeVid = JSON.stringify(beforeVidArr);
        // Always verify existing IDs on resync; if deleted in Drive, re-upload or prune
        await saveListingImages(listing, { verifyExisting: true });
        await saveListingVideos(listing, { verifyExisting: true });
        const afterImgArr = isAws ? (listing.s3ImageKeys||[]) : (listing.driveFileIds||[]);
        const afterVidArr = isAws ? (listing.s3VideoKeys||[]) : (listing.driveVideoIds||[]);
        const afterImg = JSON.stringify(afterImgArr);
        const afterVid = JSON.stringify(afterVidArr);
        if (beforeImg !== afterImg || beforeVid !== afterVid) mediaRepaired++;
        const ok = await saveListingMetadata(listing);
        // After saving metadata to the canonical metadata namespace, also upload full listing JSON
        if (ok && isAws) {
          try {
            const infoOk = await window.ffmAwsUploadGuarded(listing);
            if (infoOk) {
              try { if (window.showToast) window.showToast('Listing metadata (info.json) uploaded', 'success'); } catch(_){}
            } else {
              console.warn('[AutoList Pro popup] awsUploadListingMetadata returned false for', listing.inventoryName || listing.id || listing.listingId);
              try { if (window.showToast) window.showToast('Listing metadata (info.json) upload failed', 'error'); } catch(_){}
            }
          } catch (e) { console.debug('awsUploadListingMetadata error', e); }
        }
        // If AWS and metadata saved, prune any now-unreferenced S3 objects if autoPruneCloudFiles is enabled
        if (ok && isAws && (window.CONFIG?.autoPruneCloudFiles ?? true)) {
          try {
            const extras = beforeImgArr.filter(k=>!afterImgArr.includes(k)).concat(beforeVidArr.filter(k=>!afterVidArr.includes(k)));
            if (extras.length) await awsDeleteObjects(extras, { minAgeDays: 1 });
          } catch (e) { console.debug('resync prune extras failed', e); }
        }
        ok ? okCount++ : failCount++;
      } catch (e) { failCount++; }
    }
  statusBar && (statusBar.textContent = `Resync Upload complete: ${okCount} metadata updated, ${mediaRepaired} media repaired, ${failCount} failed.`);
  alert(`Resync Upload complete: ${okCount} metadata updated, ${mediaRepaired} media repaired, ${failCount} failed.`);
  try { savedListingsView = 'saved'; toggleSection(savedListingsSection); displaySavedListingsOnce(); } catch (e) {}
  // After a resync upload, update user-level settings/templates/manifest in S3
  try {
    const uid = window.ffmActiveUserId || await import('../popup_helpers.js').then(m => m.ffmGetActiveUserId()).catch(()=>null);
    if (uid) {
      try { await uploadUserSettingsToS3(uid).catch(e => console.debug('uploadUserSettingsToS3 non-fatal', e)); } catch(e){}
      try { await uploadUserTemplatesToS3(uid).catch(e => console.debug('uploadUserTemplatesToS3 non-fatal', e)); } catch(e){}
      try {
        const manifestListings = (Array.isArray(local) ? local.map(l => (l && (l.id || l.listingId || l.inventoryId)) ).filter(Boolean) : []);
        await uploadUserBackupManifestToS3(uid, manifestListings).catch(e => console.debug('uploadUserBackupManifestToS3 non-fatal', e));
      } catch (e) { console.debug('upload backup manifest error', e); }
    }
  } catch (e) { console.debug('resync post-upload hook error', e); }
  } catch (e) { console.debug('resyncUploadAll error', e); alert('Resync Upload failed.'); }
}

async function importOrMergeFromDriveByName(inventoryName, attachMedia = true) {
  try {
    const existing = await findExistingListingInDrive(inventoryName);
    if (!existing) return false;
    const local = await new Promise((resolve)=> storageGet({ listings: [] }, (r)=> resolve(r.listings || [])));
    const existingIx = local.findIndex(x => x && x.inventoryName === inventoryName);
    if (existingIx >= 0) {
      let meta = await downloadJsonFromDrive(existing.id);
      if (!meta) return false;
      const hasImgIds = Array.isArray(meta.driveFileIds) && meta.driveFileIds.length > 0;
      const hasVidIds = Array.isArray(meta.driveVideoIds) && meta.driveVideoIds.length > 0;
      if (!hasImgIds || !hasVidIds) {
        const found = await findDriveMediaIdsForListing(inventoryName);
        if (!hasImgIds && found.imageIds && found.imageIds.length) meta.driveFileIds = found.imageIds.slice();
        if (!hasVidIds && found.videoIds && found.videoIds.length) meta.driveVideoIds = found.videoIds.slice();
      }
      const l = local[existingIx];
      l.driveMetaId = existing.id;
      if ((!l.driveFileIds || !l.driveFileIds.length) && meta.driveFileIds && meta.driveFileIds.length) l.driveFileIds = meta.driveFileIds.slice();
      if ((!l.driveVideoIds || !l.driveVideoIds.length) && meta.driveVideoIds && meta.driveVideoIds.length) l.driveVideoIds = meta.driveVideoIds.slice();
      try {
        const localDesc = (l.description || '').toString().trim();
        const remoteDesc = (meta.description || '').toString().trim();
        if (!localDesc && remoteDesc) l.description = meta.description;
      } catch (e) {}
      if (attachMedia) {
        if (meta.driveFileIds && meta.driveFileIds.length) {
          const imgs = await downloadImagesFromDrive(meta.driveFileIds);
          if (imgs && imgs.length) {
            const seen = new Set(Array.isArray(l.images) ? l.images : []);
            l.images = (Array.isArray(l.images) ? l.images : []).concat(imgs.filter(x => !seen.has(x)));
          }
        }
        if (meta.driveVideoIds && meta.driveVideoIds.length) {
          const vids = await downloadImagesFromDrive(meta.driveVideoIds);
          if (vids && vids.length) {
            const seenV = new Set(Array.isArray(l.videos) ? l.videos : []);
            l.videos = (Array.isArray(l.videos) ? l.videos : []).concat(vids.filter(x => !seenV.has(x)));
          }
        }
      }
      await new Promise((res)=> storageSet({ listings: prepareListingsForStorage(local) }, res));
      return true;
    } else {
      const res = await restoreListingFromDrive(existing.id, { rehydrateMedia: attachMedia });
      return !!(res && res.success);
    }
  } catch (e) { console.debug('importOrMergeFromDriveByName error', e); return false; }
}

async function resyncDownloadAll() {
  try {
    const provider = await getCloudProvider();
    if (provider === 'drive') {
      const token = await getDriveAuthToken(true);
      if (!token) { alert('Drive not connected. Connect in the Menu first.'); return; }
    } else {
      const api = await getAwsApiBase();
      if (!api) { alert('Set AWS API base URL in Menu, then try again.'); return; }
    }
  const local = await new Promise((r)=> storageGet({ listings: [] }, (res)=> r(res.listings || [])));
    let okCount = 0, failCount = 0;
    const failedNames = [];
    const cp = await getCloudProvider();
    if (cp === 'aws') {
      // Union of local names and remote names so missing listings are imported too
  let remoteNames = [];
      try { remoteNames = await awsListAllInventoryNames(); } catch (_) { remoteNames = []; }
      const localNames = local.map(l => l && l.inventoryName).filter(Boolean);
  // Remove reserved names like __templates from sync target list
  const reserved = new Set([TEMPLATE_CLOUD_KEY]);
  const targetNames = Array.from(new Set([...localNames, ...remoteNames])).filter(n => n && !reserved.has(n));

      // First, update templates from cloud so defaults are fresh before merging listings
      try { await downloadTemplatesFromCloud({ merge: 'replace' }); } catch (e) { /* non-fatal */ }

      // Prompt user to select which target names to download (defaults = all)
      let namesToProcess = targetNames;
      try {
        // Prefetch human-readable titles for each candidate so the modal
        // can show friendly labels instead of raw ids. Fall back to the id
        // if fetching metadata fails.
        const nameEntries = [];
        for (const n of targetNames) {
          let label = n;
          try {
            if (typeof isValidFfmId === 'function' && isValidFfmId(n)) {
              const r = await awsGetListingInfo(n);
              if (r && (r.title || r.inventoryName)) label = r.title || r.inventoryName;
            } else {
              const r = await awsGetMetadata(n);
              if (r && (r.title || r.inventoryName)) label = r.title || r.inventoryName;
            }
          } catch (e) {
            // keep id as label on failure
          }
          nameEntries.push({ id: n, label });
        }

        const sel = await showResyncSelectionModal(nameEntries, { title: 'Select listings to download' });
        if (sel === null) {
          // User cancelled the selection modal — abort resync
          statusBar && (statusBar.textContent = 'Resync Download cancelled by user.');
          try { alert('Resync Download cancelled.'); } catch (e) {}
          try { savedListingsView = 'saved'; toggleSection(savedListingsSection); displaySavedListingsOnce(); } catch (e) {}
          return;
        }
        // If user selected none, treat as cancelled
        if (!Array.isArray(sel) || sel.length === 0) {
          statusBar && (statusBar.textContent = 'Resync Download: no items selected.');
          try { alert('No listings selected for Resync.'); } catch (e) {}
          return;
        }
        namesToProcess = sel;
      } catch (e) { /* non-fatal, fall back to all names */ }

      for (const name of namesToProcess) {
        let ok = false;
        try {
          // Prefer ID-first info.json when a local listing with this inventoryName exists and has an id
          const arr = await new Promise((resolve)=> storageGet({ listings: [] }, (res)=> resolve(res.listings || [])));
          const ix = arr.findIndex(x => x && x.inventoryName === name);
          let remote = null;
          if (ix >= 0) {
            const l = arr[ix];
            const lid = l && (l.id || l.listingId || l.inventoryId);
            if (lid) {
              try { remote = await awsGetListingInfo(lid); } catch (e) { remote = null; }
            }
          }
          if (!remote) {
            // If the target name itself looks like a modern ffm id, try the
            // ID-first info.json path (awsGetListingInfo) before falling back
            // to the legacy metadata namespace which expects inventoryName.
            try {
              if (typeof isValidFfmId === 'function' && isValidFfmId(name)) {
                try { console.debug('[AutoList Pro] resync: trying ID-first info.json for', name); } catch (e) {}
                try { remote = await awsGetListingInfo(name); } catch (e) { remote = null; }
                try { if (remote) console.debug('[AutoList Pro] resync: ID-first info.json FOUND for', name); } catch (e) {}
                try { if (!remote) console.debug('[AutoList Pro] resync: ID-first info.json NOT FOUND for', name); } catch (e) {}
              }
            } catch (e) { /* ignore */ }

            if (!remote) {
              try { console.debug('[AutoList Pro] resync: trying legacy metadata namespace for', name); } catch (e) {}
              try { remote = await awsGetMetadata(name); } catch (e) { remote = null; }
              try { if (remote) console.debug('[AutoList Pro] resync: legacy metadata FOUND for', name); } catch (e) {}
              try { if (!remote) console.debug('[AutoList Pro] resync: legacy metadata NOT FOUND for', name); } catch (e) {}
            }
          }
          if (remote) {
            const arr = await new Promise((resolve)=> storageGet({ listings: [] }, (res)=> resolve(res.listings || [])));
            const ix = arr.findIndex(x => x && x.inventoryName === name);
            if (ix >= 0) {
              const l = arr[ix];
              if ((!l.s3ImageKeys || !l.s3ImageKeys.length) && remote.s3ImageKeys && remote.s3ImageKeys.length) l.s3ImageKeys = remote.s3ImageKeys.slice();
              if ((!l.s3VideoKeys || !l.s3VideoKeys.length) && remote.s3VideoKeys && remote.s3VideoKeys.length) l.s3VideoKeys = remote.s3VideoKeys.slice();
              // Full resync: download ALL media at full quality
              try {
                // Try server-side export (metadata + media) when we have an ID-first listing id
                let exported = null;
                const lidCandidate = (l && (l.id || l.listingId || l.inventoryId)) || (remote && remote.listingId) || null;
                try { console.debug('[AutoList Pro] resync: attempting server export for', name, { lidCandidate }); } catch (e) {}
                if (lidCandidate) {
                  try { exported = await awsExportListing(lidCandidate); } catch (e) { exported = null; try { console.debug('[AutoList Pro] awsExportListing failed for', lidCandidate, e && (e.message || e)); } catch(_){} }
                }
                if (exported && (Array.isArray(exported.images) || Array.isArray(exported.videos))) {
                  if (Array.isArray(exported.images) && exported.images.length) l.images = (l.images || []).concat(exported.images);
                  if (Array.isArray(exported.videos) && exported.videos.length) l.videos = (l.videos || []).concat(exported.videos);
                } else {
                  try { console.debug('[AutoList Pro] resync: server export returned no media, falling back to per-key download for', name, { s3ImageKeys: (l.s3ImageKeys || []).length, s3VideoKeys: (l.s3VideoKeys || []).length }); } catch (e) {}
                  const imgs = [];
                  if (Array.isArray(l.s3ImageKeys)) {
                    for (let i = 0; i < l.s3ImageKeys.length; i++) {
                      try { console.debug('[AutoList Pro] resync: downloading image key', l.s3ImageKeys[i]); } catch(_){}
                      const dataUrl = await downloadFromAwsS3(l.s3ImageKeys[i]);
                      if (dataUrl) imgs.push(dataUrl);
                    }
                  }
                  const vids = [];
                  if (Array.isArray(l.s3VideoKeys)) {
                    for (let i = 0; i < l.s3VideoKeys.length; i++) {
                      try { console.debug('[AutoList Pro] resync: downloading video key', l.s3VideoKeys[i]); } catch(_){}
                      const v = await downloadFromAwsS3(l.s3VideoKeys[i]);
                      if (v) vids.push(v);
                    }
                  }
                  if (imgs.length) l.images = imgs;
                  if (vids.length) l.videos = vids;
                }
                // Persist downloaded media into MediaDB so Saved Listings show thumbnails
                try {
                  if ((Array.isArray(l.images) && l.images.length) || (Array.isArray(l.videos) && l.videos.length)) {
                    try { console.debug('[AutoList Pro] resync: saving downloaded media into MediaDB for', name, { images: (l.images || []).length, videos: (l.videos || []).length }); } catch(e){}
                    const mediaDbReady = await ensureMediaDBReady(5000);
                    if (mediaDbReady) {
                      try {
                        // Ensure listing has a stable id used by MediaDB
                        if (!l.listingId && l.id) l.listingId = l.id;
                        if (!l.listingId && l.inventoryName) l.listingId = l.inventoryName;
                        await ffmSaveListingMediaToDB(l, l.images || [], l.videos || []);
                        // Persist updated listings array so localImageKeys/localVideoKeys are saved
                        try { await ffmStoreRestoredListings(prepareListingsForStorage(arr)); } catch (e) { console.warn('[AutoList Pro] resync: failed to persist listings after saving media', e); }
                      } catch (e) { console.warn('[AutoList Pro] resync: ffmSaveListingMediaToDB failed', name, e); }
                    } else {
                      console.warn('[AutoList Pro] resync: MediaDB not ready, scheduling retry to persist media for', name);
                      // Schedule a best-effort retry to persist into MediaDB once available
                      setTimeout(async () => {
                        try {
                          if (await ensureMediaDBReady(5000)) {
                            try { await ffmSaveListingMediaToDB(l, l.images || [], l.videos || []); } catch (e) { console.warn('[AutoList Pro] resync retry: ffmSaveListingMediaToDB failed', name, e); }
                            try { await ffmStoreRestoredListings(prepareListingsForStorage(arr)); } catch (e) { console.warn('[AutoList Pro] resync retry: failed to persist listings', e); }
                          } else {
                            console.warn('[AutoList Pro] resync retry: MediaDB still not ready for', name);
                          }
                        } catch (e) { console.debug('[AutoList Pro] resync retry error', e); }
                      }, 3000);
                    }
                  }
                } catch (e) { console.debug('[AutoList Pro] resync: MediaDB persist attempt failed', e); }
              } catch (e) { console.debug('Full resync media download error for', name, e); }
              await ffmStoreRestoredListings(prepareListingsForStorage(arr));
              ok = true;
            } else {
              // Create a new local listing from remote metadata (images/videos left empty)
              const mapCat = (v) => { try { return /mattress/i.test((v||'').toString()) ? 'Furniture' : (v || ''); } catch (e) { return (v || ''); } };

              const listing = {
                inventoryName: remote.inventoryName || name,
                title: remote.title || '',
                price: remote.price || '',
                retailPrice: remote.retailPrice || '',
                category: mapCat(remote.category || 'Furniture'),
                condition: remote.condition || 'Used - Like New',
                bedSize: remote.bedSize || '',
                core: remote.core || '',
                comfortLevel: remote.comfortLevel || '',
                hideFromFriends: !!remote.hideFromFriends,
                description: remote.description || '',
                timestamp: remote.timestamp || Date.now(),
                s3ImageKeys: remote.s3ImageKeys || [],
                s3VideoKeys: remote.s3VideoKeys || [],
                images: [],
                videos: [],
                awsLinked: true
              };
              // Download all media at full quality for the new listing
              try {
                // Prefer backend export when we have an ID-first indicator
                let exportedNew = null;
                const newId = (remote && (remote.listingId || remote.id)) || (typeof isValidFfmId === 'function' && isValidFfmId(name) ? name : null);
                // Normalize the newly-created listing to include an id/listingId
                if (newId) {
                  try { listing.listingId = newId; listing.id = newId; } catch (e) {}
                }
                try { console.debug('[AutoList Pro] resync (new): attempting server export for', name, { newId }); } catch(e){}
                if (newId) {
                  try { exportedNew = await awsExportListing(newId); } catch (e) { exportedNew = null; try { console.debug('[AutoList Pro] awsExportListing (new) failed for', newId, e && (e.message || e)); } catch(_){} }
                }
                if (exportedNew && (Array.isArray(exportedNew.images) || Array.isArray(exportedNew.videos))) {
                  if (Array.isArray(exportedNew.images) && exportedNew.images.length) listing.images = exportedNew.images.slice();
                  if (Array.isArray(exportedNew.videos) && exportedNew.videos.length) listing.videos = exportedNew.videos.slice();
                } else {
                  try { console.debug('[AutoList Pro] resync (new): server export missing, falling back to per-key download', name, { s3ImageKeys: listing.s3ImageKeys.length, s3VideoKeys: listing.s3VideoKeys.length }); } catch(e){}
                  const imgs = [];
                  for (let i = 0; i < listing.s3ImageKeys.length; i++) {
                    const d = await downloadFromAwsS3(listing.s3ImageKeys[i]); if (d) imgs.push(d);
                  }
                  const vids = [];
                  for (let i = 0; i < listing.s3VideoKeys.length; i++) {
                    const v = await downloadFromAwsS3(listing.s3VideoKeys[i]); if (v) vids.push(v);
                  }
                  if (imgs.length) listing.images = imgs;
                  if (vids.length) listing.videos = vids;
                }
                // Persist downloaded media into MediaDB for newly-created listing
                try {
                  if ((Array.isArray(listing.images) && listing.images.length) || (Array.isArray(listing.videos) && listing.videos.length)) {
                    try { console.debug('[AutoList Pro] resync (new): saving downloaded media into MediaDB for', name, { images: (listing.images || []).length, videos: (listing.videos || []).length }); } catch(e){}
                    const mediaDbReadyNew = await ensureMediaDBReady(5000);
                    if (mediaDbReadyNew) {
                      try {
                        await ffmSaveListingMediaToDB(listing, listing.images || [], listing.videos || []);
                        // Persist updated listing (with local keys) into storage
                        try {
                                await new Promise((resolve)=> storageGet({ listings: [] }, (res)=>{
                            const arr2 = res.listings || [];
                            // replace the just-inserted listing if present, else append
                            const ix2 = arr2.findIndex(x => x && x.inventoryName === listing.inventoryName && (x.listingId === listing.listingId || x.id === listing.id));
                            if (ix2 >= 0) arr2[ix2] = listing; else arr2.push(listing);
                            ffmStoreRestoredListings(prepareListingsForStorage(arr2)).then(resolve).catch(()=>resolve);
                          }));
                        } catch (e) { console.warn('[AutoList Pro] resync (new): failed to persist listings after saving media', e); }
                      } catch (e) { console.warn('[AutoList Pro] resync (new): ffmSaveListingMediaToDB failed', name, e); }
                    } else {
                      console.warn('[AutoList Pro] resync (new): MediaDB not ready, scheduling retry to persist media for', name);
                      setTimeout(async () => {
                        try {
                          if (await ensureMediaDBReady(5000)) {
                            try { await ffmSaveListingMediaToDB(listing, listing.images || [], listing.videos || []); } catch (e) { console.warn('[AutoList Pro] resync (new) retry: ffmSaveListingMediaToDB failed', name, e); }
                                try {
                              await new Promise((resolve)=> storageGet({ listings: [] }, (res)=>{
                                const arr2 = res.listings || [];
                                const ix2 = arr2.findIndex(x => x && x.inventoryName === listing.inventoryName && (x.listingId === listing.listingId || x.id === listing.id));
                                if (ix2 >= 0) arr2[ix2] = listing; else arr2.push(listing);
                                ffmStoreRestoredListings(prepareListingsForStorage(arr2)).then(resolve).catch(()=>resolve);
                              }));
                            } catch (e) { console.warn('[AutoList Pro] resync (new) retry: failed to persist listings', e); }
                          } else {
                            console.warn('[AutoList Pro] resync (new) retry: MediaDB still not ready for', name);
                          }
                        } catch (e) { console.debug('[AutoList Pro] resync (new) retry error', e); }
                      }, 3000);
                    }
                  }
                } catch (e) { console.debug('[AutoList Pro] resync (new): MediaDB persist attempt failed', e); }
              } catch (e) { console.debug('Full resync media download error (new)', name, e); }
              await new Promise((resolve)=> storageGet({ listings: [] }, (res)=>{
                const arr2 = res.listings || [];
                arr2.push(listing);
                ffmStoreRestoredListings(prepareListingsForStorage(arr2)).then(resolve).catch(()=>resolve);
              }));
              ok = true;
            }
          }
        } catch (e) { ok = false; }
        if (ok) okCount++; else { failCount++; failedNames.push(name || String(name)); }
      }
    } else {
      // Drive path: keep legacy behavior over locals
      for (const listing of local) {
        let ok = false;
        try { ok = await importOrMergeFromDriveByName(listing.inventoryName, true); } catch (_) { ok = false; }
        if (ok) okCount++; else { failCount++; failedNames.push(listing && listing.inventoryName ? listing.inventoryName : String(listing)); }
      }
    }
  statusBar && (statusBar.textContent = `Resync Download complete: ${okCount} updated, ${failCount} skipped/failed.`);
  try {
    // Console-log full list for inspection and also show a truncated alert for quick visibility
    if (failedNames.length) {
      console.debug('[AutoList Pro] resyncDownloadAll: failed/skipped names', failedNames);
      const first = failedNames.slice(0,50).map(n => `• ${n}`).join('\n');
      const more = failedNames.length > 50 ? `\n...and ${failedNames.length - 50} more` : '';
      alert(`Resync Download complete: ${okCount} updated, ${failCount} skipped/failed.\n\nFailed/skipped (first ${Math.min(50, failedNames.length)}):\n${first}${more}`);
    } else {
      alert(`Resync Download complete: ${okCount} updated, ${failCount} skipped/failed.`);
    }
  } catch (e) { try { console.debug('resyncDownloadAll: alert failed', e); } catch(_){} }
  try { savedListingsView = 'saved'; toggleSection(savedListingsSection); displaySavedListingsOnce(); } catch (e) {}
  } catch (e) { console.debug('resyncDownloadAll error', e); alert('Resync Download failed.'); }
}

// (Removed extra click listener; resync completion now handles switching views)

// Wire Resync buttons
if (resyncUploadBtn) {
  resyncUploadBtn.addEventListener('click', async () => {
    resyncUploadBtn.disabled = true;
    resyncUploadBtn.classList.add('is-loading');
    try {
      try { savedListingsView = 'saved'; } catch (e) {}
      statusBar && (statusBar.textContent = 'Resync Upload: pushing local changes to Cloud...');
      await resyncUploadAll();
    } finally {
      resyncUploadBtn.disabled = false;
      resyncUploadBtn.classList.remove('is-loading');
    }
  });
}
if (resyncDownloadBtn) {
  resyncDownloadBtn.addEventListener('click', async () => {
    resyncDownloadBtn.disabled = true;
    resyncDownloadBtn.classList.add('is-loading');
    try {
      try { savedListingsView = 'saved'; } catch (e) {}
      statusBar && (statusBar.textContent = 'Sync from Cloud (real restore): pulling authoritative backup from Cloud...');
      await ffmRestoreFromCloud({ dryRun: false });
    } finally {
      resyncDownloadBtn.disabled = false;
      resyncDownloadBtn.classList.remove('is-loading');
    }
  });
}

// Dry-run restore (logs only)
if (typeof dryRestoreBtn !== 'undefined' && dryRestoreBtn) {
  dryRestoreBtn.addEventListener('click', async () => {
    dryRestoreBtn.disabled = true;
    dryRestoreBtn.classList.add('is-loading');
    try {
      statusBar && (statusBar.textContent = 'Checking cloud sync status...');
      await ffmCheckCloudSyncStatusAfterLogin();
    } catch (e) {
      console.error('[CHECK-CLOUD] Failed', e);
      alert('Cloud check failed. See console for details.');
    } finally {
      dryRestoreBtn.disabled = false;
      dryRestoreBtn.classList.remove('is-loading');
    }
  });
}

// === Hide old cloud buttons if cloud is enabled ===
try {
  if (window.AutoListProCloudEnabled) {
    const hideIds = ["resync-upload-btn", "recheck-all-btn", "clean-unused-btn"];
    hideIds.forEach(id => {
      try { const el = document.getElementById(id); if (el) el.style.display = 'none'; } catch (e) {}
    });
  }
} catch (e) {}

// One-click Import from Cloud (AWS) for a fresh browser
