// Bulk recheck: verify Drive links and prune stale IDs for all listings
async function recheckAllCloudLinks() {
  try {
    const provider = await getCloudProvider();
    if (provider === 'drive') {
      const token = await getDriveAuthToken(true);
      if (!token) { alert('Drive not connected. Connect in the Menu first.'); return; }
    } else {
      const api = await getAwsApiBase();
      if (!api) { alert('Set AWS API base URL in Menu, then try again.'); return; }
    }
    // Load canonical listings then also merge any per-ID `ffm_*` entries so
    // recheck covers ID-first restored listings as well as canonical arrays.
    let local = await new Promise((r)=> storageGet({ listings: [], ffm_saved_listings: [], ffmSavedListings: [], __ffm_saved_listings_cache: [] }, (res)=> r(res.listings || res.ffm_saved_listings || res.ffmSavedListings || res.__ffm_saved_listings_cache || [])));
    try {
      // Ensure we have an array
      local = Array.isArray(local) ? local : [];
      const allStorage = await new Promise((resolve) => { try { chrome.storage.local.get(null, resolve); } catch (e) { resolve({}); } });
      const existingIds = new Set((local || []).map((ls) => ls && (ls.listingId || ls.id || ls.inventoryName)));
      const rawPerIdEntries = Object.entries(allStorage || {}).filter(([key, value]) => {
        if (!key || !key.startsWith('ffm_')) return false;
        if (!value || typeof value !== 'object') return false;
        const hasListingLikeFields = ('category' in value) || ('description' in value) || ('price' in value) || ('retailPrice' in value) || ('title' in value) || ('inventoryName' in value);
        if (!hasListingLikeFields) return false;
        return true;
      });
      for (const [, obj] of rawPerIdEntries) {
        try {
          const id = obj.listingId || obj.id || obj.inventoryName;
          if (!id || typeof id !== 'string') continue;
          if (!id.startsWith('ffm_')) continue;
          if (existingIds.has(id)) continue;
          const merged = Object.assign({}, obj, { id, listingId: id });
          if (typeof merged.awsLinked !== 'boolean') merged.awsLinked = !!(merged.s3ImageKeys && merged.s3ImageKeys.length);
          local.push(merged);
          existingIds.add(id);
        } catch (e) { /* per-entry non-fatal */ }
      }
    } catch (e) {
      console.warn('[AutoList Pro] recheckAllCloudLinks: failed to merge per-ID ffm_* records', e);
    }

    let total = 0, metaCleared = 0, imgRemoved = 0, vidRemoved = 0;
    for (const listing of local) {
      total++;
      const res = await providerRecheckForListing(listing.inventoryName);
      if (res) {
        if (listing.driveMetaId && !res.metaOk) metaCleared++;
        imgRemoved += (res.imgRemoved || 0);
        vidRemoved += (res.vidRemoved || 0);
      }
    }
    try { refreshSavedListingsUI(); } catch (e) {}
    const msg = `Recheck complete: ${total} listing(s) scanned, metadata cleared for ${metaCleared}, images pruned ${imgRemoved}, videos pruned ${vidRemoved}.`;
    statusBar && (statusBar.textContent = msg);
    alert(msg);
  } catch (e) { console.debug('recheckAllCloudLinks error', e); alert('Recheck failed.'); }
}

if (recheckAllBtn) {
  recheckAllBtn.addEventListener('click', async () => {
    if (recheckAllBtn.disabled) return;
    ffmToggleLoading(recheckAllBtn, true);
    try { statusBar && (statusBar.textContent = 'Rechecking all listings...'); await recheckAllCloudLinks(); }
    catch (e) { console.debug('recheck click error', e); }
    finally { ffmToggleLoading(recheckAllBtn, false); }
  });
}

