// Compact modal to let the user choose which listings to include in a bulk operation
// Accepts an array of strings and returns either an array of selected strings or null (cancel)
// `names` may be an array of strings or an array of objects `{ id, label }`.
// The modal returns an array of selected `id` strings, or `null` if cancelled.
function showResyncSelectionModal(names = [], opts = {}) {
  return new Promise((resolve) => {
    try {
      const id = 'ffm-resync-select-modal';
      const existing = document.getElementById(id);
      if (existing) existing.remove();

      const wrap = document.createElement('div');
      wrap.id = id;
      wrap.style.position = 'fixed';
      wrap.style.zIndex = '2147483647';
      wrap.style.left = '50%';
      wrap.style.top = '10%';
      wrap.style.transform = 'translateX(-50%)';
      wrap.style.maxWidth = '640px';
      wrap.style.width = '90%';
      wrap.style.maxHeight = '70vh';
      wrap.style.overflow = 'auto';
      wrap.style.background = '#fff';
      wrap.style.border = '1px solid rgba(0,0,0,0.08)';
      wrap.style.boxShadow = '0 8px 32px rgba(0,0,0,0.12)';
      wrap.style.padding = '12px';
      wrap.style.borderRadius = '8px';

      const title = document.createElement('div');
      title.style.fontWeight = '600';
      title.style.marginBottom = '8px';
      title.textContent = opts.title || `Select listings (${names.length}) to download`;

      const help = document.createElement('div');
      help.style.fontSize = '12px';
      help.style.color = '#444';
      help.style.marginBottom = '10px';
      help.textContent = 'Tick the items you want to download. Use Select All / Clear All for convenience.';

      const controls = document.createElement('div');
      controls.style.display = 'flex';
      controls.style.justifyContent = 'space-between';
      controls.style.alignItems = 'center';
      controls.style.marginBottom = '8px';

      const selAllBtn = document.createElement('button'); selAllBtn.className = 'action-btn'; selAllBtn.textContent = 'Select All';
      const clearBtn = document.createElement('button'); clearBtn.className = 'action-btn'; clearBtn.textContent = 'Clear All';
      const countSpan = document.createElement('div'); countSpan.style.fontSize = '12px'; countSpan.textContent = `${names.length} items`;

      const listWrap = document.createElement('div');
      listWrap.style.display = 'grid';
      listWrap.style.gridTemplateColumns = '1fr 1fr';
      listWrap.style.gap = '6px';
      listWrap.style.maxHeight = '52vh';
      listWrap.style.overflow = 'auto';
      listWrap.style.padding = '6px 0 10px 0';

      const checkboxMap = new Map();
      const makeRow = (entry) => {
        // entry may be a plain string or an object { id, label }
        const idVal = (typeof entry === 'string') ? entry : (entry && entry.id) ? entry.id : String(entry);
        const labelText = (typeof entry === 'string') ? entry : (entry && entry.label) ? entry.label : idVal;

        const row = document.createElement('label');
        row.style.display = 'flex';
        row.style.alignItems = 'center';
        row.style.gap = '8px';
        row.style.padding = '4px 6px';
        row.style.borderRadius = '4px';
        row.style.background = 'transparent';
        row.onmouseenter = () => row.style.background = 'rgba(0,0,0,0.02)';
        row.onmouseleave = () => row.style.background = 'transparent';

        const cb = document.createElement('input'); cb.type = 'checkbox'; cb.checked = true;
        const span = document.createElement('span'); span.style.fontSize = '13px'; span.style.wordBreak = 'break-word'; span.textContent = labelText;
        row.appendChild(cb); row.appendChild(span);
        checkboxMap.set(idVal, cb);
        return row;
      };

      for (const n of names) listWrap.appendChild(makeRow(n));

      controls.appendChild(selAllBtn); controls.appendChild(clearBtn); controls.appendChild(countSpan);

      const btnRow = document.createElement('div');
      btnRow.style.display = 'flex';
      btnRow.style.justifyContent = 'flex-end';
      btnRow.style.gap = '8px';

      const cancelBtn = document.createElement('button'); cancelBtn.className = 'action-btn'; cancelBtn.textContent = 'Cancel';
      const confirmBtn = document.createElement('button'); confirmBtn.className = 'action-btn'; confirmBtn.textContent = 'Download Selected';

      btnRow.appendChild(cancelBtn); btnRow.appendChild(confirmBtn);

      wrap.appendChild(title); wrap.appendChild(help); wrap.appendChild(controls); wrap.appendChild(listWrap); wrap.appendChild(btnRow);
      document.body.appendChild(wrap);

      selAllBtn.addEventListener('click', () => { checkboxMap.forEach(cb => cb.checked = true); });
      clearBtn.addEventListener('click', () => { checkboxMap.forEach(cb => cb.checked = false); });

      confirmBtn.addEventListener('click', () => {
        try {
          const sel = [];
          for (const [idVal, cb] of checkboxMap.entries()) if (cb.checked) sel.push(idVal);
          wrap.remove();
          resolve(sel);
        } catch (e) { wrap.remove(); resolve(null); }
      });

      cancelBtn.addEventListener('click', () => { try { wrap.remove(); } catch (e) {} resolve(null); });

      // Keyboard: Enter confirms, Escape cancels
      const onKey = (ev) => {
        if (ev.key === 'Escape') { try { wrap.remove(); } catch (e) {} resolve(null); document.removeEventListener('keydown', onKey); }
        if (ev.key === 'Enter') { try { confirmBtn.click(); } catch (e) {} document.removeEventListener('keydown', onKey); }
      };
      document.addEventListener('keydown', onKey);
    } catch (e) { console.debug('showResyncSelectionModal error', e); resolve(null); }
  });
}

// Bulk listing-action picker — same look as showResyncSelectionModal above,
// plus one-click auto-select buttons (Active Only / Not Published Yet / N+
// days old) driven by each listing's Active Sync status. Used by the Export
// and bulk Delete/Relist features. Kept separate from showResyncSelectionModal
// so that function's existing "download images" flow is untouched.
//
// entries: [{ id, label, isActive, daysAgo }]
// opts: { title, helpText, confirmLabel, showActiveFilter, showUnlistedFilter,
//         showDaysFilter, defaultChecked }
// Resolves to an array of selected ids, or null if cancelled.
function showBulkListingActionModal(entries = [], opts = {}) {
  return new Promise((resolve) => {
    try {
      const id = 'ffm-bulk-action-modal';
      const existing = document.getElementById(id);
      if (existing) existing.remove();

      const wrap = document.createElement('div');
      wrap.id = id;
      wrap.style.position = 'fixed';
      wrap.style.zIndex = '2147483647';
      wrap.style.left = '50%';
      wrap.style.top = '8%';
      wrap.style.transform = 'translateX(-50%)';
      wrap.style.maxWidth = '640px';
      wrap.style.width = '90%';
      wrap.style.maxHeight = '80vh';
      wrap.style.overflow = 'auto';
      wrap.style.background = '#fff';
      wrap.style.border = '1px solid rgba(0,0,0,0.08)';
      wrap.style.boxShadow = '0 8px 32px rgba(0,0,0,0.12)';
      wrap.style.padding = '12px';
      wrap.style.borderRadius = '8px';

      const title = document.createElement('div');
      title.style.fontWeight = '600';
      title.style.fontSize = '15px';
      title.style.marginBottom = '8px';
      title.textContent = opts.title || `Select listings (${entries.length})`;

      const help = document.createElement('div');
      help.style.fontSize = '12px';
      help.style.color = '#444';
      help.style.marginBottom = '10px';
      help.textContent = opts.helpText || 'Check the listings you want, or click a button below to pick them for you.';

      const controls = document.createElement('div');
      controls.style.display = 'flex';
      controls.style.flexWrap = 'wrap';
      controls.style.gap = '6px';
      controls.style.marginBottom = '8px';

      const selAllBtn = document.createElement('button'); selAllBtn.className = 'action-btn'; selAllBtn.textContent = 'Check All';
      const clearBtn = document.createElement('button'); clearBtn.className = 'action-btn'; clearBtn.textContent = 'Uncheck All';
      controls.appendChild(selAllBtn); controls.appendChild(clearBtn);

      let activeOnlyBtn = null, unlistedOnlyBtn = null;
      if (opts.showActiveFilter) {
        activeOnlyBtn = document.createElement('button'); activeOnlyBtn.className = 'action-btn'; activeOnlyBtn.textContent = 'Only Active Listings';
        controls.appendChild(activeOnlyBtn);
      }
      if (opts.showUnlistedFilter) {
        unlistedOnlyBtn = document.createElement('button'); unlistedOnlyBtn.className = 'action-btn'; unlistedOnlyBtn.textContent = 'Only Listings Not Published Yet';
        controls.appendChild(unlistedOnlyBtn);
      }

      let daysInput = null, daysBtn = null;
      const daysRow = document.createElement('div');
      if (opts.showDaysFilter) {
        daysRow.style.display = 'flex';
        daysRow.style.alignItems = 'center';
        daysRow.style.gap = '6px';
        daysRow.style.marginBottom = '8px';
        daysRow.style.fontSize = '13px';
        const lbl1 = document.createElement('span'); lbl1.textContent = 'Only listings';
        daysInput = document.createElement('input');
        daysInput.type = 'number'; daysInput.min = '0'; daysInput.value = '5';
        daysInput.style.width = '56px'; daysInput.style.padding = '3px 4px';
        const lbl2 = document.createElement('span'); lbl2.textContent = 'days old or older:';
        daysBtn = document.createElement('button'); daysBtn.className = 'action-btn'; daysBtn.textContent = 'Check Those';
        daysRow.appendChild(lbl1); daysRow.appendChild(daysInput); daysRow.appendChild(lbl2); daysRow.appendChild(daysBtn);
      }

      const countSpan = document.createElement('div');
      countSpan.style.fontSize = '12px';
      countSpan.style.color = '#666';
      countSpan.style.margin = '2px 0 8px 0';

      const listWrap = document.createElement('div');
      listWrap.style.display = 'grid';
      listWrap.style.gridTemplateColumns = '1fr';
      listWrap.style.gap = '4px';
      listWrap.style.maxHeight = '42vh';
      listWrap.style.overflow = 'auto';
      listWrap.style.padding = '6px';
      listWrap.style.border = '1px solid rgba(0,0,0,0.06)';
      listWrap.style.borderRadius = '6px';

      const rowsMeta = [];
      const updateCount = () => {
        let n = 0; rowsMeta.forEach(({ cb }) => { if (cb.checked) n++; });
        countSpan.textContent = `${n} of ${entries.length} checked`;
      };

      const makeRow = (entry) => {
        const row = document.createElement('label');
        row.style.display = 'flex';
        row.style.alignItems = 'center';
        row.style.gap = '8px';
        row.style.padding = '5px 6px';
        row.style.borderRadius = '4px';
        row.onmouseenter = () => row.style.background = 'rgba(0,0,0,0.03)';
        row.onmouseleave = () => row.style.background = 'transparent';

        const cb = document.createElement('input'); cb.type = 'checkbox';
        cb.checked = (opts.defaultChecked === false) ? false : true;
        cb.addEventListener('change', updateCount);

        const span = document.createElement('span');
        span.style.fontSize = '13px';
        span.style.wordBreak = 'break-word';
        span.textContent = entry.label;

        row.appendChild(cb); row.appendChild(span);
        rowsMeta.push({ entry, cb });
        return row;
      };

      for (const entry of entries) listWrap.appendChild(makeRow(entry));

      const btnRow = document.createElement('div');
      btnRow.style.display = 'flex';
      btnRow.style.justifyContent = 'flex-end';
      btnRow.style.gap = '8px';
      btnRow.style.marginTop = '10px';

      const cancelBtn = document.createElement('button'); cancelBtn.className = 'action-btn'; cancelBtn.textContent = 'Cancel';
      const confirmBtn = document.createElement('button'); confirmBtn.className = 'action-btn'; confirmBtn.textContent = opts.confirmLabel || 'Confirm';
      btnRow.appendChild(cancelBtn); btnRow.appendChild(confirmBtn);

      wrap.appendChild(title); wrap.appendChild(help); wrap.appendChild(controls);
      if (opts.showDaysFilter) wrap.appendChild(daysRow);
      wrap.appendChild(countSpan); wrap.appendChild(listWrap); wrap.appendChild(btnRow);
      document.body.appendChild(wrap);

      updateCount();

      selAllBtn.addEventListener('click', () => { rowsMeta.forEach(({ cb }) => cb.checked = true); updateCount(); });
      clearBtn.addEventListener('click', () => { rowsMeta.forEach(({ cb }) => cb.checked = false); updateCount(); });
      if (activeOnlyBtn) activeOnlyBtn.addEventListener('click', () => {
        rowsMeta.forEach(({ entry, cb }) => cb.checked = !!entry.isActive);
        updateCount();
      });
      if (unlistedOnlyBtn) unlistedOnlyBtn.addEventListener('click', () => {
        rowsMeta.forEach(({ entry, cb }) => cb.checked = !entry.isActive);
        updateCount();
      });
      if (daysBtn) daysBtn.addEventListener('click', () => {
        const n = Math.max(0, parseInt(daysInput.value, 10) || 0);
        rowsMeta.forEach(({ entry, cb }) => {
          cb.checked = !!entry.isActive && typeof entry.daysAgo === 'number' && entry.daysAgo >= n;
        });
        updateCount();
      });

      confirmBtn.addEventListener('click', () => {
        try {
          const sel = [];
          rowsMeta.forEach(({ entry, cb }) => { if (cb.checked) sel.push(entry.id); });
          wrap.remove();
          resolve(sel);
        } catch (e) { wrap.remove(); resolve(null); }
      });
      cancelBtn.addEventListener('click', () => { try { wrap.remove(); } catch (e) {} resolve(null); });

      const onKey = (ev) => {
        if (ev.key === 'Escape') { try { wrap.remove(); } catch (e) {} resolve(null); document.removeEventListener('keydown', onKey); }
      };
      document.addEventListener('keydown', onKey);
    } catch (e) { console.debug('showBulkListingActionModal error', e); resolve(null); }
  });
}
try { window.showBulkListingActionModal = showBulkListingActionModal; } catch (e) {}

// Small floating progress bar with a Cancel button, fixed to the bottom of
// the screen so it's visible no matter which section of the popup is
// currently open. Used by Export and Bulk Delete/Relist so long-running
// loops can be stopped partway through instead of having to finish or
