// Helper: show the two-option Create New selection panel and wire its sub-buttons
function ffmShowCreateNewSelection() {
  try {
    const sel = document.getElementById('create-new');
    if (!sel) return;
    try { toggleSection(sel); setStatus('Create New Listing Opened.'); } catch (e) {}

    // Wire Create Manually button → open full Create form
    try {
      const manual = document.getElementById('create-manual');
      if (manual && !manual._ffm_bound) {
        manual.addEventListener('click', (ev) => {
          try { ev && ev.stopPropagation && ev.stopPropagation(); } catch (e) {}
          try { if (!ffmSetActiveForm('CNL')) return; } catch (e) {}
          try { toggleSection(document.getElementById('create-listing') || 'create-listing'); } catch (e) {}
        });
        manual._ffm_bound = true;
      }
    } catch (e) { /* non-fatal */ }

    // Wire From Published button → launch CLFP flow (existing handlers also listen globally)
    try {
      const fromPub = document.getElementById('create-from-published');
      if (fromPub && !fromPub._ffm_bound) {
        fromPub.addEventListener('click', (ev) => {
          // Intentionally do NOT stop propagation — allow the centralized
          // body-level CLFP launcher (initCLFPLaunch IIFE) to observe this
          // click and run the full CLFP flow (open Selling page, set flags,
          // inject scraper). This mirrors the old behavior where the global
          // handler performed the heavy lifting.
          try { console.debug('[AutoList Pro popup] From Published clicked – launching CLFP'); } catch (e) {}
          try { if (typeof ffmSetActiveForm === 'function') ffmSetActiveForm('CLFP'); } catch (e) {}
          // Let the event bubble so the body-delegated initCLFPLaunch listener handles the rest.
          return;
        });
        fromPub._ffm_bound = true;
      }
    } catch (e) { /* non-fatal */ }

  } catch (e) { console.debug('[AutoList Pro] ffmShowCreateNewSelection failed', e); }
}

// Navigation history for Back button (populated as users navigate deeper)
window.ffmViewHistory = window.ffmViewHistory || [];
window.ffmActiveSection = window.ffmActiveSection || null;

// ---------------------------------------------------------------------------
// Global SL render debounce (Phase 3.5)
// Ensures storage.onChanged triggers only ONE render during save operations.
// ---------------------------------------------------------------------------
window.__ffm_sl_render_pending = false;
window.__ffm_sl_render_timer = null;

// Back button wiring (will be toggled visible when history > 0)
try {
  const backBtn = document.getElementById('ffmBackBtn');
    if (backBtn) {
      backBtn.addEventListener('click', () => {
        try {
          if (!window.ffmViewHistory || window.ffmViewHistory.length === 0) return;
          // Pop the last history entry (most-recent prior view)
          let prev = window.ffmViewHistory.pop();

          // If we popped the '__root__' sentinel but there are still real
          // entries in the history, treat the sentinel as the bottom marker
          // and step to the next available entry instead of jumping to root.
          if (prev === '__root__' && window.ffmViewHistory && window.ffmViewHistory.length > 0) {
            prev = window.ffmViewHistory.pop();
          }

          // If we didn't resolve to a prior view (root sentinel or falsy), prefer
          // to return to the appropriate Create-selection page based on active
          // form/context (CNL, CLFP, CFST) before falling back to the global root.
          if (!prev || prev === '__root__') {
            try {
              // Try mapping by active form namespace first
              const activeForm = window.__ffm_active_form || null;
              let candidate = null;
              if (activeForm === 'CNL') {
                candidate = document.getElementById('create-new') || document.getElementById('create-new-content');
              } else if (activeForm === 'CLFP') {
                candidate = document.getElementById('create-from-published-section') || document.getElementById('create-new') || document.getElementById('create-new-content');
              } else if (activeForm === 'CFST' || (typeof ffmInSelectMode !== 'undefined' && ffmInSelectMode)) {
                candidate = document.getElementById('create-from-sharetown') || document.getElementById('create-from-sharetown-section') || document.getElementById('create-new');
              }
              // As a fallback, prefer any visible create-new / from-published / from-sharetown wrapper if present
              if (!candidate) {
                candidate = document.getElementById('create-new') || document.getElementById('create-new-content') || document.getElementById('create-from-published-section') || document.getElementById('create-from-sharetown') || document.getElementById('create-from-sharetown-section');
              }
              if (candidate) {
                // Show the candidate selection page instead of returning to global root
                try { toggleSection(candidate, true); } catch (e) { /* fallback to root below */ }
                // update visibility/hide back button if history empty
                if (!window.ffmViewHistory || window.ffmViewHistory.length === 0) backBtn.classList.add('hidden');
                return;
              }
            } catch (e) { /* ignore mapping failures and fall back to root */ }

            // No candidate mapping found — restore toolbar/root
            try {
              const allSections = document.querySelectorAll('.hidden-section, .visible-section');
              allSections.forEach((sec) => { try { sec.classList.add('hidden-section'); sec.classList.remove('visible-section'); sec.style.display = 'none'; } catch (e) {} });
            } catch (e) {}
            // move back button back to nav container
            try { const nav = document.getElementById('ffmNavButtons'); if (nav) nav.appendChild(backBtn); } catch (e) {}
            window.ffmActiveSection = null;
            // hide the back button if history now empty
            if (!window.ffmViewHistory || window.ffmViewHistory.length === 0) backBtn.classList.add('hidden');
            return;
          }

          // resolve prev to element if it's an id
          const el = (typeof prev === 'string') ? document.getElementById(prev) : prev;
          if (el) toggleSection(el, true);
          // update visibility
          if (!window.ffmViewHistory || window.ffmViewHistory.length === 0) backBtn.classList.add('hidden');
        } catch (e) { console.debug('ffmBackBtn handler error', e); }
      });
    }
} catch (e) { /* non-fatal */ }

// legacy injector removed in favour of the newer ffmInsertDeliveryOptions path

// Observe when forms become visible and inject once.
// NOTE: 'create-listing-section' / 'create-from-published-section' /
// 'create-from-sharetown-section' don't exist in popup.html (naming drifted from an
// earlier refactor) — the real container is #create-listing (form #create-listing-form
// inside it). This kept the whole delivery-options block permanently dead.
const deliveryFormObserver = new MutationObserver(() => {
  ['create-listing']
    .forEach(id => {
      const section = document.getElementById(id);
      if (section && section.offsetParent !== null) { // visible
        // use the newer insertion path (selector targets the form inside the section or the section itself)
        ffmInsertDeliveryOptionsOnce(`#${id} form, #${id}`);
      }
    });
});

deliveryFormObserver.observe(document.body, {
  childList: true,
  subtree: true
});

// Inserts “Delivery Options” above “Hide From Friends?” inside a form container
function ffmInsertDeliveryOptions(formRoot) {
  try {
    if (!formRoot) return;

    // Prevent duplicates across rebuilds
    const existing = formRoot.querySelectorAll('.ffm-delivery');
    if (existing.length > 0) {
      existing.forEach((el, i) => { if (i > 0) el.remove(); }); // keep only first
      return;
    }

    // Find “Hide From Friends?” label
    const hideLabel = [...formRoot.querySelectorAll('label')]
      .find(el => el.textContent?.trim().toLowerCase().includes('hide from friends'));
    if (!hideLabel) return;

    const hideBlock = hideLabel.closest('div')?.parentElement || hideLabel.parentElement;
    if (!hideBlock) return;

    // Build the delivery options block
    const block = document.createElement('div');
    block.className = 'ffm-delivery';
    block.innerHTML = `
      <div class="ffm-delivery__header">Delivery Options</div>
      <div class="ffm-delivery__row">
        <div class="ffm-delivery__text">
          <div class="ffm-delivery__title">Public meetup</div>
          <div class="ffm-delivery__desc">Meet at a public location.</div>
        </div>
        <input id="ffm_opt_public_meetup" type="checkbox" class="ffm-delivery__check">
      </div>
      <div class="ffm-delivery__row">
        <div class="ffm-delivery__text">
          <div class="ffm-delivery__title">Door pickup</div>
          <div class="ffm-delivery__desc">Buyer picks up at your door.</div>
        </div>
        <input id="ffm_opt_door_pickup" type="checkbox" class="ffm-delivery__check">
      </div>
      <div class="ffm-delivery__row">
        <div class="ffm-delivery__text">
          <div class="ffm-delivery__title">Door dropoff</div>
          <div class="ffm-delivery__desc">You drop off at buyer’s door.</div>
        </div>
        <input id="ffm_opt_door_dropoff" type="checkbox" class="ffm-delivery__check">
      </div>
    `;

    hideBlock.parentNode.insertBefore(block, hideBlock);

    // Wire globals so existing save/load code picks up the newly-inserted inputs
    try {
      publicMeetupCheckbox = document.getElementById('optPublicMeet') || document.getElementById('ffm_opt_public_meetup');
      doorPickupCheckbox = document.getElementById('optDoorPickup') || document.getElementById('ffm_opt_door_pickup');
      doorDropoffCheckbox = document.getElementById('optDoorDropoff') || document.getElementById('ffm_opt_door_dropoff');
    } catch (e) { /* non-fatal */ }
    // Apply stored defaults now that inputs exist (small delay to ensure caller handlers settled)
    try {
      setTimeout(() => {
        try { applyStoredDefaultsToForm(formRoot); } catch (e) {}
      }, 60);
    } catch (e) {}
  } catch (err) {
    console.warn('[FFM] delivery options insert failed', err);
  }
}

// Retry helper: attempts to insert when root becomes available
function ffmInsertDeliveryOptionsWhenReady(rootSel, tries = 10) {
  const t = setInterval(() => {
    const root = document.querySelector(rootSel);
    if (root) {
      ffmInsertDeliveryOptionsOnce(rootSel);
      clearInterval(t);
    } else if (--tries <= 0) {
      clearInterval(t);
    }
  }, 120);
}

// Prevent re-insertion: calls ffmInsertDeliveryOptions once per root selector
function ffmInsertDeliveryOptionsOnce(selector) {
  try {
    const el = document.querySelector(selector);
    if (el && !el.dataset.ffmDeliveryInjected) {
      ffmInsertDeliveryOptions(el);
      el.dataset.ffmDeliveryInjected = 'true';
    }
  } catch (e) { /* non-fatal */ }
}

