// Last-checked display + action wiring (unified: prefer .ffm-last-checked-tip)
async function ffmUpdateLastCheckedDisplay() {
  try {
  // Prefer the visible tip span; legacy #ffmLastCheckedText has been removed
  const target = document.querySelector('.ffm-last-checked-tip');
  if (!target) return;

    return new Promise((resolve) => {
      try {
        const doSet = (display) => {
          try { target.textContent = display; } catch (e) {}
          resolve();
        };

        if (chrome && chrome.storage && chrome.storage.local && chrome.storage.local.get) {
          chrome.storage.local.get(['ffmLastActiveCheck'], (res) => {
            try {
              const lastCheck = (res && res.ffmLastActiveCheck) ? Number(res.ffmLastActiveCheck) : 0;
              if (!lastCheck) {
                doSet('Last checked: never');
                return;
              }
              const diffMs = Date.now() - lastCheck;
              const minutes = Math.floor(diffMs / 60000);
              const display = minutes < 1
                ? 'Last checked: Just Now'
                : minutes < 60
                ? `Last checked: ${minutes} min${minutes === 1 ? '' : 's'} ago`
                : `Last checked: ${(minutes / 60).toFixed(1)} hrs ago`;
              doSet(display);
            } catch (e) { doSet('Last checked: never'); }
          });
        } else {
          doSet('Last checked: never');
        }
  } catch (e) { try { target.textContent = 'Last checked: never'; } catch(_){} resolve(); }
    });
  } catch (e) { try { const el = document.querySelector('.ffm-last-checked-tip'); if (el) el.textContent = 'Last checked: never'; } catch(_){} }
}

