async function openMarketplaceAndScanActiveListings() {
  try {
    const sellingUrl = 'https://www.facebook.com/marketplace/you/selling';
    try { console.log('[AutoList Pro popup] 🌐 Opening Selling page for Active Sync...'); } catch (e) {}
    try { window.showToast && window.showToast('Opening your Facebook Selling page...', { type: 'info', duration: 2500 }); } catch (e) {}

    // Open Selling tab
    const tab = await new Promise(resolve => {
      try { chrome.tabs.create({ url: sellingUrl, active: true }, resolve); } catch (e) { resolve(null); }
    });

    if (!tab || !tab.id) {
      try { console.warn('[AutoList Pro popup] Failed to create Selling tab for Active Sync'); } catch (e) {}
      return;
    }

    // Wait for the page to load before injecting scraper
    const delayMs = 8000; // adjust if needed for slower FB loads
    try { console.log(`[AutoList Pro popup] Waiting ${delayMs / 1000}s before running scrape...`); } catch (e) {}
    setTimeout(() => {
      try {
        chrome.scripting.executeScript({
          target: { tabId: tab.id },
          func: () => {
            try { console.log('[AutoList Pro] Running Active Listings scrape in Selling tab...'); } catch (e) {}
            try {
              if (typeof window.ffmScrapeActiveListingsOnce === 'function') {
                try { window.ffmScrapeActiveListingsOnce(); } catch (e) { try { console.warn('[AutoList Pro] ffmScrapeActiveListingsOnce threw', e); } catch(_){} }
              } else {
                try { console.warn('[AutoList Pro] ffmScrapeActiveListingsOnce not found in page context.'); } catch(_){}
              }
            } catch (e) { try { console.warn('[AutoList Pro] error invoking ffmScrapeActiveListingsOnce', e); } catch(_){} }
          }
        });
      } catch (e) { try { console.warn('[AutoList Pro popup] scripting.executeScript failed', e); } catch(_){} }
    }, delayMs);
  } catch (err) {
    try { console.error('[AutoList Pro popup] Active Sync error:', err); } catch (_) {}
    try { window.showToast && window.showToast('Active Sync failed. See console.', { type: 'error' }); } catch (e) {}
  }
}
