// Apply stored Set Defaults (hide/delivery) into forms when they open.
function applyStoredDefaultsToForm(sectionEl) {
  try {
    storageGet({ 'ffm_set_defaults': {} }, (res) => {
      try {
        const d = (res && res.ffm_set_defaults) ? res.ffm_set_defaults : {};
        // Helper to find an element by possible ids, optionally scoped to sectionEl
        const find = (ids) => {
          for (const id of ids) {
            let el = null;
            try { el = (sectionEl && sectionEl.querySelector) ? sectionEl.querySelector('#' + id) : null; } catch (e) {}
            if (!el) try { el = document.getElementById(id); } catch (e) {}
            if (el) return el;
          }
          return null;
        };

        // Hide From Friends toggle
        const hideEl = find(['hide-from-friends']);
        if (hideEl) {
          // only set default if user hasn't already edited this control in this session
          if (!hideEl.dataset.ffmUserEdited) {
            try { hideEl.checked = !!d.hideFromFriends; } catch (e) {}
          }
          // mark as user-edited when changed manually so future default loads won't overwrite
          try { hideEl.addEventListener('change', () => { hideEl.dataset.ffmUserEdited = '1'; }); } catch (e) {}
        }

        // Delivery checkboxes (support legacy and injected IDs)
        const mapping = [
          { ids: ['optPublicMeet', 'ffm_opt_public_meetup'], val: !!d.publicMeetup },
          { ids: ['optDoorPickup', 'ffm_opt_door_pickup'], val: !!d.doorPickup },
          { ids: ['optDoorDropoff', 'ffm_opt_door_dropoff'], val: !!d.doorDropoff }
        ];
        mapping.forEach((m) => {
          const el = find(m.ids);
          if (!el) return;
          if (!el.dataset.ffmUserEdited) {
            try { el.checked = !!m.val; } catch (e) {}
          }
          try { el.addEventListener('change', () => { el.dataset.ffmUserEdited = '1'; }); } catch (e) {}
        });
      } catch (e) { /* non-fatal */ }
    });
  } catch (e) { /* defensive */ }
}

