// Show/hide form fields based on selected category
function applyCategoryFieldVisibility() {
  try {
    const cat = (categorySelect && categorySelect.value) || '';
    const show = (el, on) => { if (!el) return; const wrap = el.closest('.form-group'); if (wrap) wrap.style.display = on ? '' : 'none'; };
    // Base rules
    const isSofa = cat === 'Sofas, Loveseats & Sectionals';
    const isBicycle = cat === 'Bicycles';
    const isElectronics = cat === 'Electronics & computers';
    // Show note for Other
    if (otherCategoryNote) otherCategoryNote.style.display = (cat === 'Miscellaneous') ? '' : 'none';
    // Condition always visible
    show(conditionSelect, true);
    // Sofa Type: show for sofas
    show(sofaTypeSelect, isSofa);
    // Bike Type/Wheel Size/Material: only for Bicycles
    show(bikeTypeSelect, isBicycle);
    show(wheelSizeSelect, isBicycle);
    show(bikeMaterialSelect, isBicycle);
    // Smart Home Compatibility/Color: only for Electronics & computers
    show(smartHomeCompatInput, isElectronics);
    show(elecColorSelect, isElectronics);
  } catch (e) { console.debug('applyCategoryFieldVisibility error', e); }
}
