// Count uploadable (non-stub) data URLs in an array
function ffmCountUploadable(arr) {
  try {
    if (!Array.isArray(arr)) return 0;
    return arr.reduce((n, x) => n + ((typeof x === 'string' && /^data:/.test(x) && !(x && x.__ffm_data_stub)) ? 1 : 0), 0);
  } catch (e) { return 0; }
}

// Helper: robustly snap the Saved Listings view so the search row is visible at the top (with small offset)
function ffmSnapToSavedListings() {
  try {
    const scroller = document.scrollingElement || document.documentElement || document.body;
    const hasCustomSnap = (window && typeof window.ffm_saved_scroll_snap_top_px === 'number' && isFinite(window.ffm_saved_scroll_snap_top_px));
    const OFFSET = (window && window.ffm_saved_scroll_offset_px) || 32; // give more headroom so the title is clearly visible

    // If a fixed target top is provided, do one smooth scroll to it
    if (hasCustomSnap) {
      const TOP = Math.max(0, Number(window.ffm_saved_scroll_snap_top_px));
      try { scroller.scrollTo({ top: TOP, behavior: 'smooth' }); } catch (e) {}
      return;
    }

    // Prefer aligning to the Saved Listings header so the title is visible; fallback to search row or first item
    const section = savedListingsSection || document.getElementById('saved-listings');
    const header = section ? (section.querySelector('h2, .card-header h2, .section-title, .card-header')) : null;
    const searchRow = document.getElementById('saved-search');
    const cont = document.getElementById('saved-listings-container');
    const fallback = (searchRow) ? searchRow : (cont && cont.querySelector('li')) || section || document.body;

    const firstPass = () => {
      try {
        const currentY = scroller.scrollTop || window.pageYOffset || 0;
        const anchor = header || fallback;
        const rect = anchor.getBoundingClientRect();
        const desired = Math.max(0, currentY + rect.top - OFFSET);
        scroller.scrollTo({ top: desired, behavior: 'smooth' });
      } catch (e) {}
    };

    const secondPass = () => {
      try {
        const currentY = scroller.scrollTop || window.pageYOffset || 0;
        const anchor = header || fallback;
        const rect = anchor.getBoundingClientRect();
        const desired = Math.max(0, currentY + rect.top - OFFSET);
        const delta = Math.abs((scroller.scrollTop || 0) - desired);
        if (delta > 2) scroller.scrollTo({ top: desired, behavior: 'auto' });
      } catch (e) {}
    };

    // Run after layout settles slightly
    requestAnimationFrame(() => { setTimeout(firstPass, 80); setTimeout(secondPass, 260); });
  } catch (e) { /* non-fatal */ }
}

// Render the image gallery from currentImages
function renderImageGallery() {
  try {
    if (!imageGallery) return;
    imageGallery.innerHTML = '';
    // Create a single hover preview element if missing
    let hoverPreview = document.getElementById('ffm-hover-preview');
    if (!hoverPreview) {
      hoverPreview = document.createElement('div');
      hoverPreview.id = 'ffm-hover-preview';
      hoverPreview.style.position = 'fixed';
      hoverPreview.style.pointerEvents = 'none';
      hoverPreview.style.zIndex = '2147483647';
      hoverPreview.style.display = 'none';
      hoverPreview.style.background = 'rgba(0,0,0,0.86)';
      hoverPreview.style.border = '1px solid rgba(255,255,255,0.2)';
      hoverPreview.style.boxShadow = '0 6px 18px rgba(0,0,0,0.35)';
      hoverPreview.style.borderRadius = '8px';
      hoverPreview.style.padding = '6px';
      // Larger size to fill the main form area while respecting popup bounds
      hoverPreview.style.maxWidth = '90vw';
      hoverPreview.style.maxHeight = '75vh';
      const im = document.createElement('img');
      im.style.display = 'block';
      im.style.maxWidth = '88vw';
      im.style.maxHeight = '72vh';
      im.style.objectFit = 'contain';
      im.alt = 'Preview';
      hoverPreview.appendChild(im);
      document.body.appendChild(hoverPreview);
    }
    // Position the preview slightly higher than center (apply whether created now or already exists)
    hoverPreview.style.left = '50%';
    hoverPreview.style.top = '38%';
    hoverPreview.style.transform = 'translate(-50%, -60%)';
    // Delayed hover preview: 1 second before showing
    let hoverTimer = null;
    const showPreview = (dataUrl) => {
      try {
        const im = hoverPreview.querySelector('img');
        if (im && im.src !== dataUrl) im.src = dataUrl;
        hoverPreview.style.display = 'block';
      } catch (e) {}
    };
    const hidePreview = () => { try { hoverPreview.style.display = 'none'; } catch (e) {} };
    const schedulePreview = (dataUrl) => {
      try { if (hoverTimer) { clearTimeout(hoverTimer); hoverTimer = null; } } catch (e) {}
      hoverTimer = setTimeout(() => { showPreview(dataUrl); }, 1000);
    };
    const cancelPreview = () => {
      try { if (hoverTimer) { clearTimeout(hoverTimer); hoverTimer = null; } } catch (e) {}
      hidePreview();
    };
    currentImages.forEach((dataUrl, idx) => {
      const thumb = document.createElement('div');
      thumb.className = 'image-thumb';
      thumb.draggable = true;
      thumb.dataset.index = idx;
      // Attach canonical mediaKey when available (set during Saved Listing load)
      try {
        const keys = window.__ffm_current_image_keys;
        if (keys && Array.isArray(keys) && keys[idx]) thumb.dataset.mediaKey = keys[idx];
      } catch (e) {}

      const img = document.createElement('img');
      img.src = dataUrl;
      // Clicking the thumbnail opens the full image in a new tab (single, consistent API)
      img.style.cursor = 'zoom-in';
      img.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        try {
          if (window.chrome && chrome.tabs && chrome.tabs.create) {
            chrome.tabs.create({ url: dataUrl });
          } else {
            window.open(dataUrl, '_blank');
          }
        } catch (_) {}
      });
      thumb.appendChild(img);

      const removeBtn = document.createElement('button'); removeBtn.className = 'remove-btn'; removeBtn.textContent = '×';
      removeBtn.addEventListener('click', async (e) => {
        e.preventDefault();
        e.stopPropagation();

        // If not in edit mode (and not editing a listing), behave as legacy: remove from currentImages
        if (!window.__ffm_isEditMode && !window.__ffm_editingListingId) {
          currentImages.splice(idx, 1);
          renderImageGallery();
          return;
        }

        // In edit mode: prefer canonical delete when mediaKey + listingId available
        // Prefer explicit data-media-key, otherwise fall back to the nearest .image-thumb dataset
        const thumbEl = removeBtn.closest && (removeBtn.closest('[data-media-key]') || removeBtn.closest('.image-thumb')) ? (removeBtn.closest('[data-media-key]') || removeBtn.closest('.image-thumb')) : null;
        const mediaKey = thumbEl && thumbEl.dataset ? (thumbEl.dataset.mediaKey || null) : null;

        // Debug: log edit-mode state and thumbnail dataset to help diagnose why confirm may not show
        try {
          console.log('[FFM:DEBUG] remove-btn clicked', {
            __ffm_isEditMode: window.__ffm_isEditMode,
            __ffm_editingListingId: window.__ffm_editingListingId,
            mediaKey,
            thumbDataset: thumbEl && thumbEl.dataset ? Object.assign({}, thumbEl.dataset) : null,
            idx
          });
        } catch (e) {}
        const listingId = window.__ffm_editingListingId || null;

        // Use the in-app modal for confirmation and canonical deletion
        try {
          ffmShowImageDeleteModal(listingId, mediaKey, thumbEl);
        } catch (e) { console.warn('[Edit] show modal failed', e); }

        // Note: modal will handle deletion and UI removal
        return;
      });
      thumb.appendChild(removeBtn);

      // drag events
      thumb.addEventListener('dragstart', (ev) => { ev.dataTransfer.setData('text/plain', String(idx)); ev.dataTransfer.effectAllowed = 'move'; cancelPreview(); });
      thumb.addEventListener('dragover', (ev) => { ev.preventDefault(); ev.dataTransfer.dropEffect = 'move'; });
      thumb.addEventListener('drop', (ev) => {
        ev.preventDefault();
        try {
          const from = parseInt(ev.dataTransfer.getData('text/plain'), 10);
          const to = parseInt(thumb.dataset.index, 10);
          if (!Number.isFinite(from) || !Number.isFinite(to) || from === to) return;
          const item = currentImages.splice(from, 1)[0];
          currentImages.splice(to, 0, item);
          renderImageGallery();
        } catch (e) { console.debug('drop reorder error', e); }
      });

      // hover preview interactions (with 1s delay, centered)
      thumb.addEventListener('mouseenter', () => { schedulePreview(dataUrl); });
      // No mousemove handler needed since preview is centered
      thumb.addEventListener('mouseleave', () => { cancelPreview(); });

      imageGallery.appendChild(thumb);
    });
    // update image count display
    try { if (imageCountEl) imageCountEl.textContent = 'Number of Images Selected: ' + (currentImages.length || 0); } catch (e) {}
  } catch (e) { console.debug('renderImageGallery error', e); }
}

// Render the video gallery from currentVideos
async function renderVideoGallery() {
  try {
    try { console.debug('renderVideoGallery called', { currentVideosLen: currentVideos.length }); } catch(e){}
    if (!videoGallery) return;
    videoGallery.innerHTML = '';
    currentVideos.forEach((dataUrl, idx) => {
      const thumb = document.createElement('div');
      thumb.className = 'video-thumb';
      thumb.draggable = true;
      thumb.dataset.index = idx;
      // Attach canonical mediaKey when available (set during Saved Listing load)
      try {
        const vkeys = window.__ffm_current_video_keys;
        if (vkeys && Array.isArray(vkeys) && vkeys[idx]) thumb.dataset.mediaKey = vkeys[idx];
      } catch (e) {}

      // Create a preview box with a play icon overlay instead of embedding the video directly.
      const preview = document.createElement('div');
      preview.className = 'video-preview';
      preview.title = 'Click to open video';
      // If the dataUrl is an image (poster) use it as background; if it's a video data URL embed a small <video> tag
      try {
        if (typeof dataUrl === 'string') {
          if (dataUrl.indexOf('data:image/') === 0) {
            preview.style.backgroundImage = `url("${dataUrl}")`;
            preview.style.backgroundSize = 'cover';
            preview.style.backgroundPosition = 'center';
          } else if (dataUrl.indexOf('data:video/') === 0 || (/^https?:\/\//i).test(dataUrl) && (/\.(mp4|webm|mov)(\?|$)/i.test(dataUrl) || /fbcdn\.net|scontent-|\/video\//i.test(dataUrl))) {
            // embed a lightweight video element for inline preview (muted, looped, playsinline)
            const vid = document.createElement('video');
            vid.preload = 'metadata';
            vid.muted = true;
            vid.loop = true;
            vid.playsInline = true;
            vid.style.width = '100%';
            vid.style.height = '100%';
            vid.style.objectFit = 'cover';
            vid.style.display = 'block';
            preview.appendChild(vid);
            // If remote URL, fetch as blob first to avoid cross-origin playback problems
            (async () => {
              try {
                if (typeof dataUrl === 'string' && dataUrl.indexOf('data:video/') === 0) {
                  vid.src = dataUrl;
                } else if (typeof dataUrl === 'string' && dataUrl.startsWith('http')) {
                  try {
                    const controller = new AbortController();
                    const to = setTimeout(() => controller.abort(), 12000);
                    const resp = await fetch(dataUrl, { signal: controller.signal });
                    clearTimeout(to);
                    if (resp && resp.ok) {
                      const blob = await resp.blob();
                      try { vid.__ffm_blob_url && URL.revokeObjectURL(vid.__ffm_blob_url); } catch(e){}
                      vid.__ffm_blob_url = URL.createObjectURL(blob);
                      vid.src = vid.__ffm_blob_url;
                    } else {
                      // fallback to direct src if fetch failed
                      vid.src = dataUrl;
                    }
                  } catch (e) {
                    try { vid.src = dataUrl; } catch (er) {}
                  }
                } else {
                  try { vid.src = dataUrl; } catch (e) {}
                }
              } catch (e) { try { vid.src = dataUrl; } catch (_) {} }
            })();
            // don't autoplay by default; play on hover to show motion, pause on leave
            preview.addEventListener('mouseenter', () => { try { vid.play && vid.play().catch(()=>{}); } catch(e){} });
            preview.addEventListener('mouseleave', () => { try { vid.pause && vid.pause(); vid.currentTime = 0; } catch(e){} });
          }
        }
      } catch (e) {}

      // Play icon overlay
      const playIcon = document.createElement('div');
      playIcon.className = 'video-play-icon';
      playIcon.setAttribute('aria-hidden', 'true');
      playIcon.textContent = '\u25BA'; // play triangle
      preview.appendChild(playIcon);

      // Clicking opens the video in a new tab (consistent with image click behavior)
      preview.addEventListener('click', (e) => {
        e.preventDefault(); e.stopPropagation();
        try {
          if (window.chrome && chrome.tabs && chrome.tabs.create) {
            chrome.tabs.create({ url: dataUrl });
          } else {
            window.open(dataUrl, '_blank');
          }
        } catch (_) { window.open(dataUrl, '_blank'); }
      });

      thumb.appendChild(preview);

      const removeBtn = document.createElement('button'); removeBtn.className = 'remove-btn'; removeBtn.textContent = '×';
      removeBtn.addEventListener('click', (e) => {
        e.preventDefault();
        e.stopPropagation();
        currentVideos.splice(idx, 1);
        renderVideoGallery();
      });
      thumb.appendChild(removeBtn);

      // drag events for reorder
      thumb.addEventListener('dragstart', (ev) => { ev.dataTransfer.setData('text/plain', String(idx)); ev.dataTransfer.effectAllowed = 'move'; });
      thumb.addEventListener('dragover', (ev) => { ev.preventDefault(); ev.dataTransfer.dropEffect = 'move'; });
      thumb.addEventListener('drop', (ev) => {
        ev.preventDefault();
        try {
          const from = parseInt(ev.dataTransfer.getData('text/plain'), 10);
          const to = parseInt(thumb.dataset.index, 10);
          if (!Number.isFinite(from) || !Number.isFinite(to) || from === to) return;
          const item = currentVideos.splice(from, 1)[0];
          currentVideos.splice(to, 0, item);
          renderVideoGallery();
        } catch (e) { console.debug('drop reorder error', e); }
      });

      videoGallery.appendChild(thumb);
    });
  } catch (e) { console.debug('renderVideoGallery error', e); }
}

// Handle file input selection -> convert to data URLs and append
if (imageInput) {
  imageInput.addEventListener('change', (ev) => {
    const files = Array.from(ev.target.files || []);
    if (!files.length) return;
    // Enforce max images 10 total
    const MAX_IMAGES = 10;
    const remainingSlots = Math.max(0, MAX_IMAGES - (currentImages ? currentImages.length : 0));
    const useFiles = remainingSlots > 0 ? files.slice(0, remainingSlots) : [];
    if (useFiles.length < files.length) {
      try { (window.showToast || window.ffmShowToast)(`Only ${MAX_IMAGES} images allowed. Skipped ${files.length - useFiles.length}.`, { type: 'info' }); } catch(_) {}
    }
    if (!useFiles.length) { try { imageInput.value = ''; } catch (e) {} return; }
    const readers = useFiles.map((f) => new Promise((res) => {
      const r = new FileReader(); r.onload = () => res(r.result); r.onerror = () => res(null); r.readAsDataURL(f);
    }));
    Promise.all(readers).then((dataUrls) => {
      for (const d of dataUrls) if (d && currentImages.length < MAX_IMAGES) currentImages.push(d);
      renderImageGallery();
      // clear input so same file can be chosen again if needed
      try { imageInput.value = ''; } catch (e) {}
    }).catch((e) => { console.debug('imageInput read error', e); });
  });
}

// Select Images button triggers the hidden file input
if (selectImagesBtn && imageInput) {
  selectImagesBtn.addEventListener('click', (e) => { e.preventDefault(); try { imageInput.click(); } catch (err) {} });
}

// Handle video input selection
if (videoInput) {
  videoInput.addEventListener('change', (ev) => {
    const files = Array.from(ev.target.files || []);
    if (!files.length) return;
    // Keep only first file candidate; we only allow 1 video total
    if (files.length > 1) {
      try { (window.showToast || window.ffmShowToast)(`Only 1 video allowed. Skipped ${files.length - 1}.`, { type: 'info' }); } catch(_) {}
    }
    const first = files[0];
    if (!first) { try { videoInput.value = ''; } catch (e) {} return; }
    // If we already have a video selected in memory, replace it with the new one
    const readAsDataUrl = (f) => new Promise((res) => { const r = new FileReader(); r.onload = () => res(r.result); r.onerror = () => res(null); r.readAsDataURL(f); });
    // Probe duration using a Blob URL
    const validateDuration = (file) => new Promise((resolve) => {
      try {
        const url = URL.createObjectURL(file);
        const v = document.createElement('video');
        v.preload = 'metadata';
        v.onloadedmetadata = () => {
          try { URL.revokeObjectURL(url); } catch(_) {}
          const dur = (v.duration && isFinite(v.duration)) ? v.duration : 0;
          resolve(dur);
        };
        v.onerror = () => { try { URL.revokeObjectURL(url); } catch(_) {}; resolve(0); };
        v.src = url;
      } catch (_) { resolve(0); }
    });
    (async () => {
      try {
        const dur = await validateDuration(first);
        const MAX_SEC = 60;
        if (dur > MAX_SEC + 0.5) {
          try { (window.showToast || window.ffmShowToast)(`Video too long (${Math.round(dur)}s). Max 60 seconds.`, { type: 'error' }); } catch(_) {}
          try { videoInput.value = ''; } catch (e) {}
          return;
        }
        const dataUrl = await readAsDataUrl(first);
        if (!dataUrl) { try { (window.showToast || window.ffmShowToast)('Failed to read video file', { type: 'error' }); } catch(_) {} return; }
        // Keep only one video in memory
        currentVideos = [];
        currentVideos.push(dataUrl);
        renderVideoGallery();
        try { videoInput.value = ''; } catch (e) {}
      } catch (e) {
        console.debug('videoInput validation/read error', e);
        try { videoInput.value = ''; } catch (er) {}
      }
    })();
  });
}

// ---------------- Listing ID helpers ----------------

// Format: ffm_<timestamp>_<6-char base36>
function ffmGenerateListingId() {
  try {
    const ts = Date.now();
    const rand = Math.floor(Math.random() * 0xffffff);
    const randStr = rand.toString(36).padStart(4, '0');
    return `ffm_${ts}_${randStr}`;
  } catch (e) {
    try { console.debug('[AutoList Pro] ffmGenerateListingId error', e); } catch (_) {}
    return `ffm_${Date.now()}`;
  }
}

function ffmFormatListingIdDisplay(id) {
  if (!id) return 'ID: (not set)';
  return `ID: ${id}`;
}

// Ensure we have a little read-only label right under Inventory Name
let ffmListingIdDisplayEl = null;

function ffmEnsureListingIdDisplay() {
  try {
    if (ffmListingIdDisplayEl && ffmListingIdDisplayEl.isConnected) {
      return ffmListingIdDisplayEl;
    }

    const invInput =
      typeof inventoryNameInput !== 'undefined' && inventoryNameInput
        ? inventoryNameInput
        : document.getElementById('inventory-name');

    if (!invInput || !invInput.parentNode) return null;

    const container = (invInput.closest && invInput.closest('.form-group')) || invInput.parentNode;
    const label = document.createElement('div');
    label.id = 'listing-id-display';
    label.className = 'ffm-listing-id-display';
    label.style.fontSize = '11px';
    label.style.color = '#666';
    label.style.marginTop = '2px';
    label.textContent = ffmFormatListingIdDisplay(null);

    if (container.nextSibling) {
      container.parentNode.insertBefore(label, container.nextSibling);
    } else {
      container.parentNode.appendChild(label);
    }

    ffmListingIdDisplayEl = label;
    return ffmListingIdDisplayEl;
  } catch (e) {
    try { console.debug('[AutoList Pro] ffmEnsureListingIdDisplay error', e); } catch (_) {}
    return null;
  }
}

function ffmUpdateListingIdDisplay(listingOrId) {
  try {
    const el = ffmEnsureListingIdDisplay();
    if (!el) return;
    const id = (listingOrId && listingOrId.listingId) || listingOrId || null;
    el.textContent = ffmFormatListingIdDisplay(id);
  } catch (e) {
    try { console.debug('[AutoList Pro] ffmUpdateListingIdDisplay error', e); } catch (_) {}
  }
}

/* -------------------------------
   Storage wrapper (chrome.storage fallback to localStorage)
   Use storageGet(defaults, callback) and storageSet(obj, callback)
------------------------------- */
function storageGet(defaults, callback) {
  // If an in-memory cache is available for listings, prefer it to avoid a storage round-trip
  try {
    const hasListingsKey = Object.prototype.hasOwnProperty.call(defaults || {}, 'listings');
    if (hasListingsKey && window.FFM_SAVED_LISTINGS_CACHE && Array.isArray(window.FFM_SAVED_LISTINGS_CACHE)) {
      try {
        const res = {};
        for (const k in defaults) res[k] = defaults[k];
        res.listings = window.FFM_SAVED_LISTINGS_CACHE;
        setTimeout(() => callback(res), 0);
        return;
      } catch (e) {}
    }
  } catch (e) {}

  if (window.chrome && chrome.storage && chrome.storage.local && chrome.storage.local.get) {
    chrome.storage.local.get(defaults, callback);
    return;
  }

  // Fallback to localStorage
  try {
    const raw = localStorage.getItem('fast4mp_storage');
    const parsed = raw ? JSON.parse(raw) : {};
    const result = {};
    for (const k in defaults) {
      result[k] = parsed.hasOwnProperty(k) ? parsed[k] : defaults[k];
    }
    // simulate async
    setTimeout(() => callback(result), 0);
  } catch (err) {
    console.error('storageGet fallback error', err);
    setTimeout(() => callback(defaults), 0);
  }
}

function storageSet(obj, callback) {
  // helper: replace large data: URLs (images/videos) with small stubs to avoid storage quota errors
  // but preserve the first 10 images and first video per listing so thumbnails remain visible
  const MAX_INLINE_IMAGES = 10;
  const MAX_INLINE_VIDEOS = 1;

  function shouldKeepInline(path) {
    try {
      if (path && path.length >= 4 && path[0] === 'listings') {
        if (path[2] === 'images') {
          const idx = Number(path[3]);
          if (Number.isFinite(idx) && idx < MAX_INLINE_IMAGES) return true;
        }
        if (path[2] === 'videos') {
          const idx = Number(path[3]);
          if (Number.isFinite(idx) && idx < MAX_INLINE_VIDEOS) return true;
        }
      }
    } catch (e) {}
    return false;
  }

  function stripLargeDataUrls(val, thresholdBytes = 100 * 1024, path = []) {
    // thresholdBytes default 100KB
    if (val == null) return val;
    if (typeof val === 'string') {
      if (/^data:(image|video)\//.test(val)) {
        if (shouldKeepInline(path)) return val;
        try {
          const len = val.length;
          if (len > thresholdBytes) return { __ffm_data_stub: true, type: val.slice(5, Math.min(25, val.length)), length: len };
        } catch (e) { return { __ffm_data_stub: true }; }
      }
      return val;
    }
    if (Array.isArray(val)) return val.map((v, i) => stripLargeDataUrls(v, thresholdBytes, path.concat([i])));
    if (typeof val === 'object') {
      const out = {};
      for (const k in val) out[k] = stripLargeDataUrls(val[k], thresholdBytes, path.concat([k]));
      return out;
    }
    return val;
  }

  if (window.chrome && chrome.storage && chrome.storage.local && chrome.storage.local.set) {
  chrome.storage.local.set(obj, function() {
      // Check for quota errors and retry with stripped data if necessary
      try {
        const err = (window.chrome && chrome.runtime && chrome.runtime.lastError) ? chrome.runtime.lastError : null;
        if (err && /quota/i.test(err.message || '')) {
          console.warn('chrome.storage.local.set quota exceeded, retrying with large data URLs stripped');
          const stripped = {};
          for (const k in obj) stripped[k] = stripLargeDataUrls(obj[k], 100 * 1024, [k]);
          try {
            chrome.storage.local.set(stripped, function() {
              const err2 = (window.chrome && chrome.runtime && chrome.runtime.lastError) ? chrome.runtime.lastError : null;
              if (err2) {
                console.error('Retry storageSet after stripping failed', err2);
              } else {
                console.debug('storageSet succeeded after stripping large data URLs');
              }
              if (callback) callback();
            });
            return;
          } catch (e) {
            console.error('storageSet retry threw', e);
          }
        }
      } catch (e) { console.error('storageSet post-set check error', e); }
      if (callback) callback();

      // If suppression flag is set, skip auto-sync triggering for this storage write.
      try {
        if (window.__ffm_suppress_auto_sync && window.__ffm_suppress_auto_sync > 0) {
          if (window.FFM_DEBUG_MODE) console.debug('[AutoList Pro popup] storageSet: auto-sync suppressed for this write');
          return;
        }

        const autoOn = !!(window.ffm_auto_sync_cloud || (document.getElementById('auto-sync-cloud-toggle') && document.getElementById('auto-sync-cloud-toggle').checked));
        if (autoOn && typeof window.ffmMaybeAutoSync === 'function') {
          try {
            for (const k in obj) {
              try {
                const v = obj[k];
                if (!v) continue;
                // canonical listings array
                if (k === 'listings' && Array.isArray(v)) {
                  for (const it of v) {
                    try { if (it && (it.listingId || it.id || it.inventoryName)) window.ffmMaybeAutoSync(it); } catch(e){}
                  }
                  continue;
                }
                // other known arrays
                if ((k === 'ffm_saved_listings' || k === 'ffmSavedListings' || k === '__ffm_saved_listings_cache') && Array.isArray(v)) {
                  for (const it of v) {
                    try { if (it && (it.listingId || it.id || it.inventoryName)) window.ffmMaybeAutoSync(it); } catch(e){}
                  }
                  continue;
                }
                // per-listing entry persisted under ffm_<id>
                if (typeof k === 'string' && k.startsWith('ffm_') && typeof v === 'object') {
                  try { if (v && (v.listingId || v.id || v.inventoryName)) window.ffmMaybeAutoSync(v); } catch(e){}
                  continue;
                }
                // Generic object that looks like a listing
                if (typeof v === 'object' && (v.listingId || v.id || v.inventoryName)) {
                  try { window.ffmMaybeAutoSync(v); } catch(e){}
                  continue;
                }
              } catch (e) {}
            }
          } catch (e) {}
        }
      } catch (e) {}
    });
    return;
  }

  try {
    const raw = localStorage.getItem('fast4mp_storage');
    const parsed = raw ? JSON.parse(raw) : {};
  const merged = Object.assign({}, parsed, stripLargeDataUrls(obj, 100 * 1024, []));
    localStorage.setItem('fast4mp_storage', JSON.stringify(merged));
    if (callback) setTimeout(callback, 0);
    // After fallback persist, try auto-sync as well
    try {
      // If suppression flag is set, skip auto-sync triggering for this storage write.
      if (window.__ffm_suppress_auto_sync && window.__ffm_suppress_auto_sync > 0) {
        if (window.FFM_DEBUG_MODE) console.debug('[AutoList Pro popup] storageSet (localStorage fallback): auto-sync suppressed for this write');
      } else {
        const autoOn = !!(window.ffm_auto_sync_cloud || (document.getElementById('auto-sync-cloud-toggle') && document.getElementById('auto-sync-cloud-toggle').checked));
        if (autoOn && typeof window.ffmMaybeAutoSync === 'function') {
          try {
            for (const k in obj) {
              try {
                const v = obj[k];
                if (!v) continue;
                if (k === 'listings' && Array.isArray(v)) {
                  for (const it of v) try { if (it && (it.listingId || it.id || it.inventoryName)) window.ffmMaybeAutoSync(it); } catch(e){}
                  continue;
                }
                if ((k === 'ffm_saved_listings' || k === 'ffmSavedListings' || k === '__ffm_saved_listings_cache') && Array.isArray(v)) {
                  for (const it of v) try { if (it && (it.listingId || it.id || it.inventoryName)) window.ffmMaybeAutoSync(it); } catch(e){}
                  continue;
                }
                if (typeof k === 'string' && k.startsWith('ffm_') && typeof v === 'object') {
                  try { if (v && (v.listingId || v.id || v.inventoryName)) window.ffmMaybeAutoSync(v); } catch(e){}
                  continue;
                }
                if (typeof v === 'object' && (v.listingId || v.id || v.inventoryName)) {
                  try { window.ffmMaybeAutoSync(v); } catch(e){}
                  continue;
                }
              } catch (e) {}
            }
          } catch (e) {}
        }
      }
    } catch (e) {}
  } catch (err) {
    console.error('storageSet fallback error', err);
    if (callback) setTimeout(callback, 0);
  }
}

// Auto-Sync helper: attempt to upload a single listing's media + metadata to cloud when enabled
// Helper: set a short suppression window to prevent auto-sync from reacting to
// storage writes performed during UI refreshes (milliseconds).
window.ffmSuppressAutoSync = function(ms) {
  try { ms = (typeof ms === 'number' && ms > 0) ? ms : 1200; } catch (e) { ms = 1200; }
  try { window.__ffm_suppress_auto_sync = Date.now() + ms; } catch (e) {}
};

window.ffmMaybeAutoSync = async function(listing) {
  try {
    try {
      // Respect transient suppression window set around Saved Listings refreshes
      if (window.__ffm_suppress_auto_sync && window.__ffm_suppress_auto_sync > Date.now()) {
        try { if (window.FFM_DEBUG_MODE) console.log('[AutoList Pro] ffmMaybeAutoSync aborted: suppression active'); } catch (e) {}
        return;
      }
    } catch (e) {}
    if (!listing) return;
    try {
      const autoOn = !!(window.ffm_auto_sync_cloud || (document.getElementById('auto-sync-cloud-toggle') && document.getElementById('auto-sync-cloud-toggle').checked));
      if (!autoOn) return;
    } catch (e) {}

    const lid = listing.listingId || listing.id || null;
    // Debounce short-lived duplicate writes (avoid immediate duplicate uploads)
    try {
      window.__ffm_auto_sync_recent = window.__ffm_auto_sync_recent || {};
      if (lid) {
        const prev = window.__ffm_auto_sync_recent[lid];
        if (prev && (Date.now() - prev) < 5000) return; // skip if recent (5s)
        window.__ffm_auto_sync_recent[lid] = Date.now();
      }
    } catch (e) {}

    try {
      await window.ffmUploadListingToCloud(listing);
    } catch (e) { console.debug('ffmMaybeAutoSync upload error', e); }
  } catch (e) { console.debug('ffmMaybeAutoSync outer error', e); }
};

// Small wrapper to upload media then metadata using existing helpers
window.ffmUploadListingToCloud = async function(listing) {
  try {
    if (!listing) return false;
    const provider = await getCloudProvider();
    if (!provider) return false;
    // Avoid duplicate concurrent uploads at higher-level; awsUploadListingMetadata already guards per-id
    try {
      if (provider === 'aws') {
        try { await saveListingImages(listing, { verifyExisting: true }); } catch (e) {}
        try { await saveListingVideos(listing, { verifyExisting: true }); } catch (e) {}
        try { await saveListingMetadata(listing); } catch (e) {}
        try { await awsUploadListingMetadata(listing); } catch (e) { console.debug('awsUploadListingMetadata error in ffmUploadListingToCloud', e); }
        return true;
      } else {
        // Drive path (best-effort)
        try { await saveListingImagesToDrive(listing, { verifyExisting: true }); } catch (e) {}
        try { await saveListingVideosToDrive(listing, { verifyExisting: true }); } catch (e) {}
        try { await saveListingMetadataToDrive(listing); } catch (e) {}
        return true;
      }
    } catch (e) { console.debug('ffmUploadListingToCloud error', e); return false; }
  } catch (e) { console.debug('ffmUploadListingToCloud outer error', e); return false; }
};

/* -------------------------------
   Sync storage helpers (chrome.storage.sync) with localStorage fallback
   Use storageGetSync({ listings_meta: [] }, cb) and storageSetSync(obj, cb)
   where obj should be small (metadata-only) to avoid chrome.storage.sync quota issues
------------------------------- */
function storageGetSync(defaults, callback) {
  if (window.chrome && chrome.storage && chrome.storage.sync && chrome.storage.sync.get) {
    try { chrome.storage.sync.get(defaults, callback); return; } catch (e) { /* fallthrough */ }
  }

  // fallback to localStorage-specific key
  try {
    const raw = localStorage.getItem('fast4mp_sync_storage');
    const parsed = raw ? JSON.parse(raw) : {};
    const result = {};
    for (const k in defaults) result[k] = parsed.hasOwnProperty(k) ? parsed[k] : defaults[k];
    setTimeout(() => callback(result), 0);
  } catch (err) {
    console.error('storageGetSync fallback error', err);
    setTimeout(() => callback(defaults), 0);
  }
}

function storageSetSync(obj, callback) {
  if (window.chrome && chrome.storage && chrome.storage.sync && chrome.storage.sync.set) {
    try { chrome.storage.sync.set(obj, callback); return; } catch (e) { /* fallthrough */ }
  }

  try {
    const raw = localStorage.getItem('fast4mp_sync_storage');
    const parsed = raw ? JSON.parse(raw) : {};
    const merged = Object.assign({}, parsed, obj);
    localStorage.setItem('fast4mp_sync_storage', JSON.stringify(merged));
    if (callback) setTimeout(callback, 0);
  } catch (err) {
    console.error('storageSetSync fallback error', err);
    if (callback) setTimeout(callback, 0);
  }
}

// Prepare listings for storage by stripping large data URLs from images/videos to avoid chrome.storage quota errors.
function prepareListingsForStorage(listings) {
  if (!Array.isArray(listings)) return listings;
  const MAX_KEEP = 1000; // keep many images inline to preserve quality for full resync
  return listings.map(l => {
    const copy = Object.assign({}, l);
    try {
      if (Array.isArray(copy.images)) {
        copy.images = copy.images.map((d, i) => {
          if (!d) return d;
          if (typeof d === 'string' && d.length > 120 * 1024) {
            // keep first few inline UNCHANGED so UI can render; stub the rest to avoid quota
            if (i < MAX_KEEP) return d; // keep full data URL for first few
            // If this image slot has NOT been uploaded to Drive yet (no corresponding driveFileId), keep it inline so Sync can upload it
            const hasDriveIdHere = Array.isArray(copy.driveFileIds) && !!copy.driveFileIds[i];
            const hasS3KeyHere = Array.isArray(copy.s3ImageKeys) && !!copy.s3ImageKeys[i];
            if (!hasDriveIdHere && !hasS3KeyHere) return d;
            return { __ffm_data_stub: true, kind: 'image', length: d.length };
          }
          return d;
        });
      }
      if (Array.isArray(copy.videos)) {
        copy.videos = copy.videos.map((d, i) => {
          if (!d) return d;
          if (typeof d === 'string' && d.length > 200 * 1024) {
            // keep first video intact; stub the rest
            if (i < 1) return d;
            // If this video slot has NOT been uploaded yet, keep it inline so Sync can upload it
            const hasDriveVidHere = Array.isArray(copy.driveVideoIds) && !!copy.driveVideoIds[i];
            const hasS3VidHere = Array.isArray(copy.s3VideoKeys) && !!copy.s3VideoKeys[i];
            if (!hasDriveVidHere && !hasS3VidHere) return d;
            return { __ffm_data_stub: true, kind: 'video', length: d.length };
          }
          return d;
        });
      }
    } catch (e) { console.debug('prepareListingsForStorage error', e); }
    return copy;
  });
}

// Verify Drive linkage for a listing and prune stale IDs; returns summary
async function recheckCloudForListing(inventoryName) {
  try {
    const token = await getDriveAuthToken(true);
    if (!token) return null;
    const local = await new Promise((res)=> storageGet({ listings: [] }, (r)=> res((r.listings||[]).find(x=>x&&x.inventoryName===inventoryName)||null)));
    if (!local) return null;
    // Check metadata file
    let metaOk = false;
    if (local.driveMetaId) metaOk = await driveFileExists(local.driveMetaId);
    // Check media IDs and prune any missing
    let imgKept = 0, imgRemoved = 0, vidKept = 0, vidRemoved = 0;
    const keepImages = [];
    for (const id of (local.driveFileIds||[])) { const ok = await driveFileExists(id); if (ok) { keepImages.push(id); imgKept++; } else { imgRemoved++; } }
    const keepVideos = [];
    for (const id of (local.driveVideoIds||[])) { const ok = await driveFileExists(id); if (ok) { keepVideos.push(id); vidKept++; } else { vidRemoved++; } }
    // Persist pruned state
    await new Promise((resolve)=> storageGet({ listings: [] }, (res)=>{
      const arr = res.listings || [];
      const ix = arr.findIndex(x=>x&&x.inventoryName===inventoryName);
      if (ix >= 0) {
        arr[ix].driveFileIds = keepImages;
        arr[ix].driveVideoIds = keepVideos;
        if (local.driveMetaId && !metaOk) arr[ix].driveMetaId = '';
        storageSet({ listings: prepareListingsForStorage(arr) }, resolve);
      } else { resolve(); }
    }));
    return { metaOk, imgKept, imgRemoved, vidKept, vidRemoved };
  } catch (e) { console.debug('recheckCloudForListing error', e); return null; }
}

// Clear Drive linkage locally (does not delete files in Drive)
async function unsyncListingLocal(inventoryName) {
  return new Promise((resolve)=> storageGet({ listings: [] }, (res)=>{
    const arr = res.listings || [];
    const ix = arr.findIndex(x=>x&&x.inventoryName===inventoryName);
    if (ix >= 0) {
      arr[ix].driveMetaId = '';
      arr[ix].driveFileIds = [];
      arr[ix].driveVideoIds = [];
      arr[ix].s3ImageKeys = [];
      arr[ix].s3VideoKeys = [];
      arr[ix].awsLinked = false;
      storageSet({ listings: prepareListingsForStorage(arr) }, resolve);
    } else resolve();
  }));
}

// Save listing metadata JSON to Drive and persist driveMetaId locally
async function saveListingMetadataToDrive(listing) {
  try {
    const token = await getDriveAuthToken(true);
    if (!token) { console.warn('No Drive token for metadata upload'); return false; }
    const json = {
      inventoryName: listing.inventoryName,
      title: listing.title,
      price: listing.price,
      retailPrice: listing.retailPrice,
      category: listing.category,
      condition: listing.condition,
      bedSize: listing.bedSize,
      core: listing.core,
      comfortLevel: listing.comfortLevel,
      hideFromFriends: listing.hideFromFriends,
      description: listing.description || '',
      timestamp: listing.timestamp,
      driveFileIds: listing.driveFileIds || [],
      driveVideoIds: listing.driveVideoIds || []
    };
    const filename = `${listing.inventoryName}_listing.json`;
    let fileId = listing.driveMetaId || null;
    if (fileId) {
      const ok = await updateJsonInDrive(token, fileId, json);
      if (!ok) {
        const newId = await uploadJsonToDrive(token, json, filename);
        if (!newId) return false;
        fileId = newId;
      }
    } else {
      fileId = await uploadJsonToDrive(token, json, filename);
      if (!fileId) return false;
    }
    // Persist driveMetaId onto the listing in storage so UI reflects synced state
    await new Promise((resolve)=> storageGet({ listings: [] }, (res)=>{
      const arr = res.listings || [];
      const ix = arr.findIndex(l => l && l.inventoryName === listing.inventoryName);
      if (ix >= 0) {
        arr[ix].driveMetaId = fileId;
      } else {
        const nl = Object.assign({}, listing, { driveMetaId: fileId });
        arr.push(nl);
      }
      storageSet({ listings: prepareListingsForStorage(arr) }, resolve);
    }));
    return true;
  } catch (e) { console.debug('saveListingMetadataToDrive error', e); return false; }
}

