                if (recentlyCreated != null && recentlyCreated < 3000) {
                  try { /* skip background open (recent local create) */ } catch(e){}
                } else {
                  if (chrome && chrome.runtime && typeof chrome.runtime.sendMessage === 'function') {
                    chrome.runtime.sendMessage({ action: 'ffm_start_select_mode_popup' }, (r) => { try { if (chrome.runtime && chrome.runtime.lastError) { /* ignore */ } } catch (e) {} });
                  }
                }
