              // normalize/parse price when available (digits only) to prefer title+price matches
              priceRaw: (it && (it.price || it.priceText || '')) ? String(it.price || it.priceText || '') : '',
              priceNorm: ((it && (it.price || it.priceText)) ? String(it.price || it.priceText).replace(/[^0-9\.]/g,'').trim() : ''),
              // prefer overlay-provided timestamp, fall back to parsing the raw date string
