                si.listedDaysAgo = (typeof days === 'number' && days >= 0) ? days : (typeof si.listedDaysAgo === 'number' ? si.listedDaysAgo : null);
                // Human-readable text (if available) — prefer fbStatusRaw, otherwise construct from days
                si.fbListedText = si.fbStatusRaw || (typeof si.fbListedDays === 'number' ? ffmBuildListedLabelFromDays(si.fbListedDays) : si.fbListedText || '');

