// Helper to retrieve a listing by Inventory Name (callback receives listing or undefined)
function getListingByInventoryName(inventoryName, callback) {
  chrome.storage.local.get({ listings: [] }, (result) => {
    const listings = result.listings || [];
    const found = listings.find((l) => l.inventoryName === inventoryName);
    callback && callback(found);
  });
}

// Expose helper for other popup scripts (if needed)
window.getListingByInventoryName = getListingByInventoryName;

// Download images for a listing from Google Drive (driveFileIds must be present)
function downloadImagesForListing(listing) {
  if (!listing || !listing.driveFileIds || !listing.driveFileIds.length) {
    alert('No remote images available for this listing.');
    return;
  }
  statusBar.textContent = `Downloading ${listing.driveFileIds.length} image(s) from Drive for '${listing.inventoryName}'...`;
  downloadImagesFromDrive(listing.driveFileIds).then((imgs) => {
    if (!imgs || !imgs.length) {
      statusBar.textContent = 'No images were downloaded.';
      alert('No images were downloaded from Drive.');
      return;
    }
    storageGet({ listings: [] }, (res) => {
      const listings = res.listings || [];
      const ix = listings.findIndex(l => l.inventoryName === listing.inventoryName);
        if (ix >= 0) {
        listings[ix].images = (listings[ix].images || []).concat(imgs);
        storageSet({ listings: prepareListingsForStorage(listings) }, () => {
          statusBar.textContent = `Downloaded ${imgs.length} image(s) for '${listing.inventoryName}'.`;
          safeDisplaySavedListings('downloadImagesForListing');
        });
      } else {
        const nl = Object.assign({}, listing, { images: imgs, timestamp: Date.now() });
        listings.push(nl);
        storageSet({ listings: prepareListingsForStorage(listings) }, () => {
          statusBar.textContent = `Saved listing '${nl.inventoryName}' with ${imgs.length} downloaded image(s).`;
          safeDisplaySavedListings('downloadImagesForListing');
        });
      }
    });
  }).catch((e) => {
    console.error('downloadImagesForListing error', e);
    statusBar.textContent = 'Error downloading images from Drive.';
    alert('Error downloading images from Drive. See console for details.');
  });
}

// Modal helpers
const confirmModal = document.getElementById('confirm-modal');
const confirmMessage = document.getElementById('confirm-message');
const confirmYes = document.getElementById('confirm-yes');
const confirmNo = document.getElementById('confirm-no');

function showConfirm(message, opts = {}) {
  return new Promise((resolve) => {
    // Ensure modal element exists; if not, fallback to native confirm
    if (!confirmModal) {
      const ok = window.confirm(message);
      resolve(ok);
      return;
    }

    // Query buttons at call time to avoid stale references
    const yesBtn = document.getElementById('confirm-yes');
    const noBtn = document.getElementById('confirm-no');

    // If buttons aren't present, fallback to native confirm
    if (!yesBtn || !noBtn) {
      console.debug('showConfirm: missing confirm buttons, falling back to window.confirm', { yesBtn: !!yesBtn, noBtn: !!noBtn });
      const ok = window.confirm(message);
      resolve(ok);
      return;
    }

    // Store current focus
    const lastFocused = document.activeElement;

    try {
      if (opts && opts.html) {
        try { confirmMessage.innerHTML = typeof message === 'string' ? message : String(message); } catch (e) { confirmMessage.textContent = String(message); }
      } else {
        confirmMessage.textContent = message;
      }
    } catch (e) { console.debug('showConfirm: could not set message', e); }

    // Optional tooltip/subtext under the main message
    try {
      const sub = document.getElementById('confirm-subtext');
      if (sub) {
        if (opts && opts.tooltip) {
          try { sub.textContent = String(opts.tooltip); } catch (e) { sub.textContent = '' + opts.tooltip; }
        } else {
          try { sub.textContent = '\u00A0'; } catch (e) { sub.textContent = ''; }
        }
      }
    } catch (e) {}

    // Make sure content allows pointer events (in case global styles interfere)
    try { const content = confirmModal.querySelector('.confirm-modal-content'); if (content) content.style.pointerEvents = 'auto'; } catch (e) {}

    confirmModal.setAttribute('aria-hidden', 'false');

    function cleanup() {
      // Remove focus from modal elements first
      try {
        const focusedElement = document.activeElement;
        if (focusedElement && confirmModal.contains(focusedElement)) {
          focusedElement.blur();
        }
      } catch (e) {}

      // Small delay to ensure focus is removed
      setTimeout(() => {
        try { confirmModal.setAttribute('aria-hidden', 'true'); } catch (e) {}
        // Restore focus
        if (lastFocused && lastFocused.focus) {
          try { lastFocused.focus(); } catch (e) { console.debug('Could not restore focus in confirm modal:', e); }
        }
      }, 10);

      try { yesBtn.removeEventListener('click', onYes); } catch (e) {}
      try { noBtn.removeEventListener('click', onNo); } catch (e) {}
      if (confirmModal.escapeKeyListener) {
        document.removeEventListener('keydown', confirmModal.escapeKeyListener);
        confirmModal.escapeKeyListener = null;
      }
    }

  function onYes(e) { try { if (e && e.preventDefault) { e.preventDefault(); e.stopPropagation(); } } catch(_){}; console.debug('showConfirm: yes clicked'); cleanup(); resolve(true); }
  function onNo(e) { try { if (e && e.preventDefault) { e.preventDefault(); e.stopPropagation(); } } catch(_){}; console.debug('showConfirm: no clicked'); cleanup(); resolve(false); }

    // Add escape key support
    confirmModal.escapeKeyListener = (e) => {
      if (e.key === 'Escape') {
        onNo();
      }
    };
    document.addEventListener('keydown', confirmModal.escapeKeyListener);

    // Ensure buttons are enabled and visible
    try { yesBtn.disabled = false; noBtn.disabled = false; } catch (e) {}

    // Attach listeners (use capturing false; cleanup will remove them)
    try {
      yesBtn.addEventListener('click', onYes);
      noBtn.addEventListener('click', onNo);
    } catch (e) { console.debug('showConfirm: addEventListener failed', e); }

    // Reset to defaults each time to avoid stale labels
    try {
      if (yesBtn) yesBtn.textContent = 'Delete';
      if (noBtn) noBtn.textContent = 'Cancel';
    } catch (e) {}

    // Optional: support custom button labels
    try {
      if (opts && (opts.yesLabel || opts.noLabel)) {
        if (opts.yesLabel && yesBtn) yesBtn.textContent = opts.yesLabel;
        if (opts.noLabel && noBtn) noBtn.textContent = opts.noLabel;
      }
    } catch (e) {}

    // Focus the "No" button by default for safety
    setTimeout(() => {
      try { if (noBtn) noBtn.focus(); } catch (e) {}
    }, 100);
  });
}

// Small helper: show a temporary 3-choice modal and return the chosen label (or null on cancel)
function showChoiceModal(htmlMessage, choices = ['Local only','Cloud only','Both']) {
  return new Promise((resolve) => {
    try {
      const wrapper = document.createElement('div');
      wrapper.className = 'ffm-choice-overlay';
      wrapper.style.position = 'fixed'; wrapper.style.left = 0; wrapper.style.top = 0; wrapper.style.right = 0; wrapper.style.bottom = 0; wrapper.style.background = 'rgba(0,0,0,0.35)'; wrapper.style.display = 'flex'; wrapper.style.alignItems = 'center'; wrapper.style.justifyContent = 'center'; wrapper.style.zIndex = 9999;
      const box = document.createElement('div');
      box.style.background = '#fff'; box.style.padding = '14px'; box.style.borderRadius = '8px'; box.style.width = '420px'; box.style.maxHeight = '70vh'; box.style.overflow = 'auto'; box.style.boxShadow = '0 6px 18px rgba(0,0,0,0.15)';
      box.innerHTML = `<div style="font-size:13px">${htmlMessage}</div>`;
      const btnRow = document.createElement('div'); btnRow.style.marginTop = '12px'; btnRow.style.display = 'flex'; btnRow.style.gap = '8px';
      choices.forEach((c, ix) => {
        const b = document.createElement('button'); b.textContent = c; b.className = 'ffm-choice-btn'; b.style.padding = '6px 10px'; b.style.cursor = 'pointer';
        if (ix === 0) { b.style.background = '#d9534f'; b.style.color = '#fff'; b.style.border = 'none'; }
        else if (ix === 1) { b.style.background = '#f0ad4e'; b.style.color = '#fff'; b.style.border = 'none'; }
        else { b.style.background = '#6c757d'; b.style.color = '#fff'; b.style.border = 'none'; }
        b.addEventListener('click', () => { try { document.body.removeChild(wrapper); } catch(e){}; resolve(c); });
        btnRow.appendChild(b);
      });
      const cancel = document.createElement('button'); cancel.textContent = 'Cancel'; cancel.style.marginLeft = 'auto'; cancel.style.background = 'transparent'; cancel.style.border = '1px solid #ccc'; cancel.style.padding = '6px 10px';
      cancel.addEventListener('click', () => { try { document.body.removeChild(wrapper); } catch(e){}; resolve(null); });
      btnRow.appendChild(cancel);
      box.appendChild(btnRow);
      wrapper.appendChild(box);
      document.body.appendChild(wrapper);
      const onKey = (e) => { if (e.key === 'Escape') { try { document.body.removeChild(wrapper); } catch(e){}; document.removeEventListener('keydown', onKey); resolve(null); } };
      document.addEventListener('keydown', onKey);
    } catch (e) { console.debug('showChoiceModal error', e); resolve(null); }
  });
}

// On popup load, check for a hash to open the requested section
function openSectionFromHash() {
  try {
    const hash = (window.location.hash || '').replace('#', '');
    if (!hash) return;
    switch (hash) {
      case 'create':
        toggleSection(createListingSection);
        statusBar.textContent = 'Create Listing Section Opened.';
        break;
      case 'publish':
  savedListingsView = 'publish';
  toggleSection(savedListingsSection);
  displayPublishListings();
  setStatus('Saved Listings Section Opened.');
        try { requestAnimationFrame(() => ffmSnapToSavedListings()); } catch (e) {}
        break;
      case 'edit':
        savedListingsView = 'saved';
  toggleSection(savedListingsSection);
  safeDisplaySavedListings('openSection:edit');
  setStatus('Saved Listings Section Opened.');
        try { requestAnimationFrame(() => ffmSnapToSavedListings()); } catch (e) {}
        break;
      case 'delete':
  toggleSection(savedListingsSection);
  safeDisplaySavedListings('openSection:delete');
  setStatus('Delete & Relist Section Opened.');
        break;
      default:
        break;
    }
  } catch (err) {
    console.error('openSectionFromHash error', err);
  }
}
