const scheduleAction = typeof document !== 'undefined' ? document.getElementById('schedule-action') : null;
const scheduleDatetime = typeof document !== 'undefined' ? document.getElementById('schedule-datetime') : null;
const scheduleSaveBtn = typeof document !== 'undefined' ? document.getElementById('schedule-save') : null;
