function openScheduleModalForListing(listing, opener) {
  try {
    if (!scheduleModal) return;
    __ffm_current_schedule_listing = listing || null;
    // remember opener to restore focus on close
    try { __ffm_schedule_opener = opener || null; } catch (e) { __ffm_schedule_opener = null; }
    // set sane default datetime: next full minute + 1 minute
    try {
      const now = new Date();
      const plus = new Date(now.getTime() + 60 * 1000);
      // format to local yyyy-mm-ddThh:mm for datetime-local
      const pad = (n) => (n < 10 ? '0' + n : '' + n);
      const localStr = plus.getFullYear() + '-' + pad(plus.getMonth() + 1) + '-' + pad(plus.getDate()) + 'T' + pad(plus.getHours()) + ':' + pad(plus.getMinutes());
      if (scheduleDatetime) scheduleDatetime.value = localStr;
    } catch (e) { if (scheduleDatetime) scheduleDatetime.value = ''; }
    if (scheduleAction) scheduleAction.value = 'publish';
    scheduleModal.setAttribute('aria-hidden', 'false');
    try { scheduleModal.removeAttribute('inert'); } catch (e) {}
    // Read persisted preference and hide warning if user opted out
    try {
      if (scheduleWarning) {
        try {
          chrome && chrome.storage && chrome.storage.local && chrome.storage.local.get && chrome.storage.local.get({ schedule_hide_warning: false }, (res) => {
            try {
              const hide = !!(res && res.schedule_hide_warning);
              if (hide) {
                try { scheduleWarning.style.display = 'none'; } catch (_) {}
              } else {
                try { scheduleWarning.style.display = ''; } catch (_) {}
              }
              if (scheduleHideCheckbox) scheduleHideCheckbox.checked = hide;
            } catch (e) {}
          });
        } catch (e) {}
      }
    } catch (e) {}
    try { if (scheduleSaveBtn) scheduleSaveBtn.focus(); } catch (e) {}
  } catch (e) { console.debug('openScheduleModalForListing error', e); }
}

