          // Also clear any localStorage copy (fallback path)
          try { if (window && window.localStorage && typeof window.localStorage.removeItem === 'function') window.localStorage.removeItem('schedule_hide_warning'); } catch (e) {}
          try { if (scheduleWarning) scheduleWarning.style.display = ''; } catch (e) {}
