async function saveScheduledTask() {
  try {
    if (!__ffm_current_schedule_listing) return;
    const action = (scheduleAction && scheduleAction.value) ? scheduleAction.value : 'publish';
    // Allow scheduling of 'relist' tasks. Background will perform a
    // non-destructive first step (open the selling page) when the alarm fires.
    const dtval = scheduleDatetime && scheduleDatetime.value ? scheduleDatetime.value : null;
    if (!dtval) { window.showToast && window.showToast('Please select a date & time', 'error'); return; }
    const whenMs = new Date(dtval).getTime();
    if (isNaN(whenMs) || whenMs <= Date.now()) { window.showToast && window.showToast('Please choose a future date/time', 'error'); return; }

    // Build task object (keep small; large publish payloads are staged separately)
    const taskId = Math.random().toString(36).slice(2) + Date.now().toString(36);
    const task = {
      id: taskId,
      taskId: taskId,
      listingId: (__ffm_current_schedule_listing && (__ffm_current_schedule_listing.listingId || __ffm_current_schedule_listing.id)) || null,
      inventoryName: __ffm_current_schedule_listing.inventoryName || '',
      listingTitle: __ffm_current_schedule_listing.title || __ffm_current_schedule_listing.listingTitle || __ffm_current_schedule_listing.inventoryName || '',
      action,
      timeISO: new Date(whenMs).toISOString(),
      when: whenMs
    };

    // If scheduling a publish, stage the full listing to avoid embedding large payloads in scheduled_tasks
    if (action === 'publish') {
      try {
        // Use a suffix id (no 'ffm_publish_' prefix) to match other publish flows
        const publishRequestId = Math.random().toString(36).slice(2) + Date.now().toString(36);
  try {
    await storageLocalSetAsync({ ['ffm_publish_' + publishRequestId]: __ffm_current_schedule_listing });
    try {
      const last = Object.assign({}, __ffm_current_schedule_listing);
      try { last.publishRequestId = publishRequestId; } catch (e) {}
      try { chrome.storage.local.set({ ffm_last_publish: last }); } catch (e) {}
    } catch (e) {}
  } catch (e) {
    try { console.debug('scheduling: staging publish failed, retrying with stripped data', e); } catch(_) {}
    try {
      const stripped = {};
      stripped['ffm_publish_' + publishRequestId] = stripLargeDataUrls(__ffm_current_schedule_listing, 100 * 1024, ['listing']);
      try { stripped['ffm_publish_' + publishRequestId].__ffm_stripped = true; } catch(_) {}
      await storageLocalSetAsync(stripped);
    } catch (e2) { console.debug('scheduling: failed to stage publish after stripping', e2); }
  }
        // store reference id on task so background knows which staged payload to use (suffix form)
        task.publishRequestId = publishRequestId;
      } catch (e) { console.debug('failed to stage publish for schedule', e); }
    }

    // Persist into scheduled_tasks array
    chrome.storage.local.get({ scheduled_tasks: [] }, (res) => {
      try {
        const arr = res.scheduled_tasks || [];
        arr.push(task);
        chrome.storage.local.set({ scheduled_tasks: arr }, () => {
          try { window.showToast && window.showToast('Scheduled saved', 'success'); } catch (e) {}
          // notify background to create the alarm (best-effort)
          try { ffmSendMessage({ action: 'schedule-task', task }, (r) => { try { if (!r) return; console.debug('schedule-task response', r); } catch(e){} }); } catch (e) {}
          closeScheduleModal();
          try {
            // Update the cached scheduled tasks map so UI immediately reflects the new schedule
            try {
              window.__ffm_scheduled_tasks_map = window.__ffm_scheduled_tasks_map || {};
              const rawName = task.listing && task.listing.inventoryName ? task.listing.inventoryName : task.inventoryName;
              if (rawName) {
                const k = normalizeInventoryName(rawName);
                window.__ffm_scheduled_tasks_map[k] = (window.__ffm_scheduled_tasks_map[k] || []).concat([task]);
              }
            } catch (e) { console.debug('update scheduled_tasks map error', e); }
            safeDisplaySavedListings('taskScheduled');
            displayPublishListings && displayPublishListings();
          } catch (e) {}
        });
      } catch (e) { console.debug('saveScheduledTask storage error', e); }
    });
  } catch (e) { console.debug('saveScheduledTask error', e); }
}

// Scheduled Tasks management UI
const scheduledTasksBtn = typeof document !== 'undefined' ? document.getElementById('open-scheduled-tasks') : null;
const scheduledTasksModal = typeof document !== 'undefined' ? document.getElementById('scheduled-tasks-modal') : null;
