// If Sharetown provided scraped details, prefill the Create form once when Create is shown
(async function ffmPrefillFromSharetown(){
  try {
    const get = (keys) => new Promise((res)=>chrome.storage.local.get(keys, (r)=>res(r||{})));
    const set = (obj) => new Promise((res)=>chrome.storage.local.set(obj, ()=>res()));
    const incoming = (await get(['ffm_incoming_listing'])).ffm_incoming_listing || null;
    if (!incoming) return;
    // If we're not on Create yet, switch to it
    if (createListingSection && createListingSection.classList.contains('hidden-section')) {
      toggleSection(createListingSection);
      statusBar.textContent = 'Create Listing Section Opened.';
    }
  // Prefill fields if present
    try { const invEl = document.getElementById('inventory-name'); if (incoming.inventoryName && invEl) invEl.value = incoming.inventoryName; } catch (e) {}

    // Derive Bed Size and Core from Inventory Name when possible
    try {
      const text = (incoming.inventoryName || '').toString();
      const setSelectByText = (sel, target) => {
        try {
          if (!sel || !target) return false;
          const opts = Array.from(sel.options || []);
          const hit = opts.find(o => (o.text || '').toString().trim().toLowerCase() === target.toString().trim().toLowerCase());
          if (hit) { sel.value = hit.value; sel.dispatchEvent(new Event('change', { bubbles: true })); return true; }
          return false;
        } catch (e) { return false; }
      };

      // Detect bed size (order matters to avoid partial overlaps)
      const sizePatterns = [
        { re: /\b(cal(?:ifornia)?\s*-?\s*king|cal\s*king|ca\s*king|ck)\b/i, value: 'California King' },
        { re: /\b(twin\s*xl|twin[- ]?extra[- ]?long|txl)\b/i, value: 'Twin XL' },
        { re: /\bking\b/i, value: 'King' },
        { re: /\bqueen\b/i, value: 'Queen' },
        { re: /\bfull\b/i, value: 'Full' },
        { re: /\btwin\b/i, value: 'Twin' }
      ];
      const sizeHit = sizePatterns.find(p => p.re.test(text));
      if (sizeHit) {
        const sizeSel = document.getElementById('bed-size');
        setSelectByText(sizeSel, sizeHit.value);
      }

      // Detect core (order matters: Gel Foam should win over Memory Foam)
      const corePatterns = [
        { re: /\bgel\s*(memory\s*)?foam\b/i, value: 'Gel Foam' },
        { re: /\bmemory\s*foam\b/i, value: 'Memory Foam' },
        { re: /\bhybrid\b/i, value: 'Hybrid' },
        { re: /\binner\s*spring\b|\binnerspring\b|\bpocketed\s*coils?\b/i, value: 'Innerspring' },
        { re: /\blatex\b/i, value: 'Latex' }
      ];
      const coreHit = corePatterns.find(p => p.re.test(text));
      if (coreHit) {
        const coreSel = document.getElementById('core');
        setSelectByText(coreSel, coreHit.value);
      }

      // Detect Comfort / Firmness
      const comfortSel = document.getElementById('comfort-level');
      if (comfortSel) {
        const lower = text.toLowerCase();
        const map = [
          { re: /\b(extra\s*firm)\b|firmness\s*:\s*extra\s*firm/i, val: 'Extra Firm' },
          { re: /\b(extra\s*plush)\b|firmness\s*:\s*extra\s*plush/i, val: 'Extra Plush' },
          { re: /\bfirm\b|firmness\s*:\s*firm/i, val: 'Firm' },
          { re: /\bmedium\b|firmness\s*:\s*medium/i, val: 'Medium' },
          { re: /\bplush\b|firmness\s*:\s*plush/i, val: 'Plush' }
        ];
        const hit = map.find(m => m.re.test(text));
        if (hit) setSelectByText(comfortSel, hit.val);
      }
    } catch (e) {}
  // Title is auto-filled by Inventory Name; do not set it from scrape
    try { const retailEl = document.getElementById('retail-price'); if (incoming.retailPrice && retailEl) retailEl.value = incoming.retailPrice; } catch (e) {}
    try { const priceEl = document.getElementById('price'); if (incoming.price && priceEl) priceEl.value = incoming.price; } catch (e) {}
    // Clear the incoming payload so it is used once
    await set({ ffm_incoming_listing: null });
  } catch (e) { console.debug('ffmPrefillFromSharetown error', e); }
})();

