// Prior default templates we want to migrate from (both content script and older popup versions)
const TEMPLATE_OLD_DEFAULTS = {
  Title: '{Inventory_Name} - {Size} - {Core}',
  Description_1: '{Inventory_Name} - {Condition}\nPrice: {Price} (Retail: {Retail_Price})\nSize: {Size} | Core: {Core} | Comfort: {Comfort}\n\nContact to arrange pickup.',
  Description_2: 'Selling {Inventory_Name} - {Condition}. Asking {Price}. In great condition. Local pickup only.',
  Description_3: '{Inventory_Name} - {Price}. Retail was {Retail_Price}. {Size} - {Core} - {Comfort}. Message me for details.',
  Description_4: '{Inventory_Name} - {Condition}. Clean, smoke-free home. {Price} or best offer. Pickup in person.',
  // Also include very old popup defaults so we upgrade those too
  __popup_old_1: 'Like new {Size} mattress. Price: ${Price}. Retail: ${Retail_Price}. Condition: {Condition}.',
  __popup_old_2: 'Selling a {Core} {Size} mattress. {Comfort} feel. Asking ${Price}.',
  __popup_old_3: '',
  __popup_old_4: ''
};

function loadTemplates(callback) {
  storageGet({ [TEMPLATE_STORAGE_KEY]: {} }, (res) => {
    const stored = (res && res[TEMPLATE_STORAGE_KEY]) ? res[TEMPLATE_STORAGE_KEY] : {};
    const map = Object.assign({}, TEMPLATE_DEFAULTS, stored);
    try {
      // Migrate only if user hasn't customized: i.e., stored equals a known old default
      let changed = false;
      const candidates = {
        Title: [TEMPLATE_OLD_DEFAULTS.Title],
        Description_1: [TEMPLATE_OLD_DEFAULTS.Description_1, TEMPLATE_OLD_DEFAULTS.__popup_old_1],
        Description_2: [TEMPLATE_OLD_DEFAULTS.Description_2, TEMPLATE_OLD_DEFAULTS.__popup_old_2],
        Description_3: [TEMPLATE_OLD_DEFAULTS.Description_3, TEMPLATE_OLD_DEFAULTS.__popup_old_3],
        Description_4: [TEMPLATE_OLD_DEFAULTS.Description_4, TEMPLATE_OLD_DEFAULTS.__popup_old_4]
      };
      Object.keys(candidates).forEach((k) => {
        const val = stored[k];
        if (typeof val === 'string' && candidates[k].some(oldVal => oldVal === val)) {
          map[k] = TEMPLATE_DEFAULTS[k];
          changed = true;
        }
      });
      if (changed) {
        saveTemplates(map, () => callback && callback(map));
        return;
      }
    } catch (e) { /* non-fatal */ }
    callback && callback(map);
  });
}

function saveTemplates(map, callback) {
  try {
    storageSet({ [TEMPLATE_STORAGE_KEY]: map }, () => {
      try { if (typeof callback === 'function') callback(); } catch (e) {}
      // Fire-and-forget upload to user-scoped S3 when available
      (async () => {
        try {
          const provider = await getCloudProvider();
          if (provider === 'aws') {
            const uid = window.ffmActiveUserId || await import('../popup_helpers.js').then(m => m.ffmGetActiveUserId()).catch(()=>null);
            if (uid) await uploadUserTemplatesToS3(uid).catch(e => console.debug('uploadUserTemplatesToS3 non-fatal', e));
          }
        } catch (e) { console.debug('saveTemplates upload hook error', e); }
      })();
    });
  } catch (e) { try { storageSet({ [TEMPLATE_STORAGE_KEY]: map }, callback); } catch(_) { if (typeof callback === 'function') callback(); } }
}

function populateTemplateSelect(map) { /* dropdown removed - nothing to populate */ }

function formatTemplate(tpl, ctx) {
  tpl = tpl || '';
  const canonical = {
    inventory_name: 'Inventory_Name',
    price: 'Price',
    retail_price: 'Retail_Price',
    condition: 'Condition',
    size: 'Size',
    core: 'Core',
    comfort: 'Comfort'
  };
  tpl = tpl.replace(/(?:\$\{|\{)\s*([A-Za-z0-9_]+)\s*[\)\]\}]?/gi, (m, k) => {
    const key = (k || '').toString().trim();
    const low = key.toLowerCase();
    if (canonical[low]) {
      if (key === key.toUpperCase()) return '{' + canonical[low] + ':UPPER}';
      return '{' + canonical[low] + '}';
    }
    return m;
  });
  return tpl.replace(/\{(Inventory_Name|Price|Retail_Price|Condition|Size|Core|Comfort)(:UPPER)?\}/g, (m, k, up) => {
    const val = (ctx[k] !== undefined && ctx[k] !== null) ? ctx[k] : '';
    return up ? ('' + val).toString().toUpperCase() : val;
  });
}

function buildPopupContext() {
  return {
    // Prefer the Inventory Name field when present so templates use the canonical name
    Inventory_Name: (inventoryNameInput && inventoryNameInput.value) ? inventoryNameInput.value : ((titleInput && titleInput.value) || ''),
    Price: (priceInput && priceInput.value) || '',
    Retail_Price: (retailPriceInput && retailPriceInput.value) || '',
    Condition: (conditionSelect && conditionSelect.value) || '',
    Size: (bedSizeSelect && bedSizeSelect.value) || '',
    Core: (coreSelect && coreSelect.value) || '',
    Comfort: (comfortSelect && comfortSelect.value) || ''
  };
}

