// Normalize a scraped description preserving paragraph breaks and simple lists.
function sanitizeScrapedDescription(raw) {
  try {
    if (!raw) return '';
    let s = String(raw);
    // If it looks like already plain text with newlines, collapse CRLF to LF and trim
    if (!/<[^>]+>/.test(s)) {
      s = s.replace(/\r\n?/g, '\n');
      // Trim trailing spaces on lines
      s = s.split('\n').map(l => l.replace(/\s+$/,'')).join('\n');
      // Collapse multiple blank lines to a maximum of two
      s = s.replace(/\n{3,}/g, '\n\n');
      return s.trim();
    }

    // Convert common block tags to newlines so textual paragraphs are preserved
    s = s.replace(/<br\s*\/?>/gi, '\n');
    s = s.replace(/<\/p>/gi, '\n\n');
    s = s.replace(/<\/div>/gi, '\n\n');
    s = s.replace(/<\/li>/gi, '\n');
    // Convert list item starts to bullet markers
    s = s.replace(/<li[^>]*>/gi, '- ');
    // Remove remaining tags
    s = s.replace(/<[^>]+>/g, '');
    // Decode basic HTML entities by leveraging a textarea element if available
    try {
      const ta = document.createElement('textarea');
      ta.innerHTML = s;
      s = ta.value;
    } catch (e) { /* ignore */ }
    // Normalize line endings
    s = s.replace(/\r\n?/g, '\n');
    // Trim spaces at end of lines
    s = s.split('\n').map(l => l.replace(/\s+$/,'')).join('\n');
    // Collapse repeated blank lines to at most two
    s = s.replace(/\n{3,}/g, '\n\n');
    // Trim leading/trailing whitespace
    return s.trim();
  } catch (e) { return (raw || '').toString(); }
}

// Extract a cleaned Inventory Name while preserving bed size and firmness
// Example: "Bear Elite Hybrid (1 King, Firmness: Firm)" -> "Bear Elite Hybrid King Firm"
function extractInventoryName(rawName) {
  if (!rawName) return "";

  // Always use the raw title, not the sanitized text
  let name = rawName.trim();

  // ✅ Capture bed size first (handles all "(1 Queen, ...)" and "(Queen)" variants)
  const bedMatch = name.match(/\(\s*\d*\s*(Cal(?:ifornia)?\s*King|King|Queen|Full|Twin(?:\s*XL)?|XL\s*Twin)\b/i);
  const bedSize = bedMatch ? bedMatch[1].replace(/California/i, "Cal").trim() : "";

  // ✅ Capture firmness, but ignore "Medium"
  const firmMatch = name.match(/Firmness:\s*([A-Za-z ]+)/i);
  let firmness = firmMatch ? firmMatch[1].trim() : "";
  if (/^medium$/i.test(firmness)) firmness = "";

  // ✅ Capture cover or top layer (optional add-on info)
  const coverMatch = name.match(/Cover:\s*([A-Za-z ]+)/i);
  const cover = coverMatch ? coverMatch[1].trim() : "";

  const topLayerMatch = name.match(/Top Layer:\s*([A-Za-z ]+)/i);
  const topLayer = topLayerMatch ? topLayerMatch[1].trim() : "";

  // ✅ Remove everything inside parentheses for the base product name
  const cleanName = name.replace(/\([^)]*\)/g, "").trim();

  // ✅ Compose in consistent order: [base] [size] [cover] [top layer] [firmness]
  const parts = [cleanName];
  if (bedSize) parts.push(bedSize);
  if (cover) parts.push(cover);
  if (topLayer) parts.push(topLayer);
  if (firmness) parts.push(firmness);

  return parts.join(" ").replace(/\s+/g, " ").trim();
}

// Insert a bed size token into an inventory-name input element if missing.
// Tries to insert before known core/comfort tokens, otherwise appends in parentheses.
function insertSizeIntoInventory(invEl, size) {
  try {
    if (!invEl || !size) return;
    const sizeStr = String(size || '').trim();
    if (!sizeStr) return;
    const invStr = String(invEl.value || '');
    const invLower = invStr.toLowerCase();
    // If already contains a size token, bail
    if (/\b(cal\s?king|california\s+king|king|queen|full|double|twin\s*xl|twinxl|twin)\b/i.test(invLower)) return;

    let newInv = invStr || '';
    let inserted = false;
    const coreTokens = ['hybrid','memory foam','memory-foam','memoryfoam','latex','inner spring','innerspring','spring'];
    for (const tok of coreTokens) {
      const re = new RegExp('\\b' + tok.replace(/[.*+?^${}()|[\\]\\]/g, '\\$&') + '\\b', 'i');
      const m = invStr.match(re);
      if (m && typeof m.index === 'number') {
        newInv = (invStr.slice(0, m.index).trim() + ' ' + sizeStr + ' ' + invStr.slice(m.index).trim()).replace(/\s+/g,' ').trim();
        inserted = true; break;
      }
    }
    if (!inserted) {
      const comfortTokens = ['extra firm','very firm','medium-firm','medium firm','medium','firm','plush','soft'];
      for (const tok of comfortTokens) {
        const re = new RegExp('\\b' + tok.replace(/[.*+?^${}()|[\\]\\]/g, '\\$&') + '\\b', 'i');
        const m = invStr.match(re);
        if (m && typeof m.index === 'number') {
          newInv = (invStr.slice(0, m.index).trim() + ' ' + sizeStr + ' ' + invStr.slice(m.index).trim()).replace(/\s+/g,' ').trim();
          inserted = true; break;
        }
      }
    }
    if (!inserted) newInv = (invStr + ' (' + sizeStr + ')').trim();
    invEl.value = newInv;
  } catch (e) { /* non-fatal */ }
}

// Infer detail fields from a title string for CLFS (Create-from-Sharetown)
function inferDetailsFromTitle(title) {
  try {
    if (!title || typeof title !== 'string') return {};
    // Normalize punctuation and separators to spaces so tokens are easier to match
    const t = title.toLowerCase().replace(/[\-_/\u2013\u2014()\[\],:]/g, ' ');
    const out = {};

    // Condition (conservative matches)
    if (/like\s*new/.test(t) || /like-new/.test(t) || /like_new/.test(t)) out.condition = 'Used - Like New';
    else if (/\bbrand\s*new\b/.test(t) || /\bnew\b/.test(t)) out.condition = 'New';

    // Bed size: allow an optional leading count/number (e.g., "1 King") and tolerate punctuation
    if (/\b(?:\d+\s*)?(?:cal\s?king|california\s+king)\b/.test(t)) out.bedSize = 'California King';
    else if (/\b(?:\d+\s*)?(?:king\s*size|king)\b/.test(t)) out.bedSize = 'King';
    else if (/\b(?:\d+\s*)?(?:queen)\b/.test(t)) out.bedSize = 'Queen';
    else if (/\b(?:\d+\s*)?(?:full|double)\b/.test(t)) out.bedSize = 'Full';
    else if (/\b(?:\d+\s*)?(?:twin\s*xl|twinxl|twin\s*x\s*l)\b/.test(t)) out.bedSize = 'Twin XL';
    else if (/\b(?:\d+\s*)?(?:twin)\b/.test(t)) out.bedSize = 'Twin';

    // Core
    if (/\bhybrid\b/.test(t)) out.core = 'Hybrid';
    else if (/memory\s*foam|memory-foam|memoryfoam/.test(t)) out.core = 'Memory Foam';
    else if (/\blatex\b/.test(t)) out.core = 'Latex';
    else if (/inner\s*spring|innerspring|\bspring\b/.test(t)) out.core = 'Innerspring';

    // Comfort: be explicit about Extra/Very so plain 'firm' or 'plush' doesn't overmatch
    if (/\bextra\s*firm\b/.test(t)) out.comfort = 'Extra Firm';
    else if (/\bvery\s*firm\b/.test(t)) out.comfort = 'Very Firm';
    else if (/\bmedium\s*-?\s*firm\b|\bmedium[- ]firm\b/.test(t)) out.comfort = 'Medium-Firm';
    else if (/\bfirm\b/.test(t)) out.comfort = 'Firm';

    if (/\bextra\s*plush\b/.test(t)) out.comfort = out.comfort || 'Extra Plush';
    else if (/\bplush\b/.test(t)) out.comfort = out.comfort || 'Plush';

    // other comfort synonyms
    if (!out.comfort) {
      if (/\bsoft\b/.test(t)) out.comfort = 'Soft';
      else if (/\bmedium\b/.test(t)) out.comfort = 'Medium';
    }

    return out;
  } catch (e) { return {}; }
}

// Set a select element's value by matching option label text (case-insensitive, substring)
function setSelectValueByLabel(selectEl, desiredLabel) {
  try {
    if (!selectEl || !desiredLabel) return false;
    const want = (desiredLabel || '').toString().toLowerCase();
    // 1) exact label match
    for (let i = 0; i < (selectEl.options || []).length; i++) {
      const opt = selectEl.options[i];
      const txt = (opt.text || opt.textContent || opt.label || '').toString().toLowerCase();
      const val = (opt.value || '').toString();
      if (!txt) continue;
      if (txt === want) {
        selectEl.value = val;
        try { selectEl.dispatchEvent && selectEl.dispatchEvent(new Event('change', { bubbles: true })); } catch (e) {}
        return true;
      }
    }
    // 2) whole-word label match (avoid matching 'extra firm' when want='firm')
    const wordRe = new RegExp('\\b' + want.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b');
    for (let i = 0; i < (selectEl.options || []).length; i++) {
      const opt = selectEl.options[i];
      const txt = (opt.text || opt.textContent || opt.label || '').toString().toLowerCase();
      const val = (opt.value || '').toString();
      if (!txt) continue;
      if (wordRe.test(txt)) {
        selectEl.value = val;
        try { selectEl.dispatchEvent && selectEl.dispatchEvent(new Event('change', { bubbles: true })); } catch (e) {}
        return true;
      }
    }
    // 3) substring fallback
    for (let i = 0; i < (selectEl.options || []).length; i++) {
      const opt = selectEl.options[i];
      const txt = (opt.text || opt.textContent || opt.label || '').toString().toLowerCase();
      const val = (opt.value || '').toString();
      if (!txt) continue;
      if (txt.indexOf(want) >= 0) {
        selectEl.value = val;
        try { selectEl.dispatchEvent && selectEl.dispatchEvent(new Event('change', { bubbles: true })); } catch (e) {}
        return true;
      }
    }
    // 4) fallback: try exact match on values
    for (let i = 0; i < (selectEl.options || []).length; i++) {
      const opt = selectEl.options[i];
      if ((opt.value || '').toString().toLowerCase() === want) {
        selectEl.value = opt.value;
        try { selectEl.dispatchEvent && selectEl.dispatchEvent(new Event('change', { bubbles: true })); } catch (e) {}
        return true;
      }
    }
    return false;
  } catch (e) { return false; }
}

function applySelectedTemplateToForm(templates) {
  try {
    // Choose template based on selected radio, default to Description_1
    let key = 'Description_1';
    try {
      if (descRadios.desc2 && descRadios.desc2.checked) key = 'Description_2';
      else if (descRadios.desc3 && descRadios.desc3.checked) key = 'Description_3';
      else if (descRadios.desc4 && descRadios.desc4.checked) key = 'Description_4';
      else key = 'Description_1';
    } catch (e) { key = 'Description_1'; }
    const tpl = templates[key] || TEMPLATE_DEFAULTS[key] || '';
    const ctx = buildPopupContext();
    const out = formatTemplate(tpl, ctx);
  if (descriptionInput && !descriptionManuallyEdited) descriptionInput.value = out;
    // also apply title: prefer Title template when present, otherwise fall back to Inventory Name
    // If the Title input is currently focused, don't overwrite it (user is actively editing)
    if (titleInput && document.activeElement === titleInput) {
      // skip title update while user is typing
    } else if (!titleManuallyEdited) {
      if (templates.Title) {
        const t = formatTemplate(templates.Title, ctx);
        if (titleInput) titleInput.value = t;
      } else {
        // if no Title template, and Inventory Name is present, use it as a sensible default
        try {
          const inv = (inventoryNameInput && inventoryNameInput.value) ? inventoryNameInput.value : '';
          if (inv && titleInput && (!titleInput.value || titleInput.value.trim() === '')) titleInput.value = inv;
        } catch (e) { /* best effort */ }
      }
    }
  } catch (e) { console.debug('applySelectedTemplateToForm error', e); }
}

