      // If this message came directly from a content script (sender.tab present),
      // ignore it here — the background will relay a single canonical refresh.
      try {
        if (sender && sender.tab) {
          console.debug('[popup] Ignoring direct ffm_refresh_popup from content script (background will relay)');
          return;
        }
      } catch (e) {}

      const now = Date.now();
      const last = window.__ffm_last_popup_refresh_ts || 0;
      const lastPublish = window.__ffm_last_publish_complete_ts || 0;

      // If we've just completed a publish, and we already refreshed once in that window,
